#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3

static volatile int keep_running = 1;
struct gpiod_chip *chip;
struct gpiod_line *line1, *line2;

void sigint_handler(int sig)
{
    keep_running = 0;
}

int main()
{
    struct gpiod_line_request_config config;
    int ret;

    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Open chip failed");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("Get line 1 failed");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("Get line 2 failed");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        return EXIT_FAILURE;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "gpio-test";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line1, &config, 0);
    if (ret < 0) {
        perror("Request line 1 as output failed");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request(line2, &config, 0);
    if (ret < 0) {
        perror("Request line 2 as output failed");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        ret = gpiod_line_set_value(line1, 1);
        if (ret < 0) {
            perror("Set line 1 value failed");
            break;
        }
        ret = gpiod_line_set_value(line2, 0);
        if (ret < 0) {
            perror("Set line 2 value failed");
            break;
        }
        printf("GPIO %d: 1, GPIO %d: 0\n", GPIO_PIN_1, GPIO_PIN_2);
        sleep(2);

        ret = gpiod_line_set_value(line1, 0);
        if (ret < 0) {
            perror("Set line 1 value failed");
            break;
        }
        ret = gpiod_line_set_value(line2, 1);
        if (ret < 0) {
            perror("Set line 2 value failed");
            break;
        }
        printf("GPIO %d: 0, GPIO %d: 1\n", GPIO_PIN_1, GPIO_PIN_2);
        sleep(2);
    }

    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_2 2
#define GPIO_3 3

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_2, PI_OUTPUT);
    gpioSetMode(GPIO_3, PI_OUTPUT);

    signal(SIGINT, signal_handler);

    while (!terminate) {
        gpioWrite(GPIO_2, 1);
        gpioWrite(GPIO_3, 0);
        printf("GPIO %d HIGH, GPIO %d LOW\n", GPIO_2, GPIO_3);
        gpioDelay(100000);

        gpioWrite(GPIO_2, 0);
        gpioWrite(GPIO_3, 1);
        printf("GPIO %d LOW, GPIO %d HIGH\n", GPIO_2, GPIO_3);
        gpioDelay(100000);
    }

    gpioWrite(GPIO_2, 0);
    gpioWrite(GPIO_3, 0);
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 2

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", rc);
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        if (gpioWrite(GPIO_PIN, 1) != 0) {
            fprintf(stderr, "Failed to write HIGH to GPIO %d\n", GPIO_PIN);
            gpioTerminate();
            return 1;
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN);
        sleep(5);

        if (gpioWrite(GPIO_PIN, 0) != 0) {
            fprintf(stderr, "Failed to write LOW to GPIO %d\n", GPIO_PIN);
            gpioTerminate();
            return 1;
        }
        printf("GPIO %d set to LOW\n", GPIO_PIN);
        sleep(5);
    }

    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <stdint.h>

// ADS1115 I2C address
#define ADS1115_ADDRESS 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define CONFIG_MUX_AIN0_GND 0x4000 // AIN0 to GND
#define CONFIG_PGA_4_096V 0x0000  // +/-4.096V range
#define CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define CONFIG_DR_128SPS 0x0060   // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_LOW 0x0000  // Active low comparator
#define CONFIG_COMP_LAT_NON 0x0000  // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

int i2c_fd;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting...\n");
    close(i2c_fd);
    exit(0);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Configure ADS1115
    uint16_t config = CONFIG_OS_SINGLE | CONFIG_MUX_AIN0_GND | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON | CONFIG_COMP_QUE_DISABLE;

    uint8_t write_buffer[3];
    write_buffer[0] = ADS1115_REG_CONFIG;
    write_buffer[1] = (config >> 8) & 0xFF; // MSB
    write_buffer[2] = config & 0xFF;        // LSB

    if (write(i2c_fd, write_buffer, 3) != 3) {
        perror("Error writing to I2C device");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        // Start single conversion
        config |= CONFIG_OS_SINGLE; // Ensure OS bit is set for single conversion
        write_buffer[0] = ADS1115_REG_CONFIG;
        write_buffer[1] = (config >> 8) & 0xFF; // MSB
        write_buffer[2] = config & 0xFF;        // LSB
        if (write(i2c_fd, write_buffer, 3) != 3) {
            perror("Error writing to I2C device");
            close(i2c_fd);
            return 1;
        }

        // Wait for conversion to complete (at least 8ms for 128 SPS)
        usleep(10000); // 10ms

        // Read conversion result
        uint8_t read_buffer[2];
        write_buffer[0] = ADS1115_REG_CONVERT;
        if (write(i2c_fd, write_buffer, 1) != 1) {
            perror("Error writing to I2C device");
            close(i2c_fd);
            return 1;
        }
        if (read(i2c_fd, read_buffer, 2) != 2) {
            perror("Error reading from I2C device");
            close(i2c_fd);
            return 1;
        }

        int16_t raw_value = (read_buffer[0] << 8) | read_buffer[1];

        // Print the raw value
        printf("Raw Value: %d\n", raw_value);

        // Wait 0.5 seconds
        usleep(500000);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX90614_ADDR 0x5A
#define MLX90614_TOBJ1 0x07

int i2c_fd = -1;

void signal_handler(int sig);
int read_mlx90614(int fd);

void signal_handler(int sig) {
    printf("\nExiting cleanly...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int read_mlx90614(int fd) {
    uint8_t buf[3];
    int16_t raw_temp;
    float temp_celsius;

    // Read temperature data (2 bytes) + dummy byte
    if (read(fd, buf, 3) != 3) {
        perror("Failed to read temperature data");
        return -1;
    }

    raw_temp = (buf[1] << 8) | buf[0];
    temp_celsius = (float)raw_temp * 0.02 - 273.15;

    return (int)(temp_celsius * 100); // Return as integer * 100
}

int main() {
    int result;
    struct sigaction sa;

    // Setup signal handler for Ctrl+C
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Write register address to be read
    uint8_t reg_addr = MLX90614_TOBJ1;
    if (write(i2c_fd, &reg_addr, 1) != 1) {
        perror("Failed to write register address");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        result = read_mlx90614(i2c_fd);
        if (result != -1) {
            printf("Temperature: %.2f °C\n", (float)result / 100.0);
        } else {
            fprintf(stderr, "Error reading temperature.\n");
        }
        sleep(5);
    }

    return 0;
}

