#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define GPIO_17 17
#define GPIO_18 18

static struct gpiod_chip *chip;
static struct gpiod_line *line17, *line18;

void cleanup(int signum) {
    printf("\nCleaning up and exiting...\n");
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_release(line18);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("Error getting GPIO 17");
        gpiod_chip_close(chip);
        return 1;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("Error getting GPIO 18");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output_flags(line17, NULL, GPIOD_LINE_REQUEST_FLAG_OPEN_DRAIN, 0) < 0) {
        perror("Error requesting GPIO 17 as output");
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output_flags(line18, NULL, GPIOD_LINE_REQUEST_FLAG_OPEN_DRAIN, 1) < 0) {
        perror("Error requesting GPIO 18 as output");
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO %d set to LOW\n", GPIO_17);
    printf("GPIO %d set to HIGH\n", GPIO_18);

    gpiod_line_release(line17);
    gpiod_line_release(line18);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int duty_cycle = 0;
    int result;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set GPIO 18 as PWM output */
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    /* Set PWM frequency */
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);

    /* Set PWM range */
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    /* Install signal handler */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("PWM control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        /* Update duty cycle */
        duty_cycle = (duty_cycle + 100) % (PWM_RANGE + 1);

        /* Set PWM duty cycle */
        result = gpioPWM(PWM_GPIO, duty_cycle);
        if (result != 0) {
            fprintf(stderr, "Error setting PWM duty cycle: %d\n", result);
            break;
        }

        /* Print current state */
        printf("GPIO %d: Duty Cycle = %d\n", PWM_GPIO, duty_cycle);

        /* Wait 0.5 seconds */
        gpioDelay(500000); // microseconds
    }

    /* Stop PWM */
    gpioPWM(PWM_GPIO, 0);

    /* Terminate pigpio */
    gpioTerminate();

    printf("PWM control stopped.\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Constants
#define SPEED_OF_SOUND 34300 // cm/s
#define MAX_DISTANCE 400      // cm
#define TIMEOUT_US 50000       // 50ms timeout

// Global variables
static volatile int running = 1;
static volatile unsigned int start_tick = 0;
static volatile unsigned int end_tick = 0;

// Function prototypes
void signal_handler(int signal);
void trigger_pulse();
double calculate_distance(unsigned int pulse_width);
void echo_callback(int gpio, int level, unsigned int tick);

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioTerminate();
    exit(0);
}

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us delay
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        start_tick = tick;
    } else if (level == 0) {
        end_tick = tick;
    }
}

// Function to calculate distance in centimeters
double calculate_distance(unsigned int pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Convert us to s and divide by 2
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set alert function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("HC-SR04 Distance Sensor Program\n");

    while (running) {
        // Trigger a measurement
        trigger_pulse();

        // Wait for the echo pulse to return or timeout
        unsigned int start_time = time(NULL);
        while ((end_tick == 0 || end_tick <= start_tick) && (time(NULL) - start_time) < 5) {
            gpioDelay(1000); // Check every 1ms
        }

        // Calculate pulse width
        unsigned int pulse_width = end_tick - start_tick;

        // Calculate distance
        double distance = calculate_distance(pulse_width);

        // Validate distance
        if (distance > 0 && distance <= MAX_DISTANCE) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: Invalid distance reading (%.2f cm)\n", distance);
        }

        // Reset ticks for next measurement
        start_tick = 0;
        end_tick = 0;

        // Wait 60 seconds
        gpioDelay(60000000); // 60 seconds in microseconds
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

