    printf("\nExiting...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write data to the I2C device
int i2c_write(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;      // LSB

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read data from the I2C device
int i2c_read(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to configure the ADS1115
int ads1115_configure(int fd) {
    uint16_t config = CONFIG_OS_SINGLE | CONFIG_MUX_AIN0_GND | CONFIG_PGA_4_096V |
                      CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD |
                      CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON | CONFIG_COMP_QUE_DISABLE;

    if (i2c_write(fd, ADS1115_REG_CONFIG, config) != 0) {
        fprintf(stderr, "Failed to configure ADS1115\n");
        return -1;
    }
    return 0;
}

// Function to read the ADC value from the ADS1115
int ads1115_read_adc(int fd, int16_t *adc_value) {
    uint16_t raw_value;

    // Start a single conversion
    if (i2c_write(fd, ADS1115_REG_CONFIG, CONFIG_OS_SINGLE | CONFIG_MUX_AIN0_GND | CONFIG_PGA_4_096V |
                  CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD |
                  CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON | CONFIG_COMP_QUE_DISABLE) != 0) {
        fprintf(stderr, "Failed to start conversion\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read the conversion result
    if (i2c_read(fd, ADS1115_REG_CONVERT, &raw_value) != 0) {
        fprintf(stderr, "Failed to read ADC value\n");
        return -1;
    }

    *adc_value = (int16_t)raw_value; // Convert to signed 16-bit integer
    return 0;
}

int main() {
    const char *i2c_device = "/dev/i2c-1"; // I2C device file
    int16_t adc_value;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Configure the ADS1115
    if (ads1115_configure(i2c_fd) != 0) {
        fprintf(stderr, "ADS1115 configuration failed\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read ADC value
        if (ads1115_read_adc(i2c_fd, &adc_value) == 0) {
            // Validate ADC reading
            if (adc_value >= -4096 && adc_value <= 4095) {
                printf("ADC Value: %d\n", adc_value);
            } else {
                fprintf(stderr, "Invalid ADC reading: %d\n", adc_value);
            }
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Close I2C device (this will never be reached in the infinite loop)
    close(i2c_fd);
    return 0;
}

