#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00

int main() {
    int fd;
    uint8_t buf[3];
    int16_t adc_value;

    // Open I2C bus
    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Specify slave address
    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return 1;
    }

    // Configure ADS1115 for single-ended A0, +/-4.096V, continuous conversion, 128 SPS
    uint16_t config = 0x4003; // Single-shot mode, AIN0, +/-4.096V, Continuous, 128 SPS
    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF;      // LSB

    if (write(fd, buf, 3) != 3) {
        perror("Error writing to I2C device");
        close(fd);
        return 1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read conversion register
    buf[0] = CONVERSION_REG;
    if (write(fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        close(fd);
        return 1;
    }

    if (read(fd, buf, 2) != 2) {
        perror("Error reading from I2C device");
        close(fd);
        return 1;
    }

    adc_value = (buf[0] << 8) | buf[1];

    printf("ADC Value: %d\n", adc_value);

    close(fd);
    return 0;
}

