#define GPIO_PIN_2 3

static volatile int keep_running = 1;
struct gpiod_chip *chip;
struct gpiod_line *line1, *line2;

void sigint_handler(int sig)
{
    keep_running = 0;
}

int main()
{
    struct gpiod_line_request_config config;
    int ret;

    // Register signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO lines
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line1 || !line2) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure line request
    memset(&config, 0, sizeof(config));
    config.consumer = "digital_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    // Request GPIO lines for output
    ret = gpiod_line_request(line1, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 1");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request(line2, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 2");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        // Set GPIO 2 high, GPIO 3 low
        ret = gpiod_line_set_value(line1, 1);
        if (ret < 0) {
            perror("Error setting GPIO 2 value");
            break;
        }
        ret = gpiod_line_set_value(line2, 0);
        if (ret < 0) {
            perror("Error setting GPIO 3 value");
            break;
        }
        printf("GPIO %d: HIGH, GPIO %d: LOW\n", GPIO_PIN_1, GPIO_PIN_2);
        sleep(5);

        // Set GPIO 2 low, GPIO 3 high
        ret = gpiod_line_set_value(line1, 0);
        if (ret < 0) {
            perror("Error setting GPIO 2 value");
            break;
        }
        ret = gpiod_line_set_value(line2, 1);
        if (ret < 0) {
            perror("Error setting GPIO 3 value");
            break;
        }
        printf("GPIO %d: LOW, GPIO %d: HIGH\n", GPIO_PIN_1, GPIO_PIN_2);
        sleep(5);
    }

    // Release GPIO lines and close chip
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 17

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

int main() {
    int i, rc;
    unsigned int seed;
    struct timespec ts;

    /* Install signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set GPIO pin as output */
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    /* Seed the random number generator */
    clock_gettime(CLOCK_REALTIME, &ts);
    seed = ts.tv_nsec;
    srand(seed);

    printf("Starting GPIO control loop...\n");

    while (!terminate) {
        /* Generate a random number between 0 and 1 */
        double random_value = (double)rand() / RAND_MAX;

        /* Determine the GPIO state based on the random value */
        int gpio_state = (random_value > 0.5) ? 1 : 0;

        /* Apply the state to the GPIO pin */
        rc = gpioWrite(GPIO_PIN, gpio_state);
        if (rc != 0) {
            fprintf(stderr, "Error writing to GPIO %d: %d\n", GPIO_PIN, rc);
            break; // Exit loop on error
        }

        /* Print the applied state */
        printf("Applied state: %d\n", gpio_state);

        /* Wait for 1 second */
        sleep(1);
    }

    /* Release GPIO resources */
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

