#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI7021_ADDR 0x40
#define MEASURE_TEMP_CMD 0xE3
#define MEASURE_HUMID_CMD 0xE5
#define TEMP_MIN -40.0
#define TEMP_MAX 85.0
#define HUMID_MIN 0.0
#define HUMID_MAX 100.0

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_setup(const char *bus);
int si7021_read_temperature(int fd, float *temperature);
int si7021_read_humidity(int fd, float *humidity);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// I2C setup function
int i2c_setup(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read temperature from SI7021
int si7021_read_temperature(int fd, float *temperature) {
    uint8_t cmd = MEASURE_TEMP_CMD;
    uint8_t data[2];
    int retries = 3;

    while (retries > 0) {
        if (write(fd, &cmd, 1) != 1) {
            perror("Error writing temperature command");
            retries--;
            usleep(10000); // Wait before retrying
            continue;
        }

        usleep(50000); // Wait for conversion (50ms)

        if (read(fd, data, 2) != 2) {
            perror("Error reading temperature data");
            retries--;
            usleep(10000); // Wait before retrying
            continue;
        }

        uint16_t raw_temp = (data[0] << 8) | data[1];
        *temperature = (175.72 * raw_temp / 65536.0) - 46.85;

        // Validity check
        if (*temperature < TEMP_MIN || *temperature > TEMP_MAX) {
            fprintf(stderr, "Error: Invalid temperature reading: %.2f\n", *temperature);
            return -1;
        }

        return 0; // Success
    }

    fprintf(stderr, "Error: Failed to read temperature after multiple retries.\n");
    return -1; // Failure
}

// Function to read humidity from SI7021
int si7021_read_humidity(int fd, float *humidity) {
    uint8_t cmd = MEASURE_HUMID_CMD;
    uint8_t data[2];
    int retries = 3;

    while (retries > 0) {
        if (write(fd, &cmd, 1) != 1) {
            perror("Error writing humidity command");
            retries--;
            usleep(10000); // Wait before retrying
            continue;
        }

        usleep(50000); // Wait for conversion (50ms)

        if (read(fd, data, 2) != 2) {
            perror("Error reading humidity data");
            retries--;
            usleep(10000); // Wait before retrying
            continue;
        }

        uint16_t raw_humidity = (data[0] << 8) | data[1];
        *humidity = (125.0 * raw_humidity / 65536.0) - 6.0;

        // Validity check
        if (*humidity < HUMID_MIN || *humidity > HUMID_MAX) {
            fprintf(stderr, "Error: Invalid humidity reading: %.2f\n", *humidity);
            return -1;
        }

        return 0; // Success
    }

    fprintf(stderr, "Error: Failed to read humidity after multiple retries.\n");
    return -1; // Failure
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup(I2C_BUS);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    float temperature, humidity;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Main loop
    while (!terminate) {
        // Read temperature
        if (si7021_read_temperature(i2c_fd, &temperature) == 0) {
            // Read humidity
            if (si7021_read_humidity(i2c_fd, &humidity) == 0) {
                // Get current timestamp
                time(&current_time);
                time_info = localtime(&current_time);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

                // Print the readings with timestamp
                printf("%s Temperature: %.2f °C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
            } else {
                fprintf(stderr, "Failed to read humidity.\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        sleep(5);
    }

    // Close I2C connection
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00

int main() {
    int fd;
    unsigned char buf[3];
    short adc_value;

    // Open I2C bus
    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return 1;
    }

    // Configure ADS1115 for single-ended A0, +/-4.096V, continuous conversion, 128 SPS
    buf[0] = CONFIG_REG;
    buf[1] = 0xC2; // MSB: 11000010 (Single-shot, AIN0, +/-4.096V)
    buf[2] = 0x83; // LSB: 10000011 (128 SPS, Disable comparator)

    if (write(fd, buf, 3) != 3) {
        perror("Error writing to ADS1115 configuration register");
        close(fd);
        return 1;
    }

    // Read ADC value three times with 1-second delay
    for (int i = 0; i < 3; i++) {
        // Start single conversion by writing to config register again
        buf[0] = CONFIG_REG;
        buf[1] = 0x82; // Start single conversion
        buf[2] = 0x83;
        if (write(fd, buf, 3) != 3) {
            perror("Error starting conversion");
            close(fd);
            return 1;
        }

        usleep(100000); // Wait for conversion (at least 8ms for 128 SPS)

        // Read conversion register
        buf[0] = CONVERSION_REG;
        if (write(fd, buf, 1) != 1) {
            perror("Error writing to conversion register");
            close(fd);
            return 1;
        }

        if (read(fd, buf, 2) != 2) {
            perror("Error reading from conversion register");
            close(fd);
            return 1;
        }

        adc_value = (buf[0] << 8) | buf[1];
        printf("ADC Value: %d\n", adc_value);

        sleep(1);
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define GPIO_8 8
#define GPIO_9 9
#define GPIO_10 10
#define GPIO_11 11
#define GPIO_23 23
#define GPIO_24 24

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variable for GPIO chip
struct gpiod_chip *chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

// Function to set the state of a GPIO pin
int set_gpio_state(struct gpiod_line *line, int value)
{
    int ret;
    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %d\n", ret);
        return -1;
    }
    return 0;
}

// Function to get the state of a GPIO pin
int get_gpio_state(struct gpiod_line *line)
{
    int value;
    int ret = gpiod_line_get_value(line);
    if (ret < 0) {
        fprintf(stderr, "Error getting GPIO value: %d\n", ret);
        return -1;
    }
    value = ret;
    return value;
}

// Function to report the state of all GPIO pins
void report_gpio_states(struct gpiod_line *line8, struct gpiod_line *line9, struct gpiod_line *line10, struct gpiod_line *line11, struct gpiod_line *line23, struct gpiod_line *line24)
{
    int val8 = get_gpio_state(line8);
    int val9 = get_gpio_state(line9);
    int val10 = get_gpio_state(line10);
    int val11 = get_gpio_state(line11);
    int val23 = get_gpio_state(line23);
    int val24 = get_gpio_state(line24);

    if (val8 == -1 || val9 == -1 || val10 == -1 || val11 == -1 || val23 == -1 || val24 == -1) {
        fprintf(stderr, "Error reading GPIO states.\n");
        return;
    }

    printf("GPIO 8: %d, GPIO 9: %d, GPIO 10: %d, GPIO 11: %d, GPIO 23: %d, GPIO 24: %d\n",
           val8, val9, val10, val11, val23, val24);
}

int main()
{
    struct gpiod_line *line8, *line9, *line10, *line11, *line23, *line24;
    int i;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line8 = gpiod_chip_get_line(chip, GPIO_8);
    line9 = gpiod_chip_get_line(chip, GPIO_9);
    line10 = gpiod_chip_get_line(chip, GPIO_10);
    line11 = gpiod_chip_get_line(chip, GPIO_11);
    line23 = gpiod_chip_get_line(chip, GPIO_23);
    line24 = gpiod_chip_get_line(chip, GPIO_24);

    if (!line8 || !line9 || !line10 || !line11 || !line23 || !line24) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines as outputs
    if (gpiod_line_request_output(line8, "my_program", 0) < 0 ||
        gpiod_line_request_output(line9, "my_program", 0) < 0 ||
        gpiod_line_request_output(line10, "my_program", 0) < 0 ||
        gpiod_line_request_output(line11, "my_program", 0) < 0 ||
        gpiod_line_request_output(line23, "my_program", 0) < 0 ||
        gpiod_line_request_output(line24, "my_program", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    for (i = 0; i < 256; i++) {
        // Set GPIO 8 high
        if (set_gpio_state(line8, 1) < 0) {
            fprintf(stderr, "Error setting GPIO 8 high.\n");
            break;
        }
        // Set GPIO 9 low
        if (set_gpio_state(line9, 0) < 0) {
            fprintf(stderr, "Error setting GPIO 9 low.\n");
            break;
        }
        // Set GPIO 10 high
        if (set_gpio_state(line10, 1) < 0) {
            fprintf(stderr, "Error setting GPIO 10 high.\n");
            break;
        }
        // Set GPIO 11 low
        if (set_gpio_state(line11, 0) < 0) {
            fprintf(stderr, "Error setting GPIO 11 low.\n");
            break;
        }
        // Set GPIO 23 high
        if (set_gpio_state(line23, 1) < 0) {
            fprintf(stderr, "Error setting GPIO 23 high.\n");
            break;
        }
        // Set GPIO 24 low
        if (set_gpio_state(line24, 0) < 0) {
            fprintf(stderr, "Error setting GPIO 24 low.\n");
            break;
        }

        report_gpio_states(line8, line9, line10, line11, line23, line24);
        usleep(100000); // 100ms

        // Set GPIO 8 low
        if (set_gpio_state(line8, 0) < 0) {
            fprintf(stderr, "Error setting GPIO 8 low.\n");
            break;
        }
        // Set GPIO 9 high
        if (set_gpio_state(line9, 1) < 0) {
            fprintf(stderr, "Error setting GPIO 9 high.\n");
            break;
        }
        // Set GPIO 10 low
        if (set_gpio_state(line10, 0) < 0) {
            fprintf(stderr, "Error setting GPIO 10 low.\n");
            break;
        }
        // Set GPIO 11 high
        if (set_gpio_state(line11, 1) < 0) {
            fprintf(stderr, "Error setting GPIO 11 high.\n");
            break;
        }
        // Set GPIO 23 low
        if (set_gpio_state(line23, 0) < 0) {
            fprintf(stderr, "Error setting GPIO 23 low.\n");
            break;
        }
        // Set GPIO 24 high
        if (set_gpio_state(line24, 1) < 0) {
            fprintf(stderr, "Error setting GPIO 24 high.\n");
            break;
        }

        report_gpio_states(line8, line9, line10, line11, line23, line24);
        usleep(100000); // 100ms
    }

    // Release GPIO lines
    gpiod_line_release(line8);
    gpiod_line_release(line9);
    gpiod_line_release(line10);
    gpiod_line_release(line11);
    gpiod_line_release(line23);
    gpiod_line_release(line24);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

