#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define GPIO_17 17
#define GPIO_18 18
#define GPIO_27 27

static volatile int keep_running = 1;
struct gpiod_chip *chip;
struct gpiod_line *line17, *line18, *line27;

void sigint_handler(int sig)
{
    keep_running = 0;
}

int main()
{
    struct gpiod_line_request_config config;
    int ret;

    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Open chip failed");
        return 1;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    line18 = gpiod_chip_get_line(chip, GPIO_18);
    line27 = gpiod_chip_get_line(chip, GPIO_27);

    if (!line17 || !line18 || !line27) {
        perror("Get line failed");
        goto cleanup_chip;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "digital_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line17, &config, 0);
    if (ret < 0) {
        perror("Request line 17 as output failed");
        goto cleanup_lines;
    }
    ret = gpiod_line_request(line18, &config, 0);
    if (ret < 0) {
        perror("Request line 18 as output failed");
        goto cleanup_lines;
    }
    ret = gpiod_line_request(line27, &config, 0);
    if (ret < 0) {
        perror("Request line 27 as output failed");
        goto cleanup_lines;
    }

    while (keep_running) {
        ret = gpiod_line_set_value(line17, 1);
        ret |= gpiod_line_set_value(line18, 0);
        ret |= gpiod_line_set_value(line27, 1);
        if (ret < 0) {
            perror("Set value failed");
            break;
        }
        printf("GPIO %d: HIGH, GPIO %d: LOW, GPIO %d: HIGH\n", GPIO_17, GPIO_18, GPIO_27);
        usleep(50000);

        ret = gpiod_line_set_value(line17, 0);
        ret |= gpiod_line_set_value(line18, 1);
        ret |= gpiod_line_set_value(line27, 0);
        if (ret < 0) {
            perror("Set value failed");
            break;
        }
        printf("GPIO %d: LOW, GPIO %d: HIGH, GPIO %d: LOW\n", GPIO_17, GPIO_18, GPIO_27);
        usleep(50000);
    }

cleanup_lines:
    gpiod_line_release(line17);
    gpiod_line_release(line18);
    gpiod_line_release(line27);

cleanup_chip:
    gpiod_chip_close(chip);

    return 0;
}

