#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_2 2
#define GPIO_3 3

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int result;
    int gpio_state;

    /* Register signal handler */
    signal(SIGINT, signal_handler);

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set GPIO 2 as output */
    gpioSetMode(GPIO_2, PI_OUTPUT);
    /* Set GPIO 3 as output */
    gpioSetMode(GPIO_3, PI_OUTPUT);

    printf("GPIO control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        /* Toggle GPIO 2 and GPIO 3 */
        gpio_state = gpioRead(GPIO_2);
        if (gpio_state == 0) {
            result = gpioWrite(GPIO_2, 1);
            if (result != 0) {
                fprintf(stderr, "Error writing to GPIO %d: %d\n", GPIO_2, result);
                break;
            }
            result = gpioWrite(GPIO_3, 0);
            if (result != 0) {
                fprintf(stderr, "Error writing to GPIO %d: %d\n", GPIO_3, result);
                break;
            }
        } else {
            result = gpioWrite(GPIO_2, 0);
            if (result != 0) {
                fprintf(stderr, "Error writing to GPIO %d: %d\n", GPIO_2, result);
                break;
            }
            result = gpioWrite(GPIO_3, 1);
            if (result != 0) {
                fprintf(stderr, "Error writing to GPIO %d: %d\n", GPIO_3, result);
                break;
            }
        }

        /* Print the current state */
        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_2, gpioRead(GPIO_2), GPIO_3, gpioRead(GPIO_3));

        /* Wait for 0.5 seconds */
        time_sleep(0.5);
    }

    /* Clean up and exit */
    gpioTerminate();
    printf("GPIO control stopped.\n");
    return 0;
}

