#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define NUM_GPIOS 4

static struct gpiod_chip *chip;
static struct gpiod_line *lines[NUM_GPIOS];
static int line_numbers[NUM_GPIOS] = {8, 9, 10, 11};
static volatile sig_atomic_t terminate;

void signal_handler(int sig)
{
    terminate = 1;
}

int main()
{
    int i, ret;
    struct gpiod_line_request_config config;

    /* Initialize signal handling */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    /* Get lines */
    for (i = 0; i < NUM_GPIOS; i++) {
        lines[i] = gpiod_chip_get_line(chip, line_numbers[i]);
        if (!lines[i]) {
            perror("Error getting GPIO line");
            goto cleanup;
        }
    }

    /* Request lines as outputs */
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio-output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    for (i = 0; i < NUM_GPIOS; i++) {
        ret = gpiod_line_request(lines[i], &config, 0);
        if (ret < 0) {
            perror("Error requesting GPIO line as output");
            goto cleanup;
        }
    }

    /* Main loop */
    while (!terminate) {
        for (i = 0; i < NUM_GPIOS; i++) {
            ret = gpiod_line_set_value(lines[i], 1);
            if (ret < 0) {
                perror("Error setting GPIO value");
                goto cleanup;
            }
        }
        printf("GPIOs set HIGH\n");
        usleep(100000); // 0.1 seconds

        for (i = 0; i < NUM_GPIOS; i++) {
            ret = gpiod_line_set_value(lines[i], 0);
            if (ret < 0) {
                perror("Error setting GPIO value");
                goto cleanup;
            }
        }
        printf("GPIOs set LOW\n");
        usleep(100000); // 0.1 seconds
    }

cleanup:
    /* Release lines */
    for (i = 0; i < NUM_GPIOS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    /* Close chip */
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

