#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Constants
#define SPEED_OF_SOUND 34300 // cm/s
#define MAX_DISTANCE 400      // cm
#define TIMEOUT_US 50000       // 50ms timeout

// Global variables
static volatile int running = 1;

// Function prototypes
void signal_handler(int signal);
double measure_distance();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to measure distance using HC-SR04
double measure_distance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Measure echo pulse width
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Error: Timeout waiting for echo start.\n");
            return -1.0; // Indicate timeout error
        }
    }

    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Error: Timeout waiting for echo end.\n");
            return -1.0; // Indicate timeout error
        }
    }
    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    double time_taken = (double)diff_tick / 1000000.0; // Time in seconds
    double distance = (time_taken * SPEED_OF_SOUND) / 2.0;

    return distance;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("HC-SR04 Distance Sensor Program\n");

    // Main loop
    while (running) {
        double distance = measure_distance();

        if (distance >= 0 && distance <= MAX_DISTANCE) {
            printf("Distance: %.2f cm\n", distance);
        } else if (distance < 0) {
            fprintf(stderr, "Error: Invalid distance reading.\n");
        } else {
            fprintf(stderr, "Error: Distance out of range (%.2f cm).\n", distance);
        }

        time_sleep(1.0); // Wait for 1 second
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

