    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    time(&start_time);

    for (i = 0; i < 5 && !terminate; ++i) {
        // Generate a random state (0 or 1)
        state = rand() % 2;

        // Apply the state to the GPIO pin
        gpioWrite(GPIO_PIN, state);

        // Print the state to stdout
        printf("%d\n", state);

        // Wait for 1 second
        sleep(1);

        time(&current_time);
        elapsed_time = difftime(current_time, start_time);

        if (elapsed_time > 5) {
            fprintf(stderr, "Timeout: Program ran for more than 5 seconds.\n");
            break;
        }
    }

    // Release GPIO pin and terminate pigpio
    gpioTerminate();

    printf("Program finished.\n");
    return 0;
}

