#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3

static volatile int keep_running = 1;
struct gpiod_chip *chip;
struct gpiod_line *line1, *line2;

void sigint_handler(int sig)
{
    keep_running = 0;
}

int main()
{
    struct gpiod_line_request_config config;
    int ret;

    // Register signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line for pin 2
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("Error getting GPIO line for pin 2");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get GPIO line for pin 3
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("Error getting GPIO line for pin 3");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        return EXIT_FAILURE;
    }

    // Configure GPIO lines as outputs
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio-output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line1, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for pin 2 as output");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request(line2, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for pin 3 as output");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        // Set GPIO 2 high, GPIO 3 low
        ret = gpiod_line_set_value(line1, 1);
        if (ret < 0) {
            perror("Error setting GPIO 2 high");
        }
        ret = gpiod_line_set_value(line2, 0);
        if (ret < 0) {
            perror("Error setting GPIO 3 low");
        }
        printf("GPIO 2: HIGH, GPIO 3: LOW\n");

        sleep(5);

        // Set GPIO 2 low, GPIO 3 high
        ret = gpiod_line_set_value(line1, 0);
        if (ret < 0) {
            perror("Error setting GPIO 2 low");
        }
        ret = gpiod_line_set_value(line2, 1);
        if (ret < 0) {
            perror("Error setting GPIO 3 high");
        }
        printf("GPIO 2: LOW, GPIO 3: HIGH\n");

        sleep(5);
    }

    // Release GPIO lines and close chip
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

