#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define DHT11_GPIO 4

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

int read_dht11(int gpio_pin, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int byte_index = 0;
    unsigned int start_time, end_time, pulse_length;

    gpioSetMode(gpio_pin, PI_OUTPUT);
    gpioWrite(gpio_pin, 0);
    gpioDelay(18); // > 18ms
    gpioWrite(gpio_pin, 1);
    gpioDelay(20); // 20us
    gpioSetMode(gpio_pin, PI_INPUT);

    /* Wait for the DHT11 to pull the line low */
    int timeout = 0;
    while (gpioRead(gpio_pin) == 1 && timeout < 100) {
        gpioDelay(1); // Check every 1 us
        timeout++;
    }
    if (timeout >= 100) {
        fprintf(stderr, "DHT11: Timeout waiting for start signal (low)\n");
        return -1;
    }

    /* Wait for the DHT11 to pull the line high */
    timeout = 0;
    while (gpioRead(gpio_pin) == 0 && timeout < 100) {
        gpioDelay(1); // Check every 1 us
        timeout++;
    }
    if (timeout >= 100) {
        fprintf(stderr, "DHT11: Timeout waiting for start signal (high)\n");
        return -1;
    }

    /* Read 40 bits of data */
    for (int i = 0; i < 40; i++) {
        /* Wait for the line to go low */
        timeout = 0;
        while (gpioRead(gpio_pin) == 1 && timeout < 100) {
            gpioDelay(1); // Check every 1 us
            timeout++;
        }
        if (timeout >= 100) {
            fprintf(stderr, "DHT11: Timeout waiting for data bit start (low)\n");
            return -1;
        }

        /* Measure the length of the high pulse */
        start_time = gpioTick();
        timeout = 0;
        while (gpioRead(gpio_pin) == 0 && timeout < 100) {
            gpioDelay(1); // Check every 1 us
            timeout++;
        }
        if (timeout >= 100) {
            fprintf(stderr, "DHT11: Timeout waiting for data bit end (low)\n");
            return -1;
        }
        end_time = gpioTick();
        pulse_length = end_time - start_time;

        /* Determine if it's a 0 or a 1 based on pulse length */
        if (pulse_length > 30) { // Empirical value, adjust as needed
            data[byte_index] |= (1 << (7 - bit_count));
        }

        bit_count++;
        if (bit_count == 8) {
            bit_count = 0;
            byte_index++;
        }
    }

    /* Validate checksum */
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        fprintf(stderr, "DHT11: Checksum failure\n");
        return -1;
    }

    *humidity = (float)data[0];
    *temperature = (float)data[2];

    return 0;
}

int main() {
    float temperature, humidity;
    int result;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    result = read_dht11(DHT11_GPIO, &temperature, &humidity);

    if (result == 0) {
        printf("Temperature: %.1f °C, Humidity: %.1f %%\n", temperature, humidity);
    } else {
        fprintf(stderr, "Failed to read DHT11 sensor\n");
        gpioTerminate();
        return 1;
    }

    gpioTerminate();
    return 0;
}

