    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);

    if (!line1 || !line2) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines as outputs
    ret = gpiod_line_request_output(line1, NULL, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line2, NULL, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop: 3 cycles of 5 seconds each
