#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define NUM_GPIOS 9

static struct gpiod_chip *chip;
static struct gpiod_line *lines[NUM_GPIOS];
static int running = 1;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int sig)
{
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
    running = 0;
}

// Function to set the value of a GPIO line
int set_gpio_value(struct gpiod_line *line, int value)
{
    return gpiod_line_set_value(line, value);
}

// Function to get the value of a GPIO line
int get_gpio_value(struct gpiod_line *line)
{
    return gpiod_line_get_value(line);
}

int main()
{
    int i;
    int values[NUM_GPIOS] = {0}; // Initial values: all LOW
    int ret;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get the lines for the specified GPIOs
    int gpios[] = {2, 3, 4, 5, 6, 7, 8, 9, 17};
    for (i = 0; i < NUM_GPIOS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpios[i]);
        if (!lines[i]) {
            perror("Error getting GPIO line");
            goto cleanup;
        }

        // Request the lines as outputs
        ret = gpiod_line_request_output(lines[i], "my_program", 0);
        if (ret < 0) {
            perror("Error requesting GPIO line as output");
            goto cleanup;
        }
    }

    // Main loop
    while (running) {
        // Toggle the values
        for (i = 0; i < NUM_GPIOS; i++) {
            values[i] = !values[i];
            ret = set_gpio_value(lines[i], values[i]);
            if (ret < 0) {
                perror("Error setting GPIO value");
                goto cleanup;
            }
        }

        // Print the current state
        printf("GPIO States: ");
        for (i = 0; i < NUM_GPIOS; i++) {
            printf("%d ", get_gpio_value(lines[i]));
        }
        printf("\n");

        // Wait for 0.05 seconds
        usleep(50000); // 50000 microseconds = 0.05 seconds
    }

cleanup:
    // Release the lines
    for (i = 0; i < NUM_GPIOS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close the chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_FAILURE;
}

