#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>

#define OPT3001_I2C_ADDR 0x44
#define RESULT_REG 0x00

int main() {
    int file;
    char filename[20];
    uint8_t buffer[2];
    uint16_t raw_result;
    float result;

    // Open I2C device file
    snprintf(filename, 19, "/dev/i2c-1");
    file = open(filename, O_RDWR);
    if (file < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Specify slave address
    if (ioctl(file, I2C_SLAVE, OPT3001_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return EXIT_FAILURE;
    }

    // Read two bytes from register 0x00
    if (read(file, buffer, 2) != 2) {
        perror("Failed to read from the i2c bus");
        close(file);
        return EXIT_FAILURE;
    }

    // Combine the bytes into a 16-bit value
    raw_result = (buffer[0] << 8) | buffer[1];

    // Extract exponent and result
    int exponent = (raw_result >> 12) & 0x0F;
    int mantissa = raw_result & 0x0FFF;

    // Calculate the result
    result = mantissa * (0.01 * (1 << exponent));

    // Print the result
    printf("OPT3001 Result: %.2f\n", result);

    // Close the I2C device
    close(file);

    return EXIT_SUCCESS;
}

