static struct gpiod_chip *chip;
static struct gpiod_line *line1, *line2;

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to set the value of a GPIO line
int set_gpio_value(struct gpiod_line *line, int value)
{
    if (!line) {
        fprintf(stderr, "Error: Invalid GPIO line.\n");
        return -1;
    }

    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Error setting GPIO value");
        return -1;
    }

    return 0;
}

int main()
{
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);

    if (!line1 || !line2) {
        fprintf(stderr, "Error getting GPIO line.\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line1, NULL, 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line2, NULL, 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 2 HIGH
        if (set_gpio_value(line1, 1) == 0) {
            printf("GPIO %d set to HIGH\n", GPIO_PIN_1);
        } else {
            fprintf(stderr, "Failed to set GPIO %d HIGH\n", GPIO_PIN_1);
        }

        // Set GPIO 3 LOW
        if (set_gpio_value(line2, 0) == 0) {
            printf("GPIO %d set to LOW\n", GPIO_PIN_2);
        } else {
            fprintf(stderr, "Failed to set GPIO %d LOW\n", GPIO_PIN_2);
        }

        sleep(1);

        // Set GPIO 2 LOW
        if (set_gpio_value(line1, 0) == 0) {
            printf("GPIO %d set to LOW\n", GPIO_PIN_1);
        } else {
            fprintf(stderr, "Failed to set GPIO %d LOW\n", GPIO_PIN_1);
        }

        // Set GPIO 3 HIGH
        if (set_gpio_value(line2, 1) == 0) {
            printf("GPIO %d set to HIGH\n", GPIO_PIN_2);
        } else {
            fprintf(stderr, "Failed to set GPIO %d HIGH\n", GPIO_PIN_2);
        }

        sleep(1);
    }

    // Cleanup (should not reach here in normal execution due to the infinite loop)
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return 0;
}

