#include <signal.h>
#include <pigpio.h>

#define GPIO_17 17
#define GPIO_22 22
#define GPIO_27 27

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int result;

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set GPIO pins as outputs */
    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_22, PI_OUTPUT);
    gpioSetMode(GPIO_27, PI_OUTPUT);

    /* Register signal handler for graceful shutdown */
    signal(SIGINT, signal_handler);

    while (!terminate) {
        /* Set GPIO 17 HIGH */
        result = gpioWrite(GPIO_17, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing to GPIO %d: %d\n", GPIO_17, result);
            break;
        }
        /* Set GPIO 22 LOW */
        result = gpioWrite(GPIO_22, 0);
        if (result != 0) {
            fprintf(stderr, "Error writing to GPIO %d: %d\n", GPIO_22, result);
            break;
        }
        /* Set GPIO 27 HIGH */
        result = gpioWrite(GPIO_27, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing to GPIO %d: %d\n", GPIO_27, result);
            break;
        }

        printf("GPIO %d: HIGH, GPIO %d: LOW, GPIO %d: HIGH\n", GPIO_17, GPIO_22, GPIO_27);
        gpioDelay(100000); // 0.1 seconds

        /* Set GPIO 17 LOW */
        result = gpioWrite(GPIO_17, 0);
        if (result != 0) {
            fprintf(stderr, "Error writing to GPIO %d: %d\n", GPIO_17, result);
            break;
        }
        /* Set GPIO 22 HIGH */
        result = gpioWrite(GPIO_22, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing to GPIO %d: %d\n", GPIO_22, result);
            break;
        }
        /* Set GPIO 27 LOW */
        result = gpioWrite(GPIO_27, 0);
        if (result != 0) {
            fprintf(stderr, "Error writing to GPIO %d: %d\n", GPIO_27, result);
            break;
        }

        printf("GPIO %d: LOW, GPIO %d: HIGH, GPIO %d: LOW\n", GPIO_17, GPIO_22, GPIO_27);
        gpioDelay(100000); // 0.1 seconds
    }

    /* Release GPIO pins */
    gpioSetMode(GPIO_17, PI_INPUT);
    gpioSetMode(GPIO_22, PI_INPUT);
    gpioSetMode(GPIO_27, PI_INPUT);

    /* Terminate pigpio library */
    gpioTerminate();

    return 0;
}

