#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for PWM output
#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 27

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

int main()
{
    // Register signal handlers for SIGINT and SIGTERM
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Could not register signal handler.\n");
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        // Generate PWM signals with different duty cycles
        gpioPWM(PWM_PIN_1, 128); // 50% duty cycle (128/255)
        gpioPWM(PWM_PIN_2, 64);  // 25% duty cycle (64/255)
        gpioPWM(PWM_PIN_3, 192); // 75% duty cycle (192/255)

        // Print current PWM states
        printf("PWM Pin %d: Duty Cycle = %d\n", PWM_PIN_1, gpioGetPWMdutycycle(PWM_PIN_1));
        printf("PWM Pin %d: Duty Cycle = %d\n", PWM_PIN_2, gpioGetPWMdutycycle(PWM_PIN_2));
        printf("PWM Pin %d: Duty Cycle = %d\n", PWM_PIN_3, gpioGetPWMdutycycle(PWM_PIN_3));

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Stop PWM signals
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated successfully.\n");
    return 0;
}

