    d = opendir(W1_DEVICES_DIR);
    if (d) {
        while ((dir = readdir(d)) != NULL) {
            if (strstr(dir->d_name, "28-")) {
                char *device_id = strdup(dir->d_name);
                closedir(d);
                return device_id;
            }
        }
        closedir(d);
    }
    return NULL;
}

// Function to read the temperature from the DS18B20 sensor
float read_temperature(const char *device_id) {
    char filepath[256];
    snprintf(filepath, sizeof(filepath), "%s/%s/w1_slave", W1_DEVICES_DIR, device_id);

    FILE *fp = fopen(filepath, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", filepath, strerror(errno));
        return -1000.0; // Indicate error
    }

    char line1[256], line2[256];
    if (fgets(line1, sizeof(line1), fp) == NULL || fgets(line2, sizeof(line2), fp) == NULL) {
        fprintf(stderr, "Error reading from file %s\n", filepath);
        fclose(fp);
        return -1000.0; // Indicate error
    }

    fclose(fp);

    if (!strstr(line1, "YES")) {
        fprintf(stderr, "CRC check failed in file %s\n", filepath);
        return -1000.0; // Indicate error
    }

    char *temp_str = strstr(line2, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Temperature data not found in file %s\n", filepath);
        return -1000.0; // Indicate error
    }

    long temp_raw = strtol(temp_str + 2, NULL, 10);
    float temperature = (float)temp_raw / 1000.0;

    return temperature;
}

int main() {
    signal(SIGINT, sigint_handler);

    char *device_id = find_ds18b20_device();
    if (device_id == NULL) {
        fprintf(stderr, "DS18B20 device not found. Please ensure it is properly connected.\n");
        return 1;
    }

    printf("Found DS18B20 device with ID: %s\n", device_id);

    while (keep_running) {
        float temperature = read_temperature(device_id);

        if (temperature > -999.0) { // Basic validity check
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying...\n");
        }

        sleep(5);
    }

    free(device_id);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define TEMP_MEASURE_CMD 0xE3
#define HUMID_MEASURE_CMD 0xE5

int i2c_fd = -1;

void signal_handler(int sig);
int read_htu21d(int fd, float *temperature, float *humidity);

void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    float temperature, humidity;
    int ret;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        ret = read_htu21d(i2c_fd, &temperature, &humidity);
        if (ret == 0) {
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading HTU21D data\n");
        }

        sleep(60);
    }

    return 0;
}

int read_htu21d(int fd, float *temperature, float *humidity) {
    uint8_t cmd;
    uint8_t data[3];
    uint16_t raw_temp, raw_humidity;
    int retries = 3;

    // Measure Temperature
    cmd = TEMP_MEASURE_CMD;
    if (write(fd, &cmd, 1) != 1) {
        perror("Error writing temperature command");
        return -1;
    }
    usleep(50000); // Wait for conversion (datasheet says 50ms)

    while (retries > 0) {
        if (read(fd, data, 3) == 3) {
            break;
        } else {
            perror("Error reading temperature data");
            retries--;
            usleep(10000); // Small delay before retrying
        }
    }
    if (retries == 0) return -1;

    raw_temp = (data[0] << 8) | data[1];
    if (raw_temp == 0 || raw_temp == 0xFFFF) {
        fprintf(stderr, "Invalid temperature reading\n");
        return -1;
    }
    *temperature = -46.85 + 175.72 * ((float)raw_temp / 65536.0);

    // Measure Humidity
    cmd = HUMID_MEASURE_CMD;
    if (write(fd, &cmd, 1) != 1) {
        perror("Error writing humidity command");
        return -1;
    }
    usleep(50000); // Wait for conversion

    retries = 3;
    while (retries > 0) {
        if (read(fd, data, 3) == 3) {
            break;
        } else {
            perror("Error reading humidity data");
            retries--;
            usleep(10000); // Small delay before retrying
        }
    }
    if (retries == 0) return -1;

    raw_humidity = (data[0] << 8) | data[1];
    if (raw_humidity == 0 || raw_humidity == 0xFFFF) {
        fprintf(stderr, "Invalid humidity reading\n");
        return -1;
    }
    *humidity = -6.0 + 125.0 * ((float)raw_humidity / 65536.0);

    return 0;
}

