struct gpiod_line *line4, *line18;

void sigint_handler(int sig)
{
    keep_running = 0;
}

int main()
{
    struct gpiod_line_request_config config;
    int ret;

    /* Initialize signal handler */
    signal(SIGINT, sigint_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Open chip failed");
        return EXIT_FAILURE;
    }

    /* Get GPIO line for GPIO 4 */
    line4 = gpiod_chip_get_line(chip, GPIO_PIN_4);
    if (!line4) {
        perror("Get line 4 failed");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Get GPIO line for GPIO 18 */
    line18 = gpiod_chip_get_line(chip, GPIO_PIN_18);
    if (!line18) {
        perror("Get line 18 failed");
        gpiod_chip_close(chip);
        gpiod_line_release(line4);
        return EXIT_FAILURE;
    }

    /* Configure GPIO line for output */
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio-output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    /* Request GPIO line for GPIO 4 */
    ret = gpiod_line_request(line4, &config, 0);
    if (ret < 0) {
        perror("Request line 4 failed");
        gpiod_chip_close(chip);
        gpiod_line_release(line4);
        gpiod_line_release(line18);
        return EXIT_FAILURE;
    }

    /* Request GPIO line for GPIO 18 */
    ret = gpiod_line_request(line18, &config, 0);
    if (ret < 0) {
        perror("Request line 18 failed");
        gpiod_chip_close(chip);
        gpiod_line_release(line4);
        gpiod_line_release(line18);
        return EXIT_FAILURE;
    }

    /* Main loop */
    while (keep_running) {
        /* Set GPIO 4 high, GPIO 18 low */
        ret = gpiod_line_set_value(line4, 1);
        if (ret < 0) {
            perror("Set line 4 value failed");
            break;
        }
        ret = gpiod_line_set_value(line18, 0);
        if (ret < 0) {
            perror("Set line 18 value failed");
            break;
        }
        printf("GPIO %d: HIGH, GPIO %d: LOW\n", GPIO_PIN_4, GPIO_PIN_18);
        usleep(50000);

        /* Set GPIO 4 low, GPIO 18 high */
        ret = gpiod_line_set_value(line4, 0);
        if (ret < 0) {
            perror("Set line 4 value failed");
            break;
        }
        ret = gpiod_line_set_value(line18, 1);
        if (ret < 0) {
            perror("Set line 18 value failed");
            break;
        }
        printf("GPIO %d: LOW, GPIO %d: HIGH\n", GPIO_PIN_4, GPIO_PIN_18);
        usleep(50000);
    }

    /* Release GPIO lines */
    gpiod_line_release(line4);
    gpiod_line_release(line18);

    /* Close GPIO chip */
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

