#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define ADXL345_I2C_ADDR 0x53
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32

int i2c_fd = -1; // Global file descriptor for I2C

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting gracefully...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    int16_t x, y, z;
    uint8_t data[6];
    int retries = 3; // Number of retries for I2C operations

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_I2C_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize ADXL345 (set POWER_CTL register to start measurement)
    uint8_t power_ctl_value = 0x08; // Enable measurement mode
    if (write(i2c_fd, &power_ctl_value, 1) != 1) {
        perror("Error writing to ADXL345 POWER_CTL register");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        // Read accelerometer data
        if (read(i2c_fd, data, 6) != 6) {
            perror("Error reading from ADXL345");
            close(i2c_fd);
            return 1;
        }

        // Combine high and low bytes for each axis
        x = (int16_t)((data[1] << 8) | data[0]);
        y = (int16_t)((data[3] << 8) | data[2]);
        z = (int16_t)((data[5] << 8) | data[4]);

        // Print the raw values
        printf("X: %d, Y: %d, Z: %d\n", x, y, z);

        // Delay for 0.1 seconds
        usleep(100000); // 100000 microseconds = 0.1 seconds
    }

    return 0;
}

