#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DHT22_GPIO 17

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int read_dht22(float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int i, j;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1);
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30);

    gpioSetMode(DHT22_GPIO, PI_INPUT);

    /* Wait for the DHT22 to pull the line low */
    int timeout = 0;
    while (gpioRead(DHT22_GPIO) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > 100) return -1; // Timeout
    }

    timeout = 0;
    while (gpioRead(DHT22_GPIO) == 0) {
        gpioDelay(1);
        timeout++;
        if (timeout > 100) return -1; // Timeout
    }

    timeout = 0;
    while (gpioRead(DHT22_GPIO) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > 100) return -1; // Timeout
    }

    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 0) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) return -1; // Timeout
        }

        long start = gpioTick();
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 1) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) return -1; // Timeout
        }
        long end = gpioTick();

        if ((end - start) > 40) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        return -2; // Checksum failure
    }

    *humidity = (float)(((data[0] << 8) | data[1])) / 10.0;
    *temperature = (float)(((data[2] << 8) | data[3])) / 10.0;
    if (*temperature > 125) {
        *temperature = *temperature - 256;
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;
    int result;

    while (!terminate) {
        result = read_dht22(&temperature, &humidity);

        if (result == 0) {
            printf("Temperature: %.1f °C, Humidity: %.1f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading DHT22 sensor: %d\n", result);
            break; // Exit loop on error
        }

        sleep(2);
    }

    gpioTerminate();
    return (result == 0) ? 0 : 1;
}

