#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define OUTPUT_FILE "capture.rgb"

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffer;
    unsigned int page_size;

    // Open the video device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK);
    if (fd == -1) {
        perror("Error opening device");
        return 1;
    }

    // Check device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        close(fd);
        return 1;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB24; // Request RGB24 format
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting format");
        close(fd);
        return 1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 1; // Request only one buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Error requesting buffers");
        close(fd);
        return 1;
    }

    // Query buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("Error querying buffer");
        close(fd);
        return 1;
    }

    // Map the buffer
    page_size = getpagesize();
    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd);
        return 1;
    }

    // Queue the buffer
    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("Error queuing buffer");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Error starting stream");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    // Capture image
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("Error during select");
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    // Dequeue the buffer
    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("Error dequeuing buffer");
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    // Save the image to a file
    FILE *fp = fopen(OUTPUT_FILE, "wb");
    if (fp == NULL) {
        perror("Error opening output file");
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    fwrite(buffer, buf.bytesused, 1, fp);
    fclose(fp);

    // Stop streaming
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("Error stopping stream");
    }

    // Unmap the buffer
    if (munmap(buffer, buf.length) == -1) {
        perror("Error unmapping buffer");
    }

    // Close the device
    if (close(fd) == -1) {
        perror("Error closing device");
        return 1;
    }

    printf("Image captured and saved as %s\n", OUTPUT_FILE);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN_22 22
#define GPIO_PIN_27 27

static volatile int keep_running = 1;
struct gpiod_chip *chip;
struct gpiod_line *line22, *line27;

void sigint_handler(int sig)
{
    keep_running = 0;
}

int main()
{
    struct gpiod_line_request_config config;
    int ret;

    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Open chip failed");
        return EXIT_FAILURE;
    }

    line22 = gpiod_chip_get_line(chip, GPIO_PIN_22);
    if (!line22) {
        perror("Get line 22 failed");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line27 = gpiod_chip_get_line(chip, GPIO_PIN_27);
    if (!line27) {
        perror("Get line 27 failed");
        gpiod_chip_close(chip);
        gpiod_line_release(line22);
        return EXIT_FAILURE;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "gpio-test";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line22, &config, 0);
    if (ret < 0) {
        perror("Request line 22 as output failed");
        gpiod_chip_close(chip);
        gpiod_line_release(line22);
        gpiod_line_release(line27);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request(line27, &config, 0);
    if (ret < 0) {
        perror("Request line 27 as output failed");
        gpiod_chip_close(chip);
        gpiod_line_release(line22);
        gpiod_line_release(line27);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        ret = gpiod_line_set_value(line22, 1);
        if (ret < 0) {
            perror("Set line 22 value failed");
            break;
        }
        ret = gpiod_line_set_value(line27, 0);
        if (ret < 0) {
            perror("Set line 27 value failed");
            break;
        }
        printf("GPIO %d: 1, GPIO %d: 0\n", GPIO_PIN_22, GPIO_PIN_27);
        usleep(10000);

        ret = gpiod_line_set_value(line22, 0);
        if (ret < 0) {
            perror("Set line 22 value failed");
            break;
        }
        ret = gpiod_line_set_value(line27, 1);
        if (ret < 0) {
            perror("Set line 27 value failed");
            break;
        }
        printf("GPIO %d: 0, GPIO %d: 1\n", GPIO_PIN_22, GPIO_PIN_27);
        usleep(10000);
    }

    gpiod_line_release(line22);
    gpiod_line_release(line27);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

