// Define SSD1306 I2C address and dimensions
#define SSD1306_I2C_ADDR 0x3C
#define SSD1306_WIDTH 128
#define SSD1306_HEIGHT 64

// I2C file descriptor
int i2c_fd;

// Function prototypes
int ssd1306_init();
void ssd1306_sendCommand(uint8_t command);
void ssd1306_sendData(uint8_t data);
void ssd1306_clearDisplay();
void ssd1306_displayString(int x, int y, char *str);
void ssd1306_updateDisplay();
void generateRandomReadings(float *temperature, float *humidity, float *pressure);

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting gracefully...\n");
    ssd1306_clearDisplay();
    close(i2c_fd);
    exit(0);
}

// Function to initialize the SSD1306 OLED display
int ssd1306_init() {
    // Initialization sequence (typical for 128x64 SSD1306)
    ssd1306_sendCommand(0xAE);       // Display off
    ssd1306_sendCommand(0xD5);       // Set display clock divide ratio/oscillator frequency
    ssd1306_sendCommand(0x80);       // --ratio
    ssd1306_sendCommand(0xA8);       // Set multiplex ratio
    ssd1306_sendCommand(SSD1306_HEIGHT - 1); // --height-1
    ssd1306_sendCommand(0xD3);       // Set display offset
    ssd1306_sendCommand(0x00);       // --offset
    ssd1306_sendCommand(0x40 | 0x00); // Set start line address
    ssd1306_sendCommand(0x8D);       // Charge pump setting
    ssd1306_sendCommand(0x14);       // --enable
    ssd1306_sendCommand(0x20);       // Set memory addressing mode
    ssd1306_sendCommand(0x00);       // --horizontal addressing mode
    ssd1306_sendCommand(0xA1);       // Set segment re-map   (A0=column addr 0 mapped to SEG0)
    ssd1306_sendCommand(0xC8);       // Set COM output scan direction   (C0=normal)
    ssd1306_sendCommand(0xDA);       // Set COM pins hardware configuration
    ssd1306_sendCommand(0x12);       // --alternative
    ssd1306_sendCommand(0x81);       // Set contrast control register
    ssd1306_sendCommand(0xCF);       // --contrast
    ssd1306_sendCommand(0xD9);       // Set pre-charge period
    ssd1306_sendCommand(0xF1);       // --period
    ssd1306_sendCommand(0xDB);       // Set VCOM deselect level mode
    ssd1306_sendCommand(0x40);       // --level
    ssd1306_sendCommand(0xA4);       // Entire display ON/OFF
    ssd1306_sendCommand(0xA6);       // Set normal display
    ssd1306_sendCommand(0xAF);       // Display on

    return 0;
}

// Function to send a command to the SSD1306
void ssd1306_sendCommand(uint8_t command) {
    uint8_t buffer[2];
    buffer[0] = 0x00; // Control byte: command
    buffer[1] = command;
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write command to I2C device");
    }
}

// Function to send data to the SSD1306
void ssd1306_sendData(uint8_t data) {
    uint8_t buffer[2];
    buffer[0] = 0x40; // Control byte: data
    buffer[1] = data;
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write data to I2C device");
    }
}

// Function to clear the display buffer
void ssd1306_clearDisplay() {
    // Set column and page address to 0
    ssd1306_sendCommand(0x21); // Column start/end address
    ssd1306_sendCommand(0x00); // Start at column 0
    ssd1306_sendCommand(SSD1306_WIDTH - 1); // End at column 127

    ssd1306_sendCommand(0x22); // Page start/end address
    ssd1306_sendCommand(0x00); // Start at page 0
    ssd1306_sendCommand((SSD1306_HEIGHT / 8) - 1); // End at page 7

    // Send 0x00 to fill the entire display with black
    for (int i = 0; i < SSD1306_WIDTH * (SSD1306_HEIGHT / 8); i++) {
        ssd1306_sendData(0x00);
    }
}

// Function to display a string at a given position
void ssd1306_displayString(int x, int y, char *str) {
    // Simple character mapping (ASCII 32-126) - requires font data
    // This is a placeholder; a real implementation would use a font table
    // For simplicity, we'll just print the ASCII values as characters.

    int page = y / 8;
    int col = x;

    ssd1306_sendCommand(0xB0 + page); // Set page address
    ssd1306_sendCommand(0x00 + (col & 0x0F)); // Set lower column address
    ssd1306_sendCommand(0x10 + ((col >> 4) & 0x0F)); // Set higher column address

    while (*str) {
        // Placeholder: Replace with actual font data lookup and rendering
        // For now, just send the ASCII value as data.
        ssd1306_sendData(*str); // Send the ASCII value as data
        str++;
    }
}

// Function to update the display (not strictly needed with direct writes, but good practice)
void ssd1306_updateDisplay() {
    // In this simple example, we're writing directly to the display,
    // so this function doesn't do anything.
    // A more complex implementation might involve double buffering.
}

// Function to generate random sensor readings
void generateRandomReadings(float *temperature, float *humidity, float *pressure) {
    *temperature = 20.0 + (float)(rand() % 100) / 10.0; // 20.0 - 30.0
    *humidity = 50.0 + (float)(rand() % 500) / 10.0;    // 50.0 - 100.0
    *pressure = 950.0 + (float)(rand() % 1000) / 10.0;   // 950.0 - 1050.0
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SSD1306_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Initialize the SSD1306 display
    if (ssd1306_init() != 0) {
        fprintf(stderr, "SSD1306 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    float temperature, humidity, pressure;
    char temp_str[20], hum_str[20], press_str[20];

    // Main loop
    while (1) {
        // Generate random sensor readings
        generateRandomReadings(&temperature, &humidity, &pressure);

        // Format the readings into strings
        snprintf(temp_str, sizeof(temp_str), "Temp: %.1f C", temperature);
        snprintf(hum_str, sizeof(hum_str), "Hum: %.1f %%", humidity);
        snprintf(press_str, sizeof(press_str), "Press: %.1f hPa", pressure);

        // Clear the display
        ssd1306_clearDisplay();

        // Display the readings on the OLED screen
        ssd1306_displayString(0, 0, temp_str);
        ssd1306_displayString(0, 16, hum_str);
        ssd1306_displayString(0, 32, press_str);

        // Update the display (optional in this simple example)
        ssd1306_updateDisplay();

        // Wait for 0.1 seconds
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 100000000; // 0.1 seconds
        nanosleep(&ts, NULL);
    }

    return 0;
}

