#include <stdio.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_8 8
#define GPIO_9 9
#define GPIO_11 11
#define GPIO_18 18

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_8, PI_OUTPUT);
    gpioSetMode(GPIO_9, PI_OUTPUT);
    gpioSetMode(GPIO_11, PI_OUTPUT);
    gpioSetMode(GPIO_18, PI_OUTPUT);

    int dutyCycle = 0;
    int increment = 5;

    while (1) {
        // Set PWM duty cycle for each GPIO
        gpioPWM(GPIO_8, dutyCycle);
        gpioPWM(GPIO_9, dutyCycle);
        gpioPWM(GPIO_11, dutyCycle);
        gpioPWM(GPIO_18, dutyCycle);

        // Print the current state
        printf("GPIO %d: Duty Cycle = %d\n", GPIO_8, dutyCycle);
        printf("GPIO %d: Duty Cycle = %d\n", GPIO_9, dutyCycle);
        printf("GPIO %d: Duty Cycle = %d\n", GPIO_11, dutyCycle);
        printf("GPIO %d: Duty Cycle = %d\n", GPIO_18, dutyCycle);

        sleep(1);

        // Update duty cycle
        dutyCycle += increment;
        if (dutyCycle > 255) {
            dutyCycle = 0;
        }
    }

    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 23

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to measure distance in centimeters
float get_distance()
{
    long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to start (rising edge)
    int timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout_count < 5000) {
        gpioDelay(1); // Check every 1 us
        timeout_count++;
    }

    if (timeout_count >= 5000) {
        fprintf(stderr, "Timeout waiting for rising edge\n");
        return -1.0; // Indicate error
    }

    start_tick = gpioTick();

    // Wait for echo to end (falling edge)
    timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout_count < 5000) {
        gpioDelay(1); // Check every 1 us
        timeout_count++;
    }

    if (timeout_count >= 5000) {
        fprintf(stderr, "Timeout waiting for falling edge\n");
        return -1.0; // Indicate error
    }

    end_tick = gpioTick();

    // Calculate pulse duration in microseconds
    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters (speed of sound: 343 m/s)
    float distance = (diff_tick / 1000000.0) * 34300.0 / 2.0;

    return distance;
}

int main()
{
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Main loop
    while (!terminate) {
        float distance = get_distance();

        if (distance >= 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(200); // Delay 200 ms
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

