// BME280 Registers
#define BME280_ADDR_76 0x76
#define BME280_ADDR_77 0x77
#define BME280_REG_TEMP_MSB 0xFA
#define BME280_REG_PRESSURE_MSB 0xF7
#define BME280_REG_HUMIDITY_MSB 0xFD
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CTRL_HUMIDITY 0xF2
#define BME280_REG_CONFIG 0xF5

int i2c_fd = -1;

void signal_handler(int sig);
int bme280_init(int fd);
int read_bme280_data(int fd, float *temperature, float *pressure, float *humidity);

void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int bme280_init(int fd) {
    // Set humidity oversampling to 1x
    if (write(fd, "\xF2\x01", 2) != 2) return -1;
    // Set temperature and pressure oversampling to 1x, normal mode
    if (write(fd, "\xF4\x27", 2) != 2) return -1;
    // Set inactive duration to 0.5ms
    if (write(fd, "\xF5\x00", 2) != 2) return -1;
    return 0;
}

int read_bme280_data(int fd, float *temperature, float *pressure, float *humidity) {
    uint8_t data[8];
    int32_t raw_temp, raw_pressure, raw_humidity;
    double var1, var2, T, p, h;

    // Read 8 bytes of data starting from temperature MSB
    if (write(fd, "\xFA", 1) != 1) return -1;
    if (read(fd, data, 8) != 8) return -1;

    raw_pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    raw_temp = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    raw_humidity = (data[6] << 8) | data[7];

    // Dummy compensation calculations (replace with actual BME280 formulas)
    T = (double)raw_temp / 100.0;
    p = (double)raw_pressure / 100.0;
    h = (double)raw_humidity / 100.0;

    *temperature = (float)T;
    *pressure = (float)p;
    *humidity = (float)h;

    return 0;
}

int main() {
    const char *i2c_device = "/dev/i2c-1";
    float temperature, pressure, humidity;
    int result;

    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Initialize BME280 at address 0x76
    if (ioctl(i2c_fd, I2C_SLAVE, BME280_ADDR_76) < 0) {
        perror("Error setting I2C slave address 0x76");
        close(i2c_fd);
        return 1;
    }
    if (bme280_init(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing BME280 at 0x76\n");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        if (read_bme280_data(i2c_fd, &temperature, &pressure, &humidity) == 0) {
            printf("BME280 0x76: Temperature = %.2f °C, Pressure = %.2f hPa, Humidity = %.2f %%\n", temperature, pressure, humidity);
        } else {
            fprintf(stderr, "Error reading data from BME280 at 0x76\n");
        }

        sleep(5);
    }

    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00

int i2c_fd = -1;

void signal_handler(int sig) {
    printf("\nExiting...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    int16_t adc_value;
    unsigned char buf[2];
    unsigned char config[3];

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Configure ADS1115 for single-ended A0, +/-4.096V, continuous conversion, 128 SPS
    config[0] = CONFIG_REG;
    config[1] = 0xC3; // MSB: 11000011 (Single-shot mode, AIN0, +/-4.096V)
    config[2] = 0xE3; // LSB: 11100011 (Continuous conversion, 128 SPS, Disable comparator)

    if (write(i2c_fd, config, 3) != 3) {
        perror("Error writing to I2C device");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        // Read conversion register
        buf[0] = CONVERSION_REG;
        if (write(i2c_fd, buf, 1) != 1) {
            perror("Error writing to I2C device");
            close(i2c_fd);
            return 1;
        }

        if (read(i2c_fd, buf, 2) != 2) {
            perror("Error reading from I2C device");
            close(i2c_fd);
            return 1;
        }

        // Combine MSB and LSB
        adc_value = (buf[0] << 8) | buf[1];

        // Print ADC value
        printf("ADC Value: %d\n", adc_value);

        // Wait 0.2 seconds
        usleep(200000);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 4

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig)
{
    terminate = 1;
}

int main()
{
    int ret;
    struct gpiod_line_request_config config;

    /* Register signal handler */
    signal(SIGINT, signal_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Configure line request */
    memset(&config, 0, sizeof(config));
    config.consumer = "digital_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    /* Request GPIO line */
    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop */
    while (!terminate) {
        /* Set GPIO value to 1 */
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO value");
            break;
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN);
        sleep(60);

        /* Set GPIO value to 0 */
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO value");
            break;
        }
        printf("GPIO %d set to LOW\n", GPIO_PIN);
        sleep(60);
    }

    /* Release GPIO line */
    gpiod_line_release(line);

    /* Close GPIO chip */
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B

int i2c_fd = -1;

void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    int retries = 3;
    while (retries > 0) {
        i2c_fd = open("/dev/i2c-1", O_RDWR);
        if (i2c_fd < 0) {
            perror("Error opening I2C device");
            retries--;
            sleep(1); // Wait before retrying
            continue;
        }

        if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
            perror("Error setting I2C slave address");
            close(i2c_fd);
            i2c_fd = -1;
            retries--;
            sleep(1);
            continue;
        }

        // Wake up the MPU6050
        uint8_t wake_up_data[] = {PWR_MGMT_1, 0x00};
        if (write(i2c_fd, wake_up_data, 2) != 2) {
            perror("Error writing to I2C device");
            close(i2c_fd);
            i2c_fd = -1;
            retries--;
            sleep(1);
            continue;
        }

        break; // Exit retry loop if successful
    }

    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to initialize I2C after multiple retries.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (1) {
        uint8_t read_buffer[14];
        uint8_t read_command = ACCEL_XOUT_H;

        if (write(i2c_fd, &read_command, 1) != 1) {
            perror("Error writing read command");
            close(i2c_fd);
            return 1;
        }

        if (read(i2c_fd, read_buffer, 14) != 14) {
            perror("Error reading from I2C device");
            close(i2c_fd);
            return 1;
        }

        int16_t accel_x = (read_buffer[0] << 8) | read_buffer[1];
        int16_t accel_y = (read_buffer[2] << 8) | read_buffer[3];
        int16_t accel_z = (read_buffer[4] << 8) | read_buffer[5];
        int16_t temp = (read_buffer[6] << 8) | read_buffer[7];
        int16_t gyro_x = (read_buffer[8] << 8) | read_buffer[9];
        int16_t gyro_y = (read_buffer[10] << 8) | read_buffer[11];
        int16_t gyro_z = (read_buffer[12] << 8) | read_buffer[13];

        printf("AccelX: %d, AccelY: %d, AccelZ: %d, Temp: %d, GyroX: %d, GyroY: %d, GyroZ: %d\n",
               accel_x, accel_y, accel_z, temp, gyro_x, gyro_y, gyro_z);

        usleep(10000); // 10ms delay
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 23

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", rc);
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        gpioWrite(GPIO_PIN, 1);
        printf("GPIO %d HIGH\n", GPIO_PIN);
        gpioDelay(50000); // 0.05 seconds

        gpioWrite(GPIO_PIN, 0);
        printf("GPIO %d LOW\n", GPIO_PIN);
        gpioDelay(50000); // 0.05 seconds
    }

    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

// Configuration
#define I2C_BUS "/dev/i2c-1" // I2C bus device file
#define LCD_ADDR 0x27         // I2C address of the LCD
#define LCD_WIDTH 16          // Number of characters per line

// LCD Commands
#define LCD_CLEARDISPLAY 0x01
#define LCD_RETURNHOME 0x02
#define LCD_ENTRYMODESET 0x04
#define LCD_DISPLAYCONTROL 0x08
#define LCD_CURSORSHIFT 0x10
#define LCD_FUNCTIONSET 0x20

// Flags for display control
#define LCD_DISPLAYON 0x04
#define LCD_CURSORON 0x02
#define LCD_BLINKON 0x01

// Flags for entry mode
#define LCD_ENTRYRIGHT 0x00
#define LCD_ENTRYLEFT 0x02
#define LCD_ENTRYSHIFTINCREMENT 0x01
#define LCD_ENTRYSHIFTDECREMENT 0x00

// Flags for function set
#define LCD_8BITMODE 0x10
#define LCD_4BITMODE 0x00
#define LCD_2LINE 0x08
#define LCD_1LINE 0x00
#define LCD_5x10DOTS 0x04
#define LCD_5x8DOTS 0x00

// Backlight control
#define LCD_BACKLIGHT 0x08
#define LCD_NOBACKLIGHT 0x00

// En pin is data bit 2
#define En 0b00000100 // Enable bit
// Rw pin is data bit 5
#define Rw 0b00001000 // Read/Write bit (not used in this example)
// Rs pin is data bit 6
#define Rs 0b00010000 // Register select bit

int i2c_fd; // File descriptor for I2C communication

// Function prototypes
int lcd_init();
void lcd_byte(int bits, int mode);
void lcd_string(const char *s);
void lcd_clear();
void lcd_backlight(int state);
void display_readings(float temperature, float humidity);
void signal_handler(int sig);

// Signal handler for clean exit
void signal_handler(int sig) {
    printf("\nExiting cleanly...\n");
    lcd_clear();
    lcd_backlight(0); // Turn off backlight
    close(i2c_fd);
    exit(0);
}

// Initialize the LCD
int lcd_init() {
    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, LCD_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    // Initialization sequence (as per HD44780 datasheet)
    usleep(50000); // Wait for more than 4.1ms after VCC rises to 4.5V
    lcd_byte(0x30, 0); // Initialization command 1
    usleep(4500);      // Wait for more than 4.1ms
    lcd_byte(0x30, 0); // Initialization command 2
    usleep(4500);      // Wait for more than 100us
    lcd_byte(0x30, 0); // Initialization command 3
    usleep(4500);
    lcd_byte(0x20, 0); // 4-bit mode

    lcd_byte(LCD_FUNCTIONSET | LCD_4BITMODE | LCD_2LINE | LCD_5x8DOTS, 0);
    lcd_byte(LCD_DISPLAYCONTROL | LCD_DISPLAYON | LCD_CURSOROFF | LCD_BLINKOFF, 0);
    lcd_clear();
    lcd_byte(LCD_ENTRYMODESET | LCD_ENTRYLEFT | LCD_ENTRYSHIFTDECREMENT, 0);

    return 0;
}

// Send byte to LCD
void lcd_byte(int bits, int mode) {
    int bits_high = mode | (bits & 0xF0) | LCD_BACKLIGHT;
    int bits_low = mode | ((bits << 4) & 0xF0) | LCD_BACKLIGHT;

    // High bits
    if (write(i2c_fd, &bits_high, 1) != 1) {
        perror("Error writing to I2C device");
    }
    usleep(1); // Enable pulse
    bits_high |= En;
    if (write(i2c_fd, &bits_high, 1) != 1) {
        perror("Error writing to I2C device");
    }
    usleep(1);
    bits_high &= ~En;
    if (write(i2c_fd, &bits_high, 1) != 1) {
        perror("Error writing to I2C device");
    }
    usleep(100);

    // Low bits
    if (write(i2c_fd, &bits_low, 1) != 1) {
        perror("Error writing to I2C device");
    }
    usleep(1); // Enable pulse
    bits_low |= En;
    if (write(i2c_fd, &bits_low, 1) != 1) {
        perror("Error writing to I2C device");
    }
    usleep(1);
    bits_low &= ~En;
    if (write(i2c_fd, &bits_low, 1) != 1) {
        perror("Error writing to I2C device");
    }
    usleep(100);
}

// Send string to LCD
void lcd_string(const char *s) {
    while (*s) {
        lcd_byte(*s++, Rs);
    }
}

// Clear the LCD display
void lcd_clear() {
    lcd_byte(LCD_CLEARDISPLAY, 0);
    usleep(2000); // This command requires a long execution time > 1.53 ms
}

// Control the LCD backlight
void lcd_backlight(int state) {
    int backlight_state = state ? LCD_BACKLIGHT : LCD_NOBACKLIGHT;
    int cmd = 0x00 | backlight_state;
    if (write(i2c_fd, &cmd, 1) != 1) {
        perror("Error writing to I2C device");
    }
}

// Display temperature and humidity readings
void display_readings(float temperature, float humidity) {
    char buffer[32];

    lcd_clear();

    snprintf(buffer, sizeof(buffer), "Temp: %.1f C", temperature);
    lcd_string(buffer);

    lcd_byte(0xC0, 0); // Move cursor to the second line

    snprintf(buffer, sizeof(buffer), "Hum: %.1f %%", humidity);
    lcd_string(buffer);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize LCD
    if (lcd_init() < 0) {
        fprintf(stderr, "LCD initialization failed. Exiting.\n");
        return 1;
    }

    // Simulated sensor readings
    float temperature = 25.0;
    float humidity = 60.0;

    while (1) {
