#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B

int main() {
    int file;
    const char *i2c_device = "/dev/i2c-1";
    int i;

    // Open I2C device
    if ((file = open(i2c_device, O_RDWR)) < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Specify slave address
    if (ioctl(file, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(file);
        return 1;
    }

    // Wake up the MPU6050
    unsigned char wake_up_data[2] = {PWR_MGMT_1, 0x00};
    if (write(file, wake_up_data, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        close(file);
        return 1;
    }

    // Read accelerometer data
    for (i = 0; i < 100; i++) {
        unsigned char reg_addr = ACCEL_XOUT_H;
        if (write(file, &reg_addr, 1) != 1) {
            fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
            close(file);
            return 1;
        }

        unsigned char buffer[6];
        if (read(file, buffer, 6) != 6) {
            fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
            close(file);
            return 1;
        }

        int16_t accel_x = (buffer[0] << 8) | buffer[1];
        int16_t accel_y = (buffer[2] << 8) | buffer[3];
        int16_t accel_z = (buffer[4] << 8) | buffer[5];

        printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n", accel_x, accel_y, accel_z);
        usleep(10000); // 10ms delay
    }

    close(file);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
