#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <fcntl.h>
#include <termios.h>
#include <sys/select.h>
#include <mosquitto.h>

#define DEFAULT_PORT 1883
#define DEFAULT_TOPIC "sensor/reading"
#define DEFAULT_DEVICE "/dev/ttyAMA0"
#define BAUDRATE B9600
#define MAX_BUFFER_SIZE 256

// Global variables for signal handling and resource cleanup
static volatile int running = 1;
static struct mosquitto *mqtt_client = NULL;
static int serial_fd = -1;

// Structure to hold configuration parameters
typedef struct {
    char *broker_address;
    int broker_port;
    char *topic;
    char *device_path;
} config_t;

// Function prototypes
int read_sensor_data(int fd, char *buffer, size_t buffer_size);
int validate_sensor_reading(const char *reading);
int publish_sensor_reading(struct mosquitto *client, const char *topic, const char *payload);
void signal_handler(int signum);
int setup_serial(const char *device_path);

// Signal handler function
void signal_handler(int signum) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signum);
}

// Function to read sensor data from the serial port
int read_sensor_data(int fd, char *buffer, size_t buffer_size) {
    fd_set readfds;
    struct timeval timeout;
    int ret;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = 1; // Timeout after 1 second
    timeout.tv_usec = 0;

    ret = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (ret == -1) {
        perror("select");
        return -1;
    } else if (ret == 0) {
        fprintf(stderr, "Timeout reading from serial port\n");
        return -1; // Timeout
    }

    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read == -1) {
        perror("read");
        return -1;
    }

    buffer[bytes_read] = '\0'; // Null-terminate the string
    return 0;
}

// Function to validate the sensor reading
int validate_sensor_reading(const char *reading) {
    // Implement your validation logic here
    // For example, check if the reading is within a reasonable range
    // and contains only expected characters.
    if (reading == NULL || strlen(reading) == 0) {
        fprintf(stderr, "Invalid sensor reading: empty or NULL\n");
        return -1;
    }

    // Example: Check if the reading is a number between 0 and 100
    char *endptr;
    errno = 0; // Reset errno before calling strtol
    long value = strtol(reading, &endptr, 10);

    if (errno != 0 || endptr == reading || *endptr != '\0' || value < 0 || value > 100) {
        fprintf(stderr, "Invalid sensor reading: %s\n", reading);
        return -1;
    }

    return 0;
}

// Function to publish the sensor reading to the MQTT broker
int publish_sensor_reading(struct mosquitto *client, const char *topic, const char *payload) {
    int ret = mosquitto_publish(client, NULL, topic, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
        return -1;
    }
    return 0;
}

// Function to set up the serial port
int setup_serial(const char *device_path) {
    int fd = open(device_path, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("open");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, BAUDRATE);
    cfsetispeed(&tty, BAUDRATE);

    tty.c_cflag |= (CLOCAL | CREAD);//Enable receiver and set local mode
    tty.c_cflag &= ~PARENB; // No parity
    tty.c_cflag &= ~CSTOPB; // 1 stop bit
    tty.c_cflag &= ~CSIZE; // Clear size bits
    tty.c_cflag |= CS8; // 8 data bits

    tty.c_lflag &= ~ICANON; // Disable canonical mode
    tty.c_lflag &= ~ECHO;   // Disable echo
    tty.c_lflag &= ~ECHOE;  // Disable erasure
    tty.c_lflag &= ~ECHONL; // Disable new-line echo
    tty.c_lflag &= ~ISIG;   // Disable interpretation of INTR, QUIT and SUSP

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // Turn off software flow control
    tty.c_iflag &= ~(IGNBRK|BRKINT|PARMRK|ISTRIP|INLCR|IGNCR|ICRNL);

    tty.c_oflag &= ~OPOST; // Prevent special interpretation of output bytes (e.g. newline chars)
    tty.c_oflag &= ~ONLCR; // Prevent conversion of newline to carriage return/line feed

    tty.c_cc[VMIN] = 0;  // Read non-blocking
    tty.c_cc[VTIME] = 5; // Wait 0.5 seconds (5 deciseconds)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        close(fd);
        return -1;
    }

    return fd;
}

int main(int argc, char *argv[]) {
    config_t config = {
        .broker_address = "localhost",
        .broker_port = DEFAULT_PORT,
        .topic = DEFAULT_TOPIC,
        .device_path = DEFAULT_DEVICE
    };

    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "a:p:t:d:")) != -1) {
        switch (opt) {
            case 'a':
                config.broker_address = optarg;
                break;
            case 'p':
                config.broker_port = atoi(optarg);
                break;
            case 't':
                config.topic = optarg;
                break;
            case 'd':
                config.device_path = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a broker_address] [-p broker_port] [-t topic] [-d device_path]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new MQTT client instance
    mqtt_client = mosquitto_new(NULL, true, NULL);
    if (!mqtt_client) {
        fprintf(stderr, "Error: Out of memory.\n");
        mosquitto_lib_cleanup();
        return 1;
    }

    // Connect to the MQTT broker
    int ret = mosquitto_connect(mqtt_client, config.broker_address, config.broker_port, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to broker: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mqtt_client);
        mosquitto_lib_cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the serial port
    serial_fd = setup_serial(config.device_path);
    if (serial_fd == -1) {
        mosquitto_disconnect(mqtt_client);
        mosquitto_destroy(mqtt_client);
        mosquitto_lib_cleanup();
        return 1;
    }

    char buffer[MAX_BUFFER_SIZE];

    // Main loop
    while (running) {
        // Read sensor data
        if (read_sensor_data(serial_fd, buffer, sizeof(buffer)) == 0) {
            // Validate sensor reading
            if (validate_sensor_reading(buffer) == 0) {
                // Publish sensor reading
                if (publish_sensor_reading(mqtt_client, config.topic, buffer) != 0) {
                    fprintf(stderr, "Failed to publish sensor reading.\n");
                }
            } else {
                fprintf(stderr, "Invalid sensor reading received.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Sleep for 10 milliseconds
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 10000000; // 10 milliseconds
        nanosleep(&ts, NULL);
    }

    // Clean up resources
    close(serial_fd);
    mosquitto_disconnect(mqtt_client);
    mosquitto_destroy(mqtt_client);
    mosquitto_lib_cleanup();

    return 0;
}

#include <stdio.h>
