#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_23 23

static volatile int keep_running = 1;
struct gpiod_chip *chip;
struct gpiod_line *line2, *line3, *line23;

void sigint_handler(int sig)
{
    keep_running = 0;
}

int main()
{
    int ret;
    struct gpiod_line_request_config config;

    /* Initialize signal handler */
    signal(SIGINT, sigint_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Open chip failed");
        return EXIT_FAILURE;
    }

    /* Get GPIO lines */
    line2 = gpiod_chip_get_line(chip, GPIO_2);
    line3 = gpiod_chip_get_line(chip, GPIO_3);
    line23 = gpiod_chip_get_line(chip, GPIO_23);

    if (!line2 || !line3 || !line23) {
        perror("Get line failed");
        goto cleanup_chip;
    }

    /* Request GPIO lines as outputs */
    memset(&config, 0, sizeof(config));
    config.consumer = "digital_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line2, &config, 0);
    if (ret < 0) {
        perror("Request line 2 failed");
        goto cleanup_lines;
    }

    ret = gpiod_line_request(line3, &config, 0);
    if (ret < 0) {
        perror("Request line 3 failed");
        goto cleanup_line2;
    }

    ret = gpiod_line_request(line23, &config, 0);
    if (ret < 0) {
        perror("Request line 23 failed");
        goto cleanup_line3;
    }

    /* Main loop */
    while (keep_running) {
        /* Set GPIO 2 high, GPIO 3 low, GPIO 23 high */
        ret = gpiod_line_set_value(line2, 1);
        if (ret < 0) {
            perror("Set line 2 value failed");
            break;
        }
        ret = gpiod_line_set_value(line3, 0);
        if (ret < 0) {
            perror("Set line 3 value failed");
            break;
        }
        ret = gpiod_line_set_value(line23, 1);
        if (ret < 0) {
            perror("Set line 23 value failed");
            break;
        }

        printf("GPIO %d: HIGH, GPIO %d: LOW, GPIO %d: HIGH\n", GPIO_2, GPIO_3, GPIO_23);
        sleep(2);

        /* Set GPIO 2 low, GPIO 3 high, GPIO 23 low */
        ret = gpiod_line_set_value(line2, 0);
        if (ret < 0) {
            perror("Set line 2 value failed");
            break;
        }
        ret = gpiod_line_set_value(line3, 1);
        if (ret < 0) {
            perror("Set line 3 value failed");
            break;
        }
        ret = gpiod_line_set_value(line23, 0);
        if (ret < 0) {
            perror("Set line 23 value failed");
            break;
        }

        printf("GPIO %d: LOW, GPIO %d: HIGH, GPIO %d: LOW\n", GPIO_2, GPIO_3, GPIO_23);
        sleep(2);
    }

    /* Release GPIO lines */
cleanup_line23:
    gpiod_line_release(line23);
cleanup_line3:
    gpiod_line_release(line3);
cleanup_line2:
    gpiod_line_release(line2);
cleanup_lines:
    gpiod_line_release(line2);
    gpiod_line_release(line3);
    gpiod_line_release(line23);
cleanup_chip:
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

