        return -1;
    }

    cfsetospeed(&tty, B9600); // Set baud rate to 9600
    cfsetispeed(&tty, B9600);

    tty.c_cflag &= ~PARENB; // No parity
    tty.c_cflag &= ~CSTOPB; // 1 stop bit
    tty.c_cflag &= ~CSIZE;  // Clear size bits
    tty.c_cflag |= CS8;   // 8 data bits
    tty.c_cflag &= ~CRTSCTS; // Disable RTS/CTS hardware flow control

    tty.c_cflag |= CREAD | CLOCAL; // Turn on READ & ignore ctrl lines

    tty.c_lflag &= ~ICANON; // Disable canonical mode
    tty.c_lflag &= ~ECHO;   // Disable echo
    tty.c_lflag &= ~ECHOE;  // Disable erasure
    tty.c_lflag &= ~ECHONL; // Disable new-line echo
    tty.c_lflag &= ~ISIG;   // Disable interpretation of INTR, QUIT and SUSP

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // Turn off software flow control
    tty.c_iflag &= ~(IGNBRK|BRKINT|PARMRK|ISTRIP|INLCR|IGNCR|ICRNL);

    tty.c_oflag &= ~OPOST; // Prevent special interpretation of output bytes (e.g. newline chars)
    tty.c_oflag &= ~ONLCR; // Prevent conversion of newline to carriage return/line feed

    tty.c_cc[VMIN] = 0;  // Read non-blocking
    tty.c_cc[VTIME] = 5; // Wait 0.5 seconds (5 * 0.1s)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read == -1) {
        fprintf(stderr, "Error reading from device %s: %s\n", device, strerror(errno));
        close(fd);
        return -1;
    } else {
        buffer[bytes_read] = '\0'; // Null-terminate the buffer
    }

    close(fd);
    return 0;
}

// Function to publish data to MQTT broker
int publish_mqtt(struct mosquitto *client, const char *topic, const char *payload) {
    int ret = mosquitto_publish(client, NULL, topic, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    const char *device = DEFAULT_DEVICE;
    const char *mqtt_host = DEFAULT_MQTT_HOST;
    int mqtt_port = DEFAULT_MQTT_PORT;
    const char *mqtt_topic = DEFAULT_MQTT_TOPIC;

    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "d:h:p:t:")) != -1) {
        switch (opt) {
            case 'd':
                device = optarg;
                break;
            case 'h':
                mqtt_host = optarg;
                break;
            case 'p':
                mqtt_port = atoi(optarg);
                break;
            case 't':
                mqtt_topic = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-d device] [-h host] [-p port] [-t topic]\n", argv[0]);
                return 1;
        }
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new Mosquitto client instance
    mqtt_client = mosquitto_new(NULL, true, NULL);
    if (!mqtt_client) {
        fprintf(stderr, "Error creating Mosquitto client instance.\n");
        mosquitto_lib_cleanup();
        return 1;
    }

    // Connect to the MQTT broker
    int ret = mosquitto_connect(mqtt_client, mqtt_host, mqtt_port, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mqtt_client);
        mosquitto_lib_cleanup();
        return 1;
    }

    // Main loop
    char buffer[256];
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(device, buffer, sizeof(buffer)) == 0) {
            // Publish data to MQTT broker
            if (publish_mqtt(mqtt_client, mqtt_topic, buffer) != 0) {
                fprintf(stderr, "Failed to publish data. Retrying in 5 seconds.\n");
                sleep(5);
                continue;
            }
            printf("Published: %s\n", buffer);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Sleep for 5 seconds
        sleep(5);
    }

    // Disconnect from the MQTT broker
    mosquitto_disconnect(mqtt_client);

    // Destroy the Mosquitto client instance
    mosquitto_destroy(mqtt_client);

    // Cleanup libmosquitto
    mosquitto_lib_cleanup();

    return 0;
}

#include <stdio.h>
