#define PWM_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int duty_cycle;
    int result;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set GPIO 18 as PWM output */
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    /* Set PWM frequency */
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);

    /* Set PWM range */
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    /* Register signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    while (!terminate) {
        /* Generate random duty cycle */
        duty_cycle = rand() % (PWM_RANGE + 1);

        /* Set PWM duty cycle */
        result = gpioPWM(PWM_GPIO, duty_cycle);
        if (result != 0) {
            fprintf(stderr, "Error setting PWM duty cycle: %d\n", result);
            gpioTerminate();
            return 1;
        }

        /* Print current state */
        printf("PWM Duty Cycle: %d\n", duty_cycle);

        /* Wait for 5 seconds */
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    /* Clean up and exit */
    gpioPWM(PWM_GPIO, 0); // Stop PWM
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to measure distance in centimeters
float get_distance()
{
    long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to start (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < 50000) // Timeout after ~50ms
    {
        gpioDelay(1); // Check every 1 us
        count++;
    }

    if (count >= 50000)
    {
        fprintf(stderr, "Timeout waiting for echo start.\n");
        return -1.0; // Indicate error
    }

    start_tick = gpioTick();

    // Wait for echo to end (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < 50000) // Timeout after ~50ms
    {
        gpioDelay(1); // Check every 1 us
        count++;
    }

    if (count >= 50000)
    {
        fprintf(stderr, "Timeout waiting for echo end.\n");
        return -1.0; // Indicate error
    }

    end_tick = gpioTick();

    // Calculate the difference in ticks
    diff_tick = end_tick - start_tick;

    // Calculate the distance in centimeters
    float distance = (diff_tick * 34300.0) / 2000000.0; // Speed of sound: 343 m/s

    return distance;
}

int main()
{
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Main loop
    while (!terminate)
    {
        float distance = get_distance();

        if (distance >= 0.0)
        {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error reading distance.\n");
        }

        gpioDelay(200000); // 0.2 seconds
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

