#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <mosquitto.h>

#define DEFAULT_DEVICE_PATH "/dev/ttyS0"
#define DEFAULT_BAUD_RATE 9600
#define DEFAULT_MQTT_HOST "localhost"
#define DEFAULT_MQTT_PORT 1883
#define DEFAULT_MQTT_TOPIC "sensor/reading"
#define DEFAULT_TIMEOUT_SEC 5

// Global variables for signal handling and resource cleanup
static volatile int keep_running = 1;
static struct mosquitto *mqtt_client = NULL;
static int serial_fd = -1;

// Structure to hold configuration parameters
typedef struct {
    char *device_path;
    int baud_rate;
    char *mqtt_host;
    int mqtt_port;
    char *mqtt_topic;
    int timeout_sec;
} config_t;

// Function prototypes
int parse_arguments(int argc, char *argv[], config_t *config);
int open_serial_port(const char *device_path, int baud_rate);
char *read_sensor_data(int fd, int timeout_sec);
int validate_sensor_reading(const char *data);
int publish_mqtt_message(struct mosquitto *client, const char *topic, const char *payload);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signum);
        keep_running = 0;
    }
}

// Function to parse command-line arguments
int parse_arguments(int argc, char *argv[], config_t *config) {
    int opt;

    // Initialize default values
    config->device_path = strdup(DEFAULT_DEVICE_PATH);
    config->baud_rate = DEFAULT_BAUD_RATE;
    config->mqtt_host = strdup(DEFAULT_MQTT_HOST);
    config->mqtt_port = DEFAULT_MQTT_PORT;
    config->mqtt_topic = strdup(DEFAULT_MQTT_TOPIC);
    config->timeout_sec = DEFAULT_TIMEOUT_SEC;

    while ((opt = getopt(argc, argv, "d:b:h:p:t:")) != -1) {
        switch (opt) {
            case 'd':
                free(config->device_path);
                config->device_path = strdup(optarg);
                break;
            case 'b':
                config->baud_rate = atoi(optarg);
                break;
            case 'h':
                free(config->mqtt_host);
                config->mqtt_host = strdup(optarg);
                break;
            case 'p':
                config->mqtt_port = atoi(optarg);
                break;
            case 't':
                free(config->mqtt_topic);
                config->mqtt_topic = strdup(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-d device_path] [-b baud_rate] [-h mqtt_host] [-p mqtt_port] [-t mqtt_topic]\n", argv[0]);
                return 1;
        }
    }

    return 0;
}

// Function to open the serial port
int open_serial_port(const char *device_path, int baud_rate) {
    int fd = open(device_path, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Error opening serial port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud_rate);
    cfsetispeed(&tty, baud_rate);

    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_lflag &= ~ICANON;
    tty.c_lflag &= ~ECHO;
    tty.c_lflag &= ~ECHOE;
    tty.c_lflag &= ~ECHONL;
    tty.c_lflag &= ~ISIG;
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN] = 0;      // Non-blocking read
    tty.c_cc[VTIME] = 5;     // Timeout of 0.5 seconds

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read sensor data from the serial port with timeout
char *read_sensor_data(int fd, int timeout_sec) {
    char *buffer = NULL;
    size_t buffer_size = 0;
    ssize_t bytes_read;
    time_t start_time = time(NULL);

    while (keep_running && (time(NULL) - start_time) < timeout_sec) {
        bytes_read = read(fd, &buffer[buffer_size], 1); // Read one byte at a time
        if (bytes_read > 0) {
            buffer_size++;
            buffer = realloc(buffer, buffer_size + 1); // Allocate space for null terminator
            if (buffer == NULL) {
                perror("Failed to reallocate memory");
                return NULL;
            }
            buffer[buffer_size - 1] = '\0';
        } else if (bytes_read < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                usleep(10000); // Wait 10ms before retrying
            } else {
                perror("Error reading from serial port");
                free(buffer);
                return NULL;
            }
        } else {
            // No more data to read
            break;
        }
    }

    if (!keep_running) {
        free(buffer);
        return NULL;
    }

    if (buffer_size == 0) {
        fprintf(stderr, "Timeout reading from serial port\n");
        return NULL;
    }

    return buffer;
}

// Function to validate the sensor reading
int validate_sensor_reading(const char *data) {
    // Simple validation: check if the string contains only digits and commas
    if (data == NULL || strlen(data) == 0) {
        return 0;
    }

    for (size_t i = 0; i < strlen(data); i++) {
        if (!(isdigit(data[i]) || data[i] == ',')) {
            return 0;
        }
    }

    return 1;
}

// Function to publish an MQTT message
int publish_mqtt_message(struct mosquitto *client, const char *topic, const char *payload) {
    int ret = mosquitto_publish(client, NULL, topic, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
        return 1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    config_t config;

    // Parse command-line arguments
    if (parse_arguments(argc, argv, &config) != 0) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new Mosquitto client instance
    mqtt_client = mosquitto_new(NULL, true, NULL);
    if (!mqtt_client) {
        fprintf(stderr, "Error creating Mosquitto client\n");
        mosquitto_lib_cleanup();
        free(config.device_path);
        free(config.mqtt_host);
        free(config.mqtt_topic);
        return 1;
    }

    // Connect to the MQTT broker
    int ret = mosquitto_connect(mqtt_client, config.mqtt_host, config.mqtt_port, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mqtt_client);
        mosquitto_lib_cleanup();
        free(config.device_path);
        free(config.mqtt_host);
        free(config.mqtt_topic);
        return 1;
    }

    // Open the serial port
    serial_fd = open_serial_port(config.device_path, config.baud_rate);
    if (serial_fd == -1) {
        mosquitto_disconnect(mqtt_client);
        mosquitto_destroy(mqtt_client);
        mosquitto_lib_cleanup();
        free(config.device_path);
        free(config.mqtt_host);
        free(config.mqtt_topic);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Read sensor data
        char *sensor_data = read_sensor_data(serial_fd, config.timeout_sec);
        if (sensor_data != NULL) {
            // Validate sensor reading
            if (validate_sensor_reading(sensor_data)) {
                // Publish MQTT message
                if (publish_mqtt_message(mqtt_client, config.mqtt_topic, sensor_data) != 0) {
                    fprintf(stderr, "Failed to publish MQTT message\n");
                }
            } else {
                fprintf(stderr, "Invalid sensor reading: %s\n", sensor_data);
            }
            free(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(1); // Wait for 1 second
    }

    // Clean up resources
    close(serial_fd);
    mosquitto_disconnect(mqtt_client);
    mosquitto_destroy(mqtt_client);
    mosquitto_lib_cleanup();
    free(config.device_path);
    free(config.mqtt_host);
    free(config.mqtt_topic);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <sys/time.h>
#include <mosquitto.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48 // Default address
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define MQTT_HOST "localhost" // Change this to your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/sensors/ads1115"
#define NUM_READINGS 10

// Global variables
int i2c_handle;
struct mosquitto *mosq = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_ads1115(int i2c_handle);
void publish_mqtt(struct mosquitto *mosq, const char *topic, const char *payload);
void signal_handler(int signum);

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Reads the ADC value from the ADS1115
int read_ads1115(int i2c_handle) {
    uint8_t config[3];
    int16_t adc_value;
    char buf[2];

    // Configure ADS1115 for single-ended channel 0, +/- 4.096V, continuous conversion mode
    config[0] = CONFIG_REG;
    config[1] = 0xC3; // 0b11000011  MSB: OS=1, MUX=100 (AIN0-GND), PGA=011 (+/- 4.096V)
    config[2] = 0x83; // 0b10000011  LSB: MODE=1 (Continuous), DR=100 (128 SPS), COMP_MODE=0, COMP_POL=0, COMP_LAT=0, COMP_QUE=11

    if (i2cWriteDevice(i2c_handle, (char *)config, 3) != 0) {
        fprintf(stderr, "Error writing to ADS1115 configuration register\n");
        return -1;
    }

    gpioDelay(10); // Wait for conversion (adjust as needed)

    // Read the conversion register
    if (i2cReadI2CBlockData(i2c_handle, CONVERSION_REG, buf, 2) != 2) {
        fprintf(stderr, "Error reading from ADS1115 conversion register\n");
        return -1;
    }

    adc_value = (buf[0] << 8) | buf[1];

    return adc_value;
}

// Publishes the sensor reading to the MQTT broker
void publish_mqtt(struct mosquitto *mosq, const char *topic, const char *payload) {
    int ret = mosquitto_publish(mosq, NULL, topic, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
    }
}

int main() {
    int i;
    int adc_value;
    char payload[50]; // Buffer for the payload string
    struct timeval tv;
    time_t nowtime;
    struct tm *nowtm;
    char tmbuf[64], buf[64];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize libmosquitto
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error creating mosquitto instance\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Connect to MQTT broker
    int ret = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    for (i = 0; i < NUM_READINGS && !terminate; ++i) {
        adc_value = read_ads1115(i2c_handle);
        if (adc_value >= 0) {
            // Get current timestamp
            gettimeofday(&tv, NULL);
            nowtime = tv.tv_sec;
            nowtm = localtime(&nowtime);
            strftime(tmbuf, sizeof(tmbuf), "%Y-%m-%d %H:%M:%S", nowtm);
            snprintf(buf, sizeof(buf), "%s.%06ld", tmbuf, tv.tv_usec);

            // Format the payload
            snprintf(payload, sizeof(payload), "{\"timestamp\": \"%s\", \"value\": %d}", buf, adc_value);

            // Publish the reading
            publish_mqtt(mosq, MQTT_TOPIC, payload);
            printf("Published: %s\n", payload);
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        sleep(1); // Delay between readings
    }

    // Clean up
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

