#define GPIO_18 18

static volatile int keep_running = 1;
struct gpiod_chip *chip;
struct gpiod_line *line17, *line18;

void sigint_handler(int sig)
{
    keep_running = 0;
}

int main()
{
    struct gpiod_line_request_config config;
    int ret;

    /* Initialize signal handler */
    signal(SIGINT, sigint_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    /* Get GPIO lines */
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line17 || !line18) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request GPIO lines as outputs */
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio-test";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line17, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO 17 as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request(line18, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO 18 as output");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop */
    while (keep_running) {
        /* Set GPIO 17 high, GPIO 18 low */
        ret = gpiod_line_set_value(line17, 1);
        if (ret < 0) {
            perror("Error setting GPIO 17 high");
            break;
        }
        ret = gpiod_line_set_value(line18, 0);
        if (ret < 0) {
            perror("Error setting GPIO 18 low");
            break;
        }
        printf("GPIO 17: HIGH, GPIO 18: LOW\n");

        usleep(50000); // 50ms

        /* Set GPIO 17 low, GPIO 18 high */
        ret = gpiod_line_set_value(line17, 0);
        if (ret < 0) {
            perror("Error setting GPIO 17 low");
            break;
        }
        ret = gpiod_line_set_value(line18, 1);
        if (ret < 0) {
            perror("Error setting GPIO 18 high");
            break;
        }
        printf("GPIO 17: LOW, GPIO 18: HIGH\n");

        usleep(50000); // 50ms
    }

    /* Release GPIO lines */
    gpiod_line_release(line17);
    gpiod_line_release(line18);

    /* Close GPIO chip */
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
