#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>

#define UART_PORT "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUD_RATE B9600
#define BUFFER_SIZE 256

volatile sig_atomic_t keep_running = 1;
int uart_fd = -1;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        keep_running = 0;
    }
}

int main() {
    struct termios tty;
    char buffer[BUFFER_SIZE];
    int bytes_read;

    // Register signal handler for Ctrl+C
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open the UART port
    uart_fd = open(UART_PORT, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd < 0) {
        perror("Error opening UART port");
        return EXIT_FAILURE;
    }

    // Configure the UART port
    if (tcgetattr(uart_fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(uart_fd);
        return EXIT_FAILURE;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 9600 baud, 8-bit data, no parity, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;                                // Raw output
    tty.c_lflag = 0;                                // Non-canonical mode
    tty.c_cc[VMIN] = 0;                              // Read at least 0 characters
    tty.c_cc[VTIME] = 5;                             // Wait for up to 0.5 seconds (5 * 0.1s)

    if (tcsetattr(uart_fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(uart_fd);
        return EXIT_FAILURE;
    }

    printf("UART communication started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        bytes_read = read(uart_fd, buffer, BUFFER_SIZE - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0'; // Null-terminate the string
            printf("Received: %s", buffer);
        } else if (bytes_read < 0) {
            perror("Error reading from UART");
            break; // Exit loop on error
        } else {
            // Timeout occurred, no data received
            //printf("Timeout waiting for data.\n"); //Optional timeout message
        }
        usleep(100000); // Sleep for 100ms to avoid busy-waiting
    }

    // Close the UART port
    if (uart_fd != -1) {
        close(uart_fd);
    }

    printf("UART communication stopped.\n");

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B

int i2c_fd = -1;

void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    int retries = 3;
    while (retries > 0) {
        i2c_fd = open("/dev/i2c-1", O_RDWR);
        if (i2c_fd < 0) {
            perror("Error opening I2C device");
            retries--;
            sleep(1);
            continue;
        }

        if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
            perror("Error setting I2C slave address");
            close(i2c_fd);
            i2c_fd = -1;
            retries--;
            sleep(1);
            continue;
        }

        // Wake up the MPU6050
        uint8_t wake_up_data[] = {PWR_MGMT_1, 0x00};
        if (write(i2c_fd, wake_up_data, 2) != 2) {
            perror("Error writing to I2C device");
            close(i2c_fd);
            i2c_fd = -1;
            retries--;
            sleep(1);
            continue;
        }

        break; // Success, exit retry loop
    }

    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to initialize I2C after multiple retries.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (1) {
        uint8_t read_buffer[14];
        uint8_t read_command = ACCEL_XOUT_H;

        if (write(i2c_fd, &read_command, 1) != 1) {
            perror("Error writing read command");
            close(i2c_fd);
            return 1;
        }

        if (read(i2c_fd, read_buffer, 14) != 14) {
            perror("Error reading from I2C device");
            close(i2c_fd);
            return 1;
        }

        int16_t accel_x = (read_buffer[0] << 8) | read_buffer[1];
        int16_t accel_y = (read_buffer[2] << 8) | read_buffer[3];
        int16_t accel_z = (read_buffer[4] << 8) | read_buffer[5];
        int16_t temp = (read_buffer[6] << 8) | read_buffer[7];
        int16_t gyro_x = (read_buffer[8] << 8) | read_buffer[9];
        int16_t gyro_y = (read_buffer[10] << 8) | read_buffer[11];
        int16_t gyro_z = (read_buffer[12] << 8) | read_buffer[13];

        printf("AccelX: %d, AccelY: %d, AccelZ: %d, Temp: %d, GyroX: %d, GyroY: %d, GyroZ: %d\n",
               accel_x, accel_y, accel_z, temp, gyro_x, gyro_y, gyro_z);

        usleep(100000); // 0.1 seconds
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_PRESSURE_MSB 0xF7
#define BMP280_REG_CTRL_MEAS 0xF4

int i2c_fd = -1;

void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    int retries = 3;
    int delay_ms = 100;
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = delay_ms * 1000000; // Convert milliseconds to nanoseconds

    signal(SIGINT, signal_handler);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Set the BMP280 to forced mode
    unsigned char ctrl_meas = 0b00110011; // Oversampling x1, Normal mode
    if (write(i2c_fd, &ctrl_meas, 1) != 1) {
        perror("Error writing to I2C device");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        unsigned char data[6];
        int bytes_read;

        // Read temperature and pressure registers
        if (write(i2c_fd, (unsigned char[]){BMP280_REG_PRESSURE_MSB}, 1) != 1) {
            perror("Error writing register address");
            close(i2c_fd);
            return 1;
        }

        bytes_read = read(i2c_fd, data, 6);
        if (bytes_read != 6) {
            fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
            close(i2c_fd);
            return 1;
        }

        // Combine the values
        long pressure_raw = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
        long temperature_raw = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);

        printf("Raw Pressure: %ld, Raw Temperature: %ld\n", pressure_raw, temperature_raw);

        sleep(5);
    }

    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_GPIO 4 // BCM GPIO 4
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000 // Range of 0-1000 for duty cycle percentage

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...");
    terminate = 1;
}

int main() {
    int i, rc;
    double duty_cycle;

    // Register signal handlers for graceful termination
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 4 as output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    printf("PWM output started on GPIO %d with frequency %d Hz and range %d\n", PWM_GPIO, PWM_FREQUENCY, PWM_RANGE);

    // Ramp up duty cycle from 0% to 100%
    for (i = 0; i <= 100; ++i) {
        if (terminate) break;
        duty_cycle = (double)i / 100.0 * PWM_RANGE;
        gpioPWM(PWM_GPIO, (int)duty_cycle);
        printf("Duty cycle: %.2f%%\n", duty_cycle / PWM_RANGE * 100.0);
        gpioDelay(50000); // 50ms delay
    }

    // Ramp down duty cycle from 100% to 0%
    for (i = 99; i >= 0; --i) {
        if (terminate) break;
        duty_cycle = (double)i / 100.0 * PWM_RANGE;
        gpioPWM(PWM_GPIO, (int)duty_cycle);
        printf("Duty cycle: %.2f%%\n", duty_cycle / PWM_RANGE * 100.0);
        gpioDelay(50000); // 50ms delay
    }

    // Stop PWM output
    gpioPWM(PWM_GPIO, 0);

    // Terminate pigpio library
    gpioTerminate();

    printf("PWM output stopped.\n");

    return 0;
}

