    while (keepRunning) {
        // Read sensor data
        float temperature = readSensorData();

        // Publish sensor data
        if (publishSensorData(temperature) != 0) {
            fprintf(stderr, "Failed to publish sensor data.\n");
        }

        // Wait for the specified interval
        usleep(READ_INTERVAL_MS * 1000); // Convert milliseconds to microseconds
    }

    // Disconnect from the MQTT broker
    mosquitto_disconnect(mqtt_client);

    // Destroy the MQTT client instance
    mosquitto_destroy(mqtt_client);

    // Clean up libmosquitto
    mosquitto_lib_cleanup();

    printf("Exiting.\n");
    return 0;
}

