#define GPIO_18 18
#define GPIO_23 23
#define GPIO_24 24

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal)
{
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
    program_running = 0;
}

int main()
{
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_2, PI_OUTPUT);
    gpioSetMode(GPIO_3, PI_OUTPUT);
    gpioSetMode(GPIO_18, PI_OUTPUT);
    gpioSetMode(GPIO_23, PI_OUTPUT);
    gpioSetMode(GPIO_24, PI_OUTPUT);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(GPIO_2, 1000); // 1 kHz
    gpioSetPWMfrequency(GPIO_3, 1000);
    gpioSetPWMfrequency(GPIO_18, 1000);
    gpioSetPWMfrequency(GPIO_23, 1000);
    gpioSetPWMfrequency(GPIO_24, 1000);

    // Main loop
    while (program_running)
    {
        // Drive GPIO 2 with 50% duty cycle
        gpioPWM(GPIO_2, 128); // 128/255 = ~50%
        printf("GPIO %d: 50%%\n", GPIO_2);

        // Drive GPIO 3 with 75% duty cycle
        gpioPWM(GPIO_3, 192); // 192/255 = ~75%
        printf("GPIO %d: 75%%\n", GPIO_3);

        // Drive GPIO 18 with 25% duty cycle
        gpioPWM(GPIO_18, 64); // 64/255 = ~25%
        printf("GPIO %d: 25%%\n", GPIO_18);

        // Drive GPIO 23 with 100% duty cycle
        gpioPWM(GPIO_23, 255); // 255/255 = 100%
        printf("GPIO %d: 100%%\n", GPIO_23);

        // Drive GPIO 24 with 0% duty cycle
        gpioPWM(GPIO_24, 0); // 0/255 = 0%
        printf("GPIO %d: 0%%\n", GPIO_24);

        // Wait for a short period
        gpioDelay(1000000); // 1 second
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

