#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN_17 17
#define GPIO_PIN_27 27

static volatile int keep_running = 1;
struct gpiod_chip *chip;
struct gpiod_line *line17, *line27;

void sigint_handler(int sig)
{
    keep_running = 0;
}

int main()
{
    struct gpiod_line_request_config config;
    int ret;

    /* Initialize signal handler */
    signal(SIGINT, sigint_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Open chip failed");
        return EXIT_FAILURE;
    }

    /* Get GPIO line for GPIO 17 */
    line17 = gpiod_chip_get_line(chip, GPIO_PIN_17);
    if (!line17) {
        perror("Get line 17 failed");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Get GPIO line for GPIO 27 */
    line27 = gpiod_chip_get_line(chip, GPIO_PIN_27);
    if (!line27) {
        perror("Get line 27 failed");
        gpiod_chip_close(chip);
        gpiod_line_release(line17);
        return EXIT_FAILURE;
    }

    /* Configure line request */
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio-test";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    /* Request GPIO line for GPIO 17 */
    ret = gpiod_line_request(line17, &config, 0);
    if (ret < 0) {
        perror("Request line 17 failed");
        gpiod_chip_close(chip);
        gpiod_line_release(line17);
        gpiod_line_release(line27);
        return EXIT_FAILURE;
    }

    /* Request GPIO line for GPIO 27 */
    ret = gpiod_line_request(line27, &config, 0);
    if (ret < 0) {
        perror("Request line 27 failed");
        gpiod_chip_close(chip);
        gpiod_line_release(line17);
        gpiod_line_release(line27);
        return EXIT_FAILURE;
    }

    /* Main loop */
    while (keep_running) {
        /* Set GPIO 17 high */
        ret = gpiod_line_set_value(line17, 1);
        if (ret < 0) {
            perror("Set line 17 high failed");
            break;
        }
        /* Set GPIO 27 low */
        ret = gpiod_line_set_value(line27, 0);
        if (ret < 0) {
            perror("Set line 27 low failed");
            break;
        }
        printf("GPIO 17: HIGH, GPIO 27: LOW\n");

        sleep(1);

        /* Set GPIO 17 low */
        ret = gpiod_line_set_value(line17, 0);
        if (ret < 0) {
            perror("Set line 17 low failed");
            break;
        }
        /* Set GPIO 27 high */
        ret = gpiod_line_set_value(line27, 1);
        if (ret < 0) {
            perror("Set line 27 high failed");
            break;
        }
        printf("GPIO 17: LOW, GPIO 27: HIGH\n");

        sleep(1);
    }

    /* Release GPIO lines */
    gpiod_line_release(line17);
    gpiod_line_release(line27);

    /* Close GPIO chip */
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

