#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>

#define UART_PORT "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUD_RATE B9600
#define BUFFER_SIZE 256

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signum) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signum);
}

int main() {
    struct termios tty;
    char buffer[BUFFER_SIZE];
    int bytes_read;

    // Register signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return EXIT_FAILURE;
    }

    // Open UART port
    uart_fd = open(UART_PORT, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd == -1) {
        perror("Error opening UART port");
        return EXIT_FAILURE;
    }

    // Configure UART settings
    if (tcgetattr(uart_fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(uart_fd);
        return EXIT_FAILURE;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 9600 baud, 8-bit chars, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;                                // Raw output
    tty.c_lflag = 0;                                // Non-canonical mode
    tty.c_cc[VMIN] = 0;                              // Read at least 0 characters
    tty.c_cc[VTIME] = 5;                             // Wait for up to 0.5 seconds (5 * 0.1s)

    if (tcsetattr(uart_fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(uart_fd);
        return EXIT_FAILURE;
    }

    printf("UART communication started on %s at %d baud.\n", UART_PORT, BAUD_RATE);

    while (program_running) {
        bytes_read = read(uart_fd, buffer, BUFFER_SIZE - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0'; // Null-terminate the string
            printf("Received: %s\n", buffer);
        } else if (bytes_read < 0) {
            if (errno == EAGAIN || errno == EINTR) {
                continue; // Try again if interrupted or no data available
            }
            perror("Error reading from UART");
            break;
        } else {
          //No data received, sleep briefly to avoid busy-waiting
          usleep(100000); // Sleep for 100ms
        }
    }

    // Close UART port
    if (close(uart_fd) != 0) {
        perror("Error closing UART port");
    }

    printf("UART communication stopped.\n");

    return EXIT_SUCCESS;
}

