#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define DHT22_GPIO 4

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    fprintf(stderr, "\nSignal received, terminating gracefully...\n");
    terminate = 1;
}

int read_dht22_data(int gpio_pin, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int byte_index = 0;
    long start_time, end_time, pulse_length;

    gpioSetMode(gpio_pin, PI_OUTPUT);
    gpioWrite(gpio_pin, 0);
    gpioDelay(1);
    gpioWrite(gpio_pin, 1);
    gpioDelay(30); // Changed from 40us to 30us

    gpioSetMode(gpio_pin, PI_INPUT);

    /* Wait for the DHT22 to pull the line low */
    int timeout = 0;
    while (gpioRead(gpio_pin) == 1 && timeout < 100) {
        gpioDelay(1); // Wait 1 us
        timeout++;
    }

    if (timeout >= 100) {
        fprintf(stderr, "DHT22: Timeout waiting for start signal (low)\n");
        return -1;
    }

    /* Wait for the DHT22 to pull the line high */
    timeout = 0;
    while (gpioRead(gpio_pin) == 0 && timeout < 100) {
        gpioDelay(1); // Wait 1 us
        timeout++;
    }

    if (timeout >= 100) {
        fprintf(stderr, "DHT22: Timeout waiting for start signal (high)\n");
        return -1;
    }

    /* Read the 40 bits of data */
    for (int i = 0; i < 40; i++) {
        /* Wait for the line to go low */
        timeout = 0;
        while (gpioRead(gpio_pin) == 1 && timeout < 100) {
            gpioDelay(1); // Wait 1 us
            timeout++;
        }
        if (timeout >= 100) {
            fprintf(stderr, "DHT22: Timeout waiting for bit start (low)\n");
            return -1;
        }

        /* Measure the length of the high pulse */
        start_time = gpioTick();
        timeout = 0;
        while (gpioRead(gpio_pin) == 0 && timeout < 100) {
            gpioDelay(1); // Wait 1 us
            timeout++;
        }
        if (timeout >= 100) {
            fprintf(stderr, "DHT22: Timeout waiting for bit end (high)\n");
            return -1;
        }
        end_time = gpioTick();

        pulse_length = end_time - start_time;

        /* Determine if it's a 0 or a 1 based on pulse length */
        if (pulse_length > 40) { // Adjusted threshold
            data[byte_index] |= (1 << (7 - bit_count));
        }

        bit_count++;
        if (bit_count == 8) {
            bit_count = 0;
            byte_index++;
        }
    }

    /* Checksum validation */
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        fprintf(stderr, "DHT22: Checksum failure\n");
        return -1;
    }

    /* Convert data to temperature and humidity */
    *humidity = (float)((data[0] << 8) | data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature *= -1;
    }

    return 0;
}

int main() {
    float temperature, humidity;
    int result;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    result = read_dht22_data(DHT22_GPIO, &temperature, &humidity);

    if (result == 0) {
        printf("Temperature: %.1f °C, Humidity: %.1f %%\n", temperature, humidity);
    } else {
        fprintf(stderr, "Failed to read DHT22 data\n");
    }

    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"

static volatile int keep_running = 1;
struct gpiod_chip *chip;
struct gpiod_line *line17, *line23, *line24, *line25;

void sigint_handler(int sig)
{
    keep_running = 0;
}

int main()
{
    struct gpiod_line_request_config config;
    int ret;

    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Open chip failed");
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, 17);
    line23 = gpiod_chip_get_line(chip, 23);
    line24 = gpiod_chip_get_line(chip, 24);
    line25 = gpiod_chip_get_line(chip, 25);

    if (!line17 || !line23 || !line24 || !line25) {
        perror("Get line failed");
        goto cleanup_chip;
    }

    gpiod_line_request_config_init(&config);
    config.consumer = "digital_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(line17, &config, 0) < 0 ||
        gpiod_line_request(line23, &config, 0) < 0 ||
        gpiod_line_request(line24, &config, 0) < 0 ||
        gpiod_line_request(line25, &config, 0) < 0) {
        perror("Request line as output failed");
        goto cleanup_lines;
    }

    while (keep_running) {
        ret = gpiod_line_set_value(line17, 1);
        ret |= gpiod_line_set_value(line23, 0);
        ret |= gpiod_line_set_value(line24, 1);
        ret |= gpiod_line_set_value(line25, 0);
        if (ret < 0) {
            perror("Set value failed");
            break;
        }
        printf("GPIO 17: HIGH, GPIO 23: LOW, GPIO 24: HIGH, GPIO 25: LOW\n");

        sleep(10);
    }

cleanup_lines:
    gpiod_line_release(line17);
    gpiod_line_release(line23);
    gpiod_line_release(line24);
    gpiod_line_release(line25);

cleanup_chip:
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <mosquitto.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNELS 8
#define MQTT_BROKER "localhost" // Change this to your broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC_BASE "home/sensors/raspberrypi"
#define NUM_SENSORS 4

// Global variables
static volatile int running = 1;
struct mosquitto *mosq = NULL;

// Structure to hold sensor data
typedef struct {
    int channel;
    char name[50];
} sensor_t;

// Array of sensors
sensor_t sensors[NUM_SENSORS] = {
    {0, "soil_moisture_1"},
    {1, "soil_moisture_2"},
    {2, "light_level"},
    {3, "temperature"}
};

// Function prototypes
int read_mcp3008(int channel);
void publish_sensor_data(int channel, const char* sensor_name, int value);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully.\n", sig);
    running = 0;
}

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char buffer[3];
    buffer[0] = 0x01; // Start bit
    buffer[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    buffer[2] = 0x00;

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    int adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Function to publish sensor data to MQTT broker
void publish_sensor_data(int channel, const char* sensor_name, int value) {
    char topic[200];
    snprintf(topic, sizeof(topic), "%s/%s", MQTT_TOPIC_BASE, sensor_name);

    char payload[50];
    snprintf(payload, sizeof(payload), "%d", value);

    int ret = mosquitto_publish(mosq, NULL, topic, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
    } else {
        printf("Published: %s = %s\n", topic, payload);
    }
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error initializing WiringPi!\n");
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "Error initializing SPI!\n");
        return 1;
    }

    // Initialize Mosquitto
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error creating Mosquitto instance!\n");
        return 1;
    }

    // Connect to MQTT broker
    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int adc_value = read_mcp3008(sensors[i].channel);
            if (adc_value != -1) {
                publish_sensor_data(sensors[i].channel, sensors[i].name, adc_value);
            } else {
                fprintf(stderr, "Error reading sensor %s\n", sensors[i].name);
            }
        }

        sleep(5); // Wait 5 seconds
    }

    // Disconnect from MQTT broker
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();

    printf("Exiting.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define FILENAME "capture.raw"

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffer;
    FILE *fp;

    // Open the video device
    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("Error opening device");
        return 1;
    }

    // Check if it's a V4L2 device
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        close(fd);
        return 1;
    }

    // Set the image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV; // Example format
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return 1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return 1;
    }

    // Query the buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        close(fd);
        return 1;
    }

    // Map the buffer
    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd);
        return 1;
    }

    // Queue the buffer
    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    // Start capturing
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    // Dequeue the buffer
    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    // Save the image to a file
    fp = fopen(FILENAME, "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    fwrite(buffer, buf.bytesused, 1, fp);
    fclose(fp);

    // Stop capturing
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
    }

    // Unmap the buffer
    if (munmap(buffer, buf.length) < 0) {
        perror("Error unmapping buffer");
    }

    // Close the device
    close(fd);

    printf("Image captured and saved as %s\n", FILENAME);
    return 0;
}

#include <stdio.h>
