#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for PWM output
#define PWM_PIN_1 4
#define PWM_PIN_2 5
#define PWM_PIN_3 6
#define PWM_PIN_4 7
#define PWM_PIN_5 8
#define PWM_PIN_6 9

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nSignal received, terminating program...\n");
    terminate = 1;
}

int main()
{
    // Register signal handlers for SIGINT and SIGTERM
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Could not register signal handler.\n");
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);
    gpioSetMode(PWM_PIN_5, PI_OUTPUT);
    gpioSetMode(PWM_PIN_6, PI_OUTPUT);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(PWM_PIN_1, 1000); // 1 kHz
    gpioSetPWMfrequency(PWM_PIN_2, 1000);
    gpioSetPWMfrequency(PWM_PIN_3, 1000);
    gpioSetPWMfrequency(PWM_PIN_4, 1000);
    gpioSetPWMfrequency(PWM_PIN_5, 1000);
    gpioSetPWMfrequency(PWM_PIN_6, 1000);

    // Set PWM duty cycle (adjust as needed)
    gpioPWM(PWM_PIN_1, 128); // 50% duty cycle (0-255 range)
    gpioPWM(PWM_PIN_2, 64);  // 25% duty cycle
    gpioPWM(PWM_PIN_3, 192); // 75% duty cycle
    gpioPWM(PWM_PIN_4, 32);  // 12.5% duty cycle
    gpioPWM(PWM_PIN_5, 160); // 62.5% duty cycle
    gpioPWM(PWM_PIN_6, 80);  // 31.25% duty cycle

    // Print the state of each pin
    printf("PWM Pin %d: Duty Cycle = %d\n", PWM_PIN_1, gpioGetPWMdutycycle(PWM_PIN_1));
    printf("PWM Pin %d: Duty Cycle = %d\n", PWM_PIN_2, gpioGetPWMdutycycle(PWM_PIN_2));
    printf("PWM Pin %d: Duty Cycle = %d\n", PWM_PIN_3, gpioGetPWMdutycycle(PWM_PIN_3));
    printf("PWM Pin %d: Duty Cycle = %d\n", PWM_PIN_4, gpioGetPWMdutycycle(PWM_PIN_4));
    printf("PWM Pin %d: Duty Cycle = %d\n", PWM_PIN_5, gpioGetPWMdutycycle(PWM_PIN_5));
    printf("PWM Pin %d: Duty Cycle = %d\n", PWM_PIN_6, gpioGetPWMdutycycle(PWM_PIN_6));

    // Wait for a short period before exiting
    gpioDelay(2000); // 2 seconds

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated successfully.\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN_17 17
#define GPIO_PIN_18 18

static struct gpiod_chip *chip;
static struct gpiod_line *line17, *line18;

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    if (line17) {
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_release(line18);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    int i, ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line17 = gpiod_chip_get_line(chip, GPIO_PIN_17);
    line18 = gpiod_chip_get_line(chip, GPIO_PIN_18);
    if (!line17 || !line18) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines as outputs
    ret = gpiod_line_request_output(line17, NULL, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line18, NULL, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop: 3 cycles of setting and clearing GPIOs
    for (i = 0; i < 3; i++) {
        // Set GPIO 17 high, GPIO 18 low
        ret = gpiod_line_set_value(line17, 1);
        if (ret < 0) {
            perror("Error setting GPIO value");
            break;
        }
        ret = gpiod_line_set_value(line18, 0);
        if (ret < 0) {
            perror("Error setting GPIO value");
            break;
        }
        printf("GPIO %d HIGH, GPIO %d LOW\n", GPIO_PIN_17, GPIO_PIN_18);
        sleep(1);

        // Set GPIO 17 low, GPIO 18 high
        ret = gpiod_line_set_value(line17, 0);
        if (ret < 0) {
            perror("Error setting GPIO value");
            break;
        }
        ret = gpiod_line_set_value(line18, 1);
        if (ret < 0) {
            perror("Error setting GPIO value");
            break;
        }
        printf("GPIO %d LOW, GPIO %d HIGH\n", GPIO_PIN_17, GPIO_PIN_18);
        sleep(1);
    }

    // Release GPIO lines and close chip
    gpiod_line_release(line17);
    gpiod_line_release(line18);
    gpiod_chip_close(chip);

    return 0;
}

