#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

// Define the I2C address of the PCF8574
#define PCF8574_ADDR 0x20

// Global variable to store the I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting gracefully...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write data to the PCF8574
int pcf8574_write(int fd, uint8_t data) {
    if (write(fd, &data, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int main() {
    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open the I2C device file
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Generate a random number between 0 and 255
        uint8_t random_value = (uint8_t)(rand() % 256);

        // Write the random value to the PCF8574
        if (pcf8574_write(i2c_fd, random_value) != 0) {
            fprintf(stderr, "Error writing to PCF8574, exiting.\n");
            close(i2c_fd);
            return 1;
        }

        // Wait for 0.5 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500000000; // 0.5 seconds
        nanosleep(&sleep_time, NULL);
    }

    // This point will not be reached unless there is an error or the loop is broken.
    close(i2c_fd);
    return 0;
}

