    gpioSetMode(ECHO_PIN, PI_INPUT);

    signal(SIGINT, signal_handler);

    while (!terminate) {
        gpioWrite(TRIGGER_PIN, 0);
        gpioDelay(2);
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, 0);

        uint32_t start_tick = 0;
        uint32_t end_tick = 0;

        // Wait for echo to go high, with timeout
        int count = 0;
        while (gpioRead(ECHO_PIN) == 0 && count < 10000) {
            count++;
            gpioDelay(1); // Small delay to prevent busy-waiting
        }
        if (count >= 10000) {
            fprintf(stderr, "Timeout waiting for echo high\n");
            gpioTerminate();
            return 1;
        }
        start_tick = gpioTick();

        // Wait for echo to go low, with timeout
        count = 0;
        while (gpioRead(ECHO_PIN) == 1 && count < 10000) {
            count++;
            gpioDelay(1);
        }
        if (count >= 10000) {
            fprintf(stderr, "Timeout waiting for echo low\n");
            gpioTerminate();
            return 1;
        }
        end_tick = gpioTick();

        uint32_t diff = end_tick - start_tick;
        float distance = (diff / 1000000.0) * 34300 / 2;

        printf("Distance: %.2f cm\n", distance);
        sleep(1);
    }

    gpioTerminate();
    return 0;
}

