#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define CAPTURE_INTERVAL_MS 100

static int fd = -1; // File descriptor for the video device
static void *buffer = NULL; // Memory buffer for capturing images
static size_t buffer_size = 0; // Size of the memory buffer

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    printf("\nCaught signal %d, cleaning up...\n", signum);
    if (fd != -1) {
        close(fd);
    }
    if (buffer != NULL) {
        munmap(buffer, buffer_size);
    }
    exit(0);
}

int main() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned char *image_data = NULL;
    FILE *fp;
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the video device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("Error opening device");
        return 1;
    }

    // Check if it's a V4L2 device
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        close(fd);
        return 1;
    }

    // Set the image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG; // Request JPEG format
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting format");
        close(fd);
        return 1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Error requesting buffers");
        close(fd);
        return 1;
    }

    // Map the buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("Error querying buffer");
        close(fd);
        return 1;
    }

    buffer_size = buf.length;
    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd);
        return 1;
    }

    // Queue the buffer
    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("Error queuing buffer");
        munmap(buffer, buffer_size);
        close(fd);
        return 1;
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Error starting stream");
        munmap(buffer, buffer_size);
        close(fd);
        return 1;
    }

    // Capture loop
    while (1) {
        // Dequeue the buffer
        if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            perror("Error dequeuing buffer");
            break; // Exit loop on error
        }

        // Capture successful, save the image
        image_data = (unsigned char *)buffer;
        fp = fopen("capture.jpg", "wb");
        if (fp == NULL) {
            perror("Error opening file for writing");
            break; // Exit loop on error
        }

        fwrite(image_data, 1, buf.bytesused, fp);
        fclose(fp);

        printf("Captured image saved as capture.jpg (%d bytes)\n", buf.bytesused);

        // Re-queue the buffer
        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("Error requeuing buffer");
            break; // Exit loop on error
        }

        // Wait for the next capture interval
        usleep(CAPTURE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Stop streaming
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("Error stopping stream");
    }

    // Cleanup
    munmap(buffer, buffer_size);
    close(fd);

    return 0;
}

