#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Constants
#define SPEED_OF_SOUND 34300 // cm/s
#define MAX_DISTANCE 400      // cm
#define TIMEOUT_US 50000       // 50ms timeout

// Global variables
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to measure distance in centimeters
float get_distance()
{
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to start
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US)
    {
        gpioDelay(1); // Check every microsecond
        count++;
    }

    if (count >= TIMEOUT_US)
    {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1.0; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for echo to end
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US)
    {
        gpioDelay(1); // Check every microsecond
        count++;
    }

    if (count >= TIMEOUT_US)
    {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1.0; // Indicate timeout error
    }

    end_tick = gpioTick();

    // Calculate pulse duration
    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = ((float)diff_tick * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate)
    {
        float distance = get_distance();

        if (distance > 0 && distance <= MAX_DISTANCE)
        {
            printf("Distance: %.2f cm\n", distance);
        } else if (distance < 0) {
            fprintf(stderr, "Error: Distance measurement failed.\n");
        } else {
            fprintf(stderr, "Error: Distance out of range (%.2f cm).\n", distance);
        }

        gpioDelay(100); // Delay between measurements
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

