#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

// MPU6050 Registers
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B

int i2c_fd = -1;

void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    int retries = 3;
    while (retries > 0) {
        // Open I2C device
        i2c_fd = open("/dev/i2c-1", O_RDWR);
        if (i2c_fd < 0) {
            perror("Error opening I2C device");
            retries--;
            sleep(1); // Wait before retrying
            continue;
        }

        // Set slave address
        if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
            perror("Error setting I2C slave address");
            close(i2c_fd);
            i2c_fd = -1;
            retries--;
            sleep(1);
            continue;
        }

        // Wake up MPU6050
        uint8_t wake_up_data[] = {PWR_MGMT_1, 0x00};
        if (write(i2c_fd, wake_up_data, 2) != 2) {
            perror("Error writing to I2C device");
            close(i2c_fd);
            i2c_fd = -1;
            retries--;
            sleep(1);
            continue;
        }

        break; // Exit retry loop if successful
    }

    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to initialize MPU6050 after multiple retries.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (1) {
        uint8_t read_buffer[14];
        uint8_t read_command = ACCEL_XOUT_H;

        if (write(i2c_fd, &read_command, 1) != 1) {
            perror("Error writing read command");
            close(i2c_fd);
            i2c_fd = -1;
            return 1;
        }

        if (read(i2c_fd, read_buffer, 14) != 14) {
            perror("Error reading from I2C device");
            close(i2c_fd);
            i2c_fd = -1;
            return 1;
        }

        int16_t accel_x = (read_buffer[0] << 8) | read_buffer[1];
        int16_t accel_y = (read_buffer[2] << 8) | read_buffer[3];
        int16_t accel_z = (read_buffer[4] << 8) | read_buffer[5];
        int16_t temp = (read_buffer[6] << 8) | read_buffer[7];
        int16_t gyro_x = (read_buffer[8] << 8) | read_buffer[9];
        int16_t gyro_y = (read_buffer[10] << 8) | read_buffer[11];
        int16_t gyro_z = (read_buffer[12] << 8) | read_buffer[13];

        printf("AccelX: %d, AccelY: %d, AccelZ: %d, Temp: %d, GyroX: %d, GyroY: %d, GyroZ: %d\n",
               accel_x, accel_y, accel_z, temp, gyro_x, gyro_y, gyro_z);

        usleep(100000); // 0.1 seconds
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_17 17

// Global variable to track program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

int main()
{
    // Register signal handlers for SIGINT and SIGTERM
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_2, PI_OUTPUT);
    gpioSetMode(GPIO_3, PI_OUTPUT);
    gpioSetMode(GPIO_17, PI_OUTPUT);

    // Main loop: 3 cycles of 5 seconds each
    for (int i = 0; i < 3 && !terminate; ++i) {
        // Turn on GPIO 2
        gpioWrite(GPIO_2, 1);
        printf("GPIO %d ON\n", GPIO_2);
        sleep(1);

        // Turn off GPIO 2, turn on GPIO 3
        gpioWrite(GPIO_2, 0);
        gpioWrite(GPIO_3, 1);
