#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <stdint.h>

// SHT31 I2C address
#define SHT31_ADDR 0x44

// Measurement command (High Repeatability, Clock Stretching disabled)
#define MEASURE_CMD 0x2400

// Global variable to store the I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read temperature and humidity from SHT31
int read_sht31(int fd, float *temperature, float *humidity) {
    unsigned char cmd[2];
    unsigned char data[6];
    int ret;

    // Send measurement command
    cmd[0] = (MEASURE_CMD >> 8) & 0xFF;
    cmd[1] = MEASURE_CMD & 0xFF;

    ret = write(fd, cmd, 2);
    if (ret != 2) {
        fprintf(stderr, "Error writing to I2C device: %d\n", ret);
        return -1;
    }

    // Wait for measurement (typical conversion time is 10ms, but we wait longer to be safe)
    usleep(20000); // 20ms

    // Read 6 bytes of data
    ret = read(fd, data, 6);
    if (ret != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", ret);
        return -1;
    }

    // Convert data to temperature and humidity
    uint16_t temp_raw = (data[0] << 8) | data[1];
    uint16_t hum_raw = (data[3] << 8) | data[4];

    *temperature = -45.0 + (175.0 * (float)temp_raw / 65535.0);
    *humidity = 100.0 * (float)hum_raw / 65535.0;

    return 0;
}

int main() {
    const char *i2c_device = "/dev/i2c-1"; // I2C device file
    float temperature, humidity;
    int ret;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        return 1;
    }

    // Set I2C slave address
    ret = ioctl(i2c_fd, I2C_SLAVE, SHT31_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Error setting I2C slave address: %d\n", ret);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read temperature and humidity
        ret = read_sht31(i2c_fd, &temperature, &humidity);
        if (ret == 0) {
            // Print temperature and humidity
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading SHT31 sensor.\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C device (this will never be reached in the infinite loop)
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"

// Array of GPIO pins to control
const int gpios[] = {5, 6, 12, 16, 19, 20, 23, 24, 25, 26};
const int num_gpios = sizeof(gpios) / sizeof(gpios[0]);

struct gpiod_chip *chip;
struct gpiod_line *lines[10];

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);
    for (int i = 0; i < num_gpios; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main()
{
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get line handles and set direction to output
    for (int i = 0; i < num_gpios; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpios[i]);
        if (!lines[i]) {
            perror("Error getting GPIO line");
            goto cleanup;
        }

        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "gpio_control";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

        if (gpiod_line_request(lines[i], &config, 0) < 0) {
            perror("Error setting GPIO direction to output");
            goto cleanup;
        }

        // Set initial value to 1 (HIGH)
        if (gpiod_line_set_value(lines[i], 1) < 0) {
            perror("Error setting GPIO value");
            goto cleanup;
        }

        printf("GPIO %d set to HIGH\n", gpios[i]);
    }

    // Cleanup and close chip
cleanup:
    for (int i = 0; i < num_gpios; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_17 17
#define GPIO_22 22
#define GPIO_27 27

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int result;

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set GPIO pins as outputs */
    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_22, PI_OUTPUT);
    gpioSetMode(GPIO_27, PI_OUTPUT);

    /* Register signal handler for graceful shutdown */
    signal(SIGINT, signal_handler);

    while (!terminate) {
        /* Set GPIO 17 HIGH, 22 LOW, 27 HIGH */
        gpioWrite(GPIO_17, 1);
        gpioWrite(GPIO_22, 0);
        gpioWrite(GPIO_27, 1);
        printf("GPIO 17: HIGH, GPIO 22: LOW, GPIO 27: HIGH\n");

        /* Wait for 1 second */
        gpioDelay(1000000); // microseconds

        /* Set GPIO 17 LOW, 22 HIGH, 27 LOW */
        gpioWrite(GPIO_17, 0);
        gpioWrite(GPIO_22, 1);
        gpioWrite(GPIO_27, 0);
        printf("GPIO 17: LOW, GPIO 22: HIGH, GPIO 27: LOW\n");

        /* Wait for 1 second */
        gpioDelay(1000000); // microseconds
    }

    /* Release GPIO pins */
    gpioSetMode(GPIO_17, PI_INPUT);
    gpioSetMode(GPIO_22, PI_INPUT);
    gpioSetMode(GPIO_27, PI_INPUT);

    /* Terminate pigpio library */
    gpioTerminate();

    return 0;
}

#include <stdio.h>
