// Define GPIO pins for PWM output
#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 22
#define PWM_PIN_4 27

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

int main()
{
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);

    // Set PWM frequency (e.g., 1 kHz)
    gpioSetPWMfrequency(PWM_PIN_1, 1000);
    gpioSetPWMfrequency(PWM_PIN_2, 1000);
    gpioSetPWMfrequency(PWM_PIN_3, 1000);
    gpioSetPWMfrequency(PWM_PIN_4, 1000);

    // Set PWM range (e.g., 0-255)
    gpioSetPWMrange(PWM_PIN_1, 255);
    gpioSetPWMrange(PWM_PIN_2, 255);
    gpioSetPWMrange(PWM_PIN_3, 255);
    gpioSetPWMrange(PWM_PIN_4, 255);

    // Main loop to generate PWM signals
    while (!terminate)
    {
        // Set duty cycle for each pin (example values)
        gpioPWM(PWM_PIN_1, 128); // 50% duty cycle
        gpioPWM(PWM_PIN_2, 64);  // 25% duty cycle
        gpioPWM(PWM_PIN_3, 192); // 75% duty cycle
        gpioPWM(PWM_PIN_4, 0);   // 0% duty cycle (off)

        // Print current state to stdout
        printf("PWM Pin %d: Duty Cycle = %d\n", PWM_PIN_1, 128);
        printf("PWM Pin %d: Duty Cycle = %d\n", PWM_PIN_2, 64);
        printf("PWM Pin %d: Duty Cycle = %d\n", PWM_PIN_3, 192);
        printf("PWM Pin %d: Duty Cycle = %d\n", PWM_PIN_4, 0);

        // Delay for a short period (e.g., 1 second)
        gpioDelay(1000000); // 1 second delay (in microseconds)
    }

    // Stop PWM signals before exiting
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

