#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define NUM_GPIOS 4

// Array of GPIO numbers to control
const int gpios[NUM_GPIOS] = {2, 3, 5, 17};

struct gpiod_chip *chip;
struct gpiod_line *lines[NUM_GPIOS];

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig)
{
    terminate = 1;
}

int main()
{
    int i, ret;
    struct gpiod_line_request_config config;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get line handles for each GPIO
    for (i = 0; i < NUM_GPIOS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpios[i]);
        if (!lines[i]) {
            perror("Error getting GPIO line");
            goto cleanup;
        }
    }

    // Configure line request
    memset(&config, 0, sizeof(config));
    config.consumer = "digital_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    // Set initial value to 0 (low)
    int values[NUM_GPIOS];
    for (i = 0; i < NUM_GPIOS; i++) {
        values[i] = 0;
    }

    // Request lines for output
    for (i = 0; i < NUM_GPIOS; i++) {
        ret = gpiod_line_request(lines[i], &config, 0);
        if (ret < 0) {
            perror("Error requesting GPIO line for output");
            goto cleanup;
        }
    }

    // Main loop
    while (!terminate) {
        // Set all GPIOs high
        for (i = 0; i < NUM_GPIOS; i++) {
            ret = gpiod_line_set_value(lines[i], 1);
            if (ret < 0) {
                perror("Error setting GPIO value");
                goto cleanup;
            }
        }
        printf("GPIOs set HIGH\n");

        sleep(5);

        // Set all GPIOs low
        for (i = 0; i < NUM_GPIOS; i++) {
            ret = gpiod_line_set_value(lines[i], 0);
            if (ret < 0) {
                perror("Error setting GPIO value");
                goto cleanup;
            }
        }
        printf("GPIOs set LOW\n");

        sleep(5);
    }

cleanup:
    // Release lines
    for (i = 0; i < NUM_GPIOS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

