        perror("Open chip failed");
        return EXIT_FAILURE;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_PIN_18);
    if (!line18) {
        perror("Get line 18 failed");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line27 = gpiod_chip_get_line(chip, GPIO_PIN_27);
    if (!line27) {
        perror("Get line 27 failed");
        gpiod_chip_close(chip);
        gpiod_line_release(line18);
        return EXIT_FAILURE;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line18, &config, 0);
    if (ret < 0) {
        perror("Request line 18 as output failed");
        gpiod_chip_close(chip);
        gpiod_line_release(line18);
        gpiod_line_release(line27);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request(line27, &config, 0);
    if (ret < 0) {
        perror("Request line 27 as output failed");
        gpiod_chip_close(chip);
        gpiod_line_release(line18);
        gpiod_line_release(line27);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        ret = gpiod_line_set_value(line18, 1);
        if (ret < 0) {
            perror("Set line 18 value failed");
            break;
        }
        ret = gpiod_line_set_value(line27, 0);
        if (ret < 0) {
            perror("Set line 27 value failed");
            break;
        }
        printf("GPIO %d: 1, GPIO %d: 0\n", GPIO_PIN_18, GPIO_PIN_27);
        usleep(10000);

        ret = gpiod_line_set_value(line18, 0);
        if (ret < 0) {
            perror("Set line 18 value failed");
            break;
        }
        ret = gpiod_line_set_value(line27, 1);
        if (ret < 0) {
            perror("Set line 27 value failed");
            break;
        }
        printf("GPIO %d: 0, GPIO %d: 1\n", GPIO_PIN_18, GPIO_PIN_27);
        usleep(10000);
    }

    gpiod_line_release(line18);
    gpiod_line_release(line27);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

