#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LED_GPIO 18
#define NUM_PIXELS 16

int pixels[NUM_PIXELS][3]; // RGB values for each pixel

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to set the color of a specific pixel
void setPixelColor(int pixelIndex, int red, int green, int blue) {
    if (pixelIndex >= 0 && pixelIndex < NUM_PIXELS) {
        pixels[pixelIndex][0] = red;
        pixels[pixelIndex][1] = green;
        pixels[pixelIndex][2] = blue;
    } else {
        fprintf(stderr, "Error: Invalid pixel index: %d\n", pixelIndex);
    }
}

// Function to apply the color data to the LED strip
void applyColors() {
    for (int i = 0; i < NUM_PIXELS; ++i) {
        // Simple PWM approximation - adjust duty cycle based on color intensity
        // This is a very basic approach and may not produce accurate colors.
        // A proper WS2812 driver would be needed for real WS2812 strips.
        int brightness = (pixels[i][0] + pixels[i][1] + pixels[i][2]) / 3; // Average brightness
        gpioPWM(LED_GPIO, brightness); // Set PWM duty cycle
        gpioDelay(100); // Small delay to allow PWM to take effect
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop: 3 cycles of color changes
    for (int cycle = 0; cycle < 3 && !terminate; ++cycle) {
        // Cycle 1: Red
        for (int i = 0; i < NUM_PIXELS; ++i) {
            setPixelColor(i, 255, 0, 0);
        }
        applyColors();
        gpioDelay(5000); // 5ms

        // Cycle 2: Green
        for (int i = 0; i < NUM_PIXELS; ++i) {
            setPixelColor(i, 0, 255, 0);
        }
        applyColors();
        gpioDelay(5000); // 5ms

        // Cycle 3: Blue
        for (int i = 0; i < NUM_PIXELS; ++i) {
            setPixelColor(i, 0, 0, 255);
        }
        applyColors();
        gpioDelay(5000); // 5ms
    }

    // Turn off LEDs before exiting
    gpioWrite(LED_GPIO, 0);

    gpioTerminate();
    printf("Program terminated successfully.\n");
    return 0;
}

