#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define W1_DEVICES_DIR "/sys/bus/w1/devices"
#define MAX_RETRIES 3

static volatile int keep_running = 1;

void sigint_handler(int sig) {
    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to find the first DS18B20 device ID
char* find_ds18b20_device() {
    DIR *d;
    struct dirent *dir;
    d = opendir(W1_DEVICES_DIR);
    if (d) {
        while ((dir = readdir(d)) != NULL) {
            if (strncmp(dir->d_name, "28-", 3) == 0) {
                char *device_id = strdup(dir->d_name);
                closedir(d);
                return device_id;
            }
        }
        closedir(d);
    }
    return NULL;
}

// Function to read the temperature from the DS18B20 sensor
float read_temperature(const char *device_id) {
    char filepath[256];
    snprintf(filepath, sizeof(filepath), "%s/%s/w1_slave", W1_DEVICES_DIR, device_id);

    FILE *fp = fopen(filepath, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", filepath, strerror(errno));
        return -1000.0; // Indicate error with a very low temperature
    }

    char line1[256], line2[256];
    if (fgets(line1, sizeof(line1), fp) == NULL || fgets(line2, sizeof(line2), fp) == NULL) {
        fprintf(stderr, "Error reading from %s\n", filepath);
        fclose(fp);
        return -1000.0;
    }

    fclose(fp);

    if (strstr(line1, "YES") == NULL) {
        fprintf(stderr, "CRC check failed in %s\n", filepath);
        return -1000.0;
    }

    char *temp_str = strstr(line2, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Temperature data not found in %s\n", filepath);
        return -1000.0;
    }

    long temp_raw = strtol(temp_str + 2, NULL, 10);
    return (float)temp_raw / 1000.0;
}

int main() {
    signal(SIGINT, sigint_handler);

    char *device_id = find_ds18b20_device();
    if (device_id == NULL) {
        fprintf(stderr, "No DS18B20 device found!\n");
        return 1;
    }

    printf("Found DS18B20 device: %s\n", device_id);

    for (int i = 0; i < 3 && keep_running; ++i) {
        float temperature = read_temperature(device_id);
        if (temperature > -999.0) { // Check for valid temperature reading
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature after multiple retries.\n");
        }
        sleep(5);
    }

    free(device_id);
    return 0;
}

