// Define GPIO pins for PWM output
#define PWM_PIN_1 4
#define PWM_PIN_2 17
#define PWM_PIN_3 18

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to set PWM duty cycle on a given GPIO pin
int set_pwm_dutycycle(int gpio_pin, int dutycycle) {
    if (gpio_pin != PWM_PIN_1 && gpio_pin != PWM_PIN_2 && gpio_pin != PWM_PIN_3) {
        fprintf(stderr, "Error: Invalid GPIO pin number: %d\n", gpio_pin);
        return -1; // Indicate error
    }

    if (dutycycle < 0 || dutycycle > 255) {
        fprintf(stderr, "Error: Invalid duty cycle value: %d. Must be between 0 and 255.\n", dutycycle);
        return -1; // Indicate error
    }

    gpioPWM(gpio_pin, dutycycle);
    return 0; // Indicate success
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1; // Exit with error
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Generate random duty cycle values
        int dutycycle1 = rand() % 256;
        int dutycycle2 = rand() % 256;
        int dutycycle3 = rand() % 256;

        // Set PWM duty cycles
        if (set_pwm_dutycycle(PWM_PIN_1, dutycycle1) != 0) {
            fprintf(stderr, "Error setting duty cycle for GPIO %d\n", PWM_PIN_1);
        }
        if (set_pwm_dutycycle(PWM_PIN_2, dutycycle2) != 0) {
            fprintf(stderr, "Error setting duty cycle for GPIO %d\n", PWM_PIN_2);
        }
        if (set_pwm_dutycycle(PWM_PIN_3, dutycycle3) != 0) {
            fprintf(stderr, "Error setting duty cycle for GPIO %d\n", PWM_PIN_3);
        }

        // Print current state
        printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n", PWM_PIN_1, dutycycle1, PWM_PIN_2, dutycycle2, PWM_PIN_3, dutycycle3);

        // Wait for 0.1 seconds
