#define CHIP_NAME "gpiochip0"
#define NUM_GPIOS 5

const int gpios[] = {8, 9, 10, 11, 17};
struct gpiod_chip *chip;
struct gpiod_line *lines[NUM_GPIOS];

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig)
{
    terminate = 1;
}

int main()
{
    int i, ret;
    struct gpiod_line_request_config config;

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get line handles and set direction to output
    for (i = 0; i < NUM_GPIOS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpios[i]);
        if (!lines[i]) {
            perror("Error getting GPIO line");
            goto cleanup;
        }

        gpiod_line_request_config_init(&config);
        config.consumer = "gpio-output";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

        ret = gpiod_line_request(lines[i], &config, 0);
        if (ret < 0) {
            perror("Error setting GPIO direction to output");
            goto cleanup;
        }
    }

    // Set GPIOs HIGH and report state
    for (i = 0; i < NUM_GPIOS; i++) {
        ret = gpiod_line_set_value(lines[i], 1);
        if (ret < 0) {
            perror("Error setting GPIO value");
            goto cleanup;
        }
        printf("GPIO %d: HIGH\n", gpios[i]);
    }

    sleep(1);

    // Set GPIOs LOW and report state
    for (i = 0; i < NUM_GPIOS; i++) {
        ret = gpiod_line_set_value(lines[i], 0);
        if (ret < 0) {
            perror("Error setting GPIO value");
            goto cleanup;
        }
        printf("GPIO %d: LOW\n", gpios[i]);
    }

cleanup:
    // Release lines and close chip
    for (i = 0; i < NUM_GPIOS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DHT22_GPIO 4

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

int read_dht22(float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int pulse_counts[80];
    int i, j;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1);
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30);

    gpioSetMode(DHT22_GPIO, PI_INPUT);

    /* Read pulses */
    for (i = 0; i < 80; i++) {
        int count = 0;
        while (gpioRead(DHT22_GPIO) == (i % 2 == 0 ? 0 : 1)) {
            count++;
            gpioDelay(1); // Delay 1 us
            if (count > 200) return -1; // Timeout
        }
        pulse_counts[i] = count;
    }

    /* Decode data */
    for (i = 0; i < 40; i++) {
        int index = 2 * i + 1;
        if (pulse_counts[index] > pulse_counts[index + 1]) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    /* Validate checksum */
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        fprintf(stderr, "Checksum failure\n");
        return -1;
    }

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature *= -1;
    }

    return 0;
}

int main() {
    int i;
    float temperature, humidity;
    int result;

    signal(SIGINT, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (i = 0; i < 3 && !terminate; i++) {
        result = read_dht22(&temperature, &humidity);
        if (result == 0) {
            printf("Cycle %d: Temperature = %.1f°C, Humidity = %.1f%%\n", i + 1, temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read DHT22 data (attempt %d)\n", i + 1);
            if (i == 2) {
                fprintf(stderr, "Giving up after 3 failed attempts.\n");
            }
        }
        sleep(2);
    }

    gpioTerminate();
    return 0;
}

