#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN_17 17
#define GPIO_PIN_27 27

static struct gpiod_chip *chip;
static struct gpiod_line *line17, *line27;

// Signal handler for clean exit
void signal_handler(int sig)
{
    printf("\nExiting cleanly...\n");
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line27) {
        gpiod_line_release(line27);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main()
{
    int value17 = 0; // Initial value for GPIO 17
    int value27 = 1; // Initial value for GPIO 27

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line for GPIO 17
    line17 = gpiod_chip_get_line(chip, GPIO_PIN_17);
    if (!line17) {
        perror("Error getting GPIO 17 line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Get GPIO line for GPIO 27
    line27 = gpiod_chip_get_line(chip, GPIO_PIN_27);
    if (!line27) {
        perror("Error getting GPIO 27 line");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output_flags(line17, NULL, GPIOD_LINE_REQUEST_FLAG_OPEN_DRAIN, value17) < 0) {
        perror("Error requesting GPIO 17 as output");
        gpiod_line_release(line17);
        gpiod_line_release(line27);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output_flags(line27, NULL, GPIOD_LINE_REQUEST_FLAG_OPEN_DRAIN, value27) < 0) {
        perror("Error requesting GPIO 27 as output");
        gpiod_line_release(line17);
        gpiod_line_release(line27);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 17 high
        if (gpiod_line_set_value(line17, 1) < 0) {
            perror("Error setting GPIO 17 high");
        } else {
            printf("GPIO %d: HIGH\n", GPIO_PIN_17);
        }

        // Set GPIO 27 low
        if (gpiod_line_set_value(line27, 0) < 0) {
            perror("Error setting GPIO 27 low");
        } else {
            printf("GPIO %d: LOW\n", GPIO_PIN_27);
        }

        sleep(5);

        // Set GPIO 17 low
        if (gpiod_line_set_value(line17, 0) < 0) {
            perror("Error setting GPIO 17 low");
        } else {
            printf("GPIO %d: LOW\n", GPIO_PIN_17);
        }

        // Set GPIO 27 high
        if (gpiod_line_set_value(line27, 1) < 0) {
            perror("Error setting GPIO 27 high");
        } else {
            printf("GPIO %d: HIGH\n", GPIO_PIN_27);
        }

        sleep(5);
    }

    // This part will not be reached due to the infinite loop, but it's good practice to include it.
    gpiod_line_release(line17);
    gpiod_line_release(line27);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for PWM output
#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 22
#define PWM_PIN_4 23
#define PWM_PIN_5 24
#define PWM_PIN_6 25

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);
    gpioSetMode(PWM_PIN_5, PI_OUTPUT);
    gpioSetMode(PWM_PIN_6, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        // Generate random duty cycles for each PWM pin
        int duty_cycle_1 = rand() % 256;
        int duty_cycle_2 = rand() % 256;
        int duty_cycle_3 = rand() % 256;
        int duty_cycle_4 = rand() % 256;
        int duty_cycle_5 = rand() % 256;
        int duty_cycle_6 = rand() % 256;

        // Set PWM duty cycles
        gpioPWM(PWM_PIN_1, duty_cycle_1);
        gpioPWM(PWM_PIN_2, duty_cycle_2);
        gpioPWM(PWM_PIN_3, duty_cycle_3);
        gpioPWM(PWM_PIN_4, duty_cycle_4);
        gpioPWM(PWM_PIN_5, duty_cycle_5);
        gpioPWM(PWM_PIN_6, duty_cycle_6);

        // Print the current state
        printf("PWM Pin %d: Duty Cycle = %d\n", PWM_PIN_1, duty_cycle_1);
        printf("PWM Pin %d: Duty Cycle = %d\n", PWM_PIN_2, duty_cycle_2);
        printf("PWM Pin %d: Duty Cycle = %d\n", PWM_PIN_3, duty_cycle_3);
        printf("PWM Pin %d: Duty Cycle = %d\n", PWM_PIN_4, duty_cycle_4);
        printf("PWM Pin %d: Duty Cycle = %d\n", PWM_PIN_5, duty_cycle_5);
        printf("PWM Pin %d: Duty Cycle = %d\n", PWM_PIN_6, duty_cycle_6);

        // Wait for 0.05 seconds
        gpioDelay(50000); // 50000 microseconds = 0.05 seconds
    }

    // Stop PWM signals before exiting
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);
    gpioPWM(PWM_PIN_5, 0);
    gpioPWM(PWM_PIN_6, 0);

    // Terminate the pigpio library
    gpioTerminate();

    printf("Program terminated successfully.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <unistd.h>

#define CHIP_NAME "gpiochip0"
#define GPIO_17 17
#define GPIO_23 23
#define GPIO_24 24

struct gpiod_chip *chip;
struct gpiod_line *line17, *line23, *line24;

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int ret;
    struct timespec sleep_time = {1, 0}; // 1 second
    int value17 = 0, value23 = 0, value24 = 0;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    line23 = gpiod_chip_get_line(chip, GPIO_23);
    line24 = gpiod_chip_get_line(chip, GPIO_24);

    if (!line17 || !line23 || !line24) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line17, "my_program", 0);
    if (ret < 0) {
        perror("Error requesting GPIO 17 as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line23, "my_program", 0);
    if (ret < 0) {
        perror("Error requesting GPIO 23 as output");
        gpiod_chip_close(chip);
        gpiod_line_release(line17);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line24, "my_program", 0);
    if (ret < 0) {
        perror("Error requesting GPIO 24 as output");
        gpiod_chip_close(chip);
        gpiod_line_release(line17);
        gpiod_line_release(line23);
        return EXIT_FAILURE;
    }

    while (!terminate) {
        ret = gpiod_line_set_value(line17, value17);
        if (ret < 0) {
            perror("Error setting GPIO 17 value");
            break;
        }
        ret = gpiod_line_set_value(line23, value23);
        if (ret < 0) {
            perror("Error setting GPIO 23 value");
            break;
        }
        ret = gpiod_line_set_value(line24, value24);
        if (ret < 0) {
            perror("Error setting GPIO 24 value");
            break;
        }

        printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n", GPIO_17, value17, GPIO_23, value23, GPIO_24, value24);

        value17 ^= 1; // Toggle value
        value23 ^= 1;
        value24 ^= 1;

        nanosleep(&sleep_time, NULL);
    }

    gpiod_line_release(line17);
    gpiod_line_release(line23);
    gpiod_line_release(line24);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DHT22_GPIO_1 4
#define DHT22_GPIO_2 17

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int read_dht22(int gpio_pin, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int pulse_counts[80];
    int i, j;

    gpioSetMode(gpio_pin, PI_OUTPUT);
    gpioWrite(gpio_pin, 0);
    gpioDelay(1);
    gpioWrite(gpio_pin, 1);
    gpioDelay(30);

    gpioSetMode(gpio_pin, PI_INPUT);

    /* Read pulses */
    for (i = 0; i < 80; i++) {
        int count = 0;
        while (gpioRead(gpio_pin) == (i % 2 == 0 ? 0 : 1)) {
            count++;
            gpioDelay(1); // Delay 1 us
            if (count > 200) return -1; // Timeout
        }
        pulse_counts[i] = count;
    }

    /* Decode data */
    for (i = 0; i < 40; i++) {
        int index = 2 * i + 1;
        if (pulse_counts[index] > pulse_counts[index + 1]) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    /* Validate checksum */
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        return -2; // Checksum error
    }

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature *= -1;
    }

    return 0;
}

int main() {
    int i;
    float temperature1, humidity1, temperature2, humidity2;
    int result1, result2;

    signal(SIGINT, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (i = 0; i < 3 && !terminate; i++) {
        result1 = read_dht22(DHT22_GPIO_1, &temperature1, &humidity1);
        result2 = read_dht22(DHT22_GPIO_2, &temperature2, &humidity2);

        if (result1 == 0) {
            printf("DHT22 Sensor 1 (GPIO %d): Temperature = %.1f°C, Humidity = %.1f%%\n", DHT22_GPIO_1, temperature1, humidity1);
        } else {
            fprintf(stderr, "DHT22 Sensor 1 (GPIO %d) read failed: Error code %d\n", DHT22_GPIO_1, result1);
        }

        if (result2 == 0) {
            printf("DHT22 Sensor 2 (GPIO %d): Temperature = %.1f°C, Humidity = %.1f%%\n", DHT22_GPIO_2, temperature2, humidity2);
        } else {
            fprintf(stderr, "DHT22 Sensor 2 (GPIO %d) read failed: Error code %d\n", DHT22_GPIO_2, result2);
        }

        sleep(60);
    }

    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define NUM_GPIOS 5

const int gpios[] = {8, 9, 10, 11, 23};
struct gpiod_chip *chip;
struct gpiod_line *lines[NUM_GPIOS];

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig)
{
    terminate = 1;
}

int main()
{
    int i, ret;
    struct gpiod_line_request_config config;

    // Initialize signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get lines and set direction to output
    for (i = 0; i < NUM_GPIOS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpios[i]);
        if (!lines[i]) {
            perror("Error getting GPIO line");
            goto cleanup;
        }

        memset(&config, 0, sizeof(config));
        config.consumer = "gpio_control";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

        ret = gpiod_line_request(lines[i], &config, 0);
        if (ret < 0) {
            perror("Error setting GPIO direction to output");
            goto cleanup;
        }
    }

    // Main loop: 3 cycles of setting and clearing each GPIO
    for (int cycle = 0; cycle < 3 && !terminate; cycle++) {
        for (i = 0; i < NUM_GPIOS; i++) {
            ret = gpiod_line_set_value(lines[i], 1);
            if (ret < 0) {
                perror("Error setting GPIO value");
                goto cleanup;
            }
            printf("GPIO %d set to HIGH\n", gpios[i]);
            usleep(100000); // 100ms

            ret = gpiod_line_set_value(lines[i], 0);
            if (ret < 0) {
                perror("Error setting GPIO value");
                goto cleanup;
            }
            printf("GPIO %d set to LOW\n", gpios[i]);
            usleep(100000); // 100ms
        }
        sleep(1); // Wait 1 second between cycles
    }

cleanup:
    // Release lines and close chip
    for (i = 0; i < NUM_GPIOS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

