#define SPI_BUS 0
#define SPI_CHIP_SELECT 0
#define SPI_DEVICE_PATH "/dev/spidev0.0"

int spi_fd;

// Function to initialize SPI
int spi_init()
{
    int mode = SPI_MODE_0;
    int bits_per_word = 8;
    int speed = 1000000; // 1 MHz

    spi_fd = open(SPI_DEVICE_PATH, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &bits_per_word) == -1) {
        fprintf(stderr, "Error getting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read data from MAX31855
int read_max31855(uint8_t *data)
{
    struct spi_ioc_transfer transfer = {
        .tx_buf = 0, // Read only, so no transmit buffer
        .rx_buf = (unsigned long)data,
        .len = 4,       // MAX31855 returns 4 bytes
        .delay_usecs = 0,
        .speed_hz = 1000000, // 1 MHz
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to process MAX31855 data
void process_max31855_data(const uint8_t *data)
{
    int16_t raw_temp = ((int16_t)data[0] << 8) | data[1];
    float temperature = (float)(raw_temp >> 2) * 0.25;

    // Check for fault conditions
    if (data[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open circuit\n");
    } else if (data[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
    } else if (data[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
    } else {
        printf("Temperature: %.2f °C\n", temperature);
    }
}

int main()
{
    uint8_t data[4];

    if (spi_init() != 0) {
        return EXIT_FAILURE;
    }

    if (read_max31855(data) != 0) {
        close(spi_fd);
        return EXIT_FAILURE;
    }

    process_max31855_data(data);

    close(spi_fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
