#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17

// Constants
#define SPEED_OF_SOUND 34300 // cm/s
#define TIMEOUT_US 50000      // 50ms timeout

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to measure distance in centimeters
float getDistance()
{
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Measure echo pulse width
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0)
    {
        end_tick = gpioTick();
        diff_tick = end_tick - start_tick;
        if (diff_tick > TIMEOUT_US)
        {
            fprintf(stderr, "Timeout waiting for rising edge\n");
            return -1.0; // Indicate timeout error
        }
    }

    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 1)
    {
        end_tick = gpioTick();
        diff_tick = end_tick - start_tick;
        if (diff_tick > TIMEOUT_US)
        {
            fprintf(stderr, "Timeout waiting for falling edge\n");
            return -1.0; // Indicate timeout error
        }
    }
    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    float time_taken_s = (float)diff_tick / 1000000.0; // Time in seconds
    float distance_cm = (time_taken_s * SPEED_OF_SOUND) / 2.0;

    return distance_cm;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate)
    {
        float distance = getDistance();

        if (distance >= 0)
        {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: Could not read distance.\n");
        }

        gpioDelay(100); // Delay between measurements
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18

static struct gpiod_chip *chip;
static struct gpiod_line *line;

void cleanup(int signum) {
    printf("\nCleaning up and exiting...\n");
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    int ret;
    int value = 1; // Initial value: HIGH

    signal(SIGINT, cleanup);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line, "rpi_gpio_control", value);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO %d set to %s\n", GPIO_PIN, (value == 1) ? "HIGH" : "LOW");

    gpiod_line_set_value(line, value);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_PRESSURE_MSB 0xF7
#define BMP280_REG_CTRL_MEAS 0xF4

int main() {
    int file;
    const char *i2c_device = "/dev/i2c-1"; // Standard I2C device on Raspberry Pi
    unsigned char data[6];
    int i;

    // Open I2C device
    if ((file = open(i2c_device, O_RDWR)) < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Specify slave address
    if (ioctl(file, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(file);
        return 1;
    }

    // Set the BMP280 to forced mode
    unsigned char ctrl_meas = 0b00110011; // Oversampling x1, Normal mode
    if (write(file, &ctrl_meas, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        close(file);
        return 1;
    }

    // Read temperature and pressure data
    for (i = 0; i < 3; i++) {
        // Read 6 bytes of data (pressure MSB, LSB, XLSB, temp MSB, LSB, XLSB)
        if (read(file, data, 6) != 6) {
            fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
            close(file);
            return 1;
        }

        // Combine pressure data
        int32_t pressure_raw = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);

        // Combine temperature data
        int32_t temperature_raw = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);

        printf("Reading %d: Pressure Raw = %d, Temperature Raw = %d\n", i + 1, pressure_raw, temperature_raw);
        usleep(100000); // 100ms delay
    }

    // Close I2C device
    close(file);
    return 0;
}

