#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig)
{
    terminate = 1;
}

int main()
{
    int value;
    int ret;

    /* Register signal handler */
    signal(SIGINT, signal_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request GPIO line for output */
    ret = gpiod_line_request_output(line, "digital_output", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop */
    while (!terminate) {
        printf("Enter GPIO value (0 or 1): ");
        if (scanf("%d", &value) != 1) {
            fprintf(stderr, "Invalid input. Please enter 0 or 1.\n");
            while (getchar() != '\n'); // Clear input buffer
            continue;
        }

        if (value != 0 && value != 1) {
            fprintf(stderr, "Invalid value. Please enter 0 or 1.\n");
            continue;
        }

        ret = gpiod_line_set_value(line, value);
        if (ret < 0) {
            perror("Error setting GPIO value");
            break;
        }

        printf("GPIO %d set to %d\n", GPIO_PIN, value);
        sleep(1);
    }

    /* Release GPIO line */
    gpiod_line_release(line);

    /* Close GPIO chip */
    gpiod_chip_close(chip);

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BMP280_ADDR 0x76
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_bmp280_temperature();
int read_bmp280_pressure();
int control_gpio(int value);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", sig);
    terminate = 1;
}

// Function to read temperature from BMP280 sensor
int read_bmp280_temperature() {
    unsigned char data[3];
    int temp_raw;
    float temperature;
    int retries = RETRY_COUNT;

    while (retries > 0) {
        // Read temperature registers (0xFA, 0xFB, 0xFC)
        if (i2c_smbus_read_i2c_block_data(i2c_fd, 0xFA, 3, (char *)data) == 3) {
            temp_raw = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);

            // Basic validity check: reasonable range (-50 to 85 degrees Celsius)
            if (temp_raw < -1000 || temp_raw > 10000) {
                fprintf(stderr, "Error: Invalid temperature reading: %d\n", temp_raw);
                return -1; // Indicate error
            }

            temperature = (float)temp_raw / 100.0; // Example conversion (adjust as needed)
            printf("Temperature: %.2f °C\n", temperature);
            return 0; // Success
        } else {
            fprintf(stderr, "Error: Failed to read temperature (attempt %d)\n", RETRY_COUNT - retries + 1);
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Delay before retrying
        }
    }

    fprintf(stderr, "Error: Failed to read temperature after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to read pressure from BMP280 sensor
int read_bmp280_pressure() {
    unsigned char data[3];
    int pressure_raw;
    float pressure;
    int retries = RETRY_COUNT;

    while (retries > 0) {
        // Read pressure registers (0xF7, 0xF8, 0xF9)
        if (i2c_smbus_read_i2c_block_data(i2c_fd, 0xF7, 3, (char *)data) == 3) {
            pressure_raw = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);

            // Basic validity check: reasonable range (300 to 1100 hPa)
            if (pressure_raw < 30000 || pressure_raw > 110000) {
                fprintf(stderr, "Error: Invalid pressure reading: %d\n", pressure_raw);
                return -1; // Indicate error
            }

            pressure = (float)pressure_raw / 100.0; // Example conversion (adjust as needed)
            printf("Pressure: %.2f hPa\n", pressure);
            return 0; // Success
        } else {
            fprintf(stderr, "Error: Failed to read pressure (attempt %d)\n", RETRY_COUNT - retries + 1);
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Delay before retrying
        }
    }

    fprintf(stderr, "Error: Failed to read pressure after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to control GPIO pin
int control_gpio(int value) {
    int ret;

    if (!gpio_line) {
        fprintf(stderr, "Error: GPIO line not initialized.\n");
        return -1;
    }

    ret = gpiod_line_set_value(gpio_line, value);
    if (ret < 0) {
        perror("Error setting GPIO value");
        return -1;
    }

    printf("GPIO %d set to %d\n", GPIO_PIN, value);
    return 0;
}

int main() {
    int ret;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(gpio_line, "bmp280_control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_bmp280_temperature() != 0) {
            fprintf(stderr, "Error reading temperature.\n");
        }
        if (read_bmp280_pressure() != 0) {
            fprintf(stderr, "Error reading pressure.\n");
        }

        // Control GPIO based on sensor readings (example: toggle every 5 seconds)
        static time_t last_toggle = 0;
        time_t now = time(NULL);
        if (now - last_toggle >= 5) {
            int current_value = gpiod_line_get_value(gpio_line);
            if (current_value < 0) {
                perror("Error getting current GPIO value");
            } else {
                if (control_gpio(!current_value) != 0) {
                    fprintf(stderr, "Error controlling GPIO.\n");
                }
                last_toggle = now;
            }
        }

        sleep(1); // Check every second
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <signal.h>
#include <errno.h>

// BME280 Registers
#define BME280_REG_TEMP_MSB 0xFA
#define BME280_REG_PRESSURE_MSB 0xF7
#define BME280_REG_HUMIDITY_MSB 0xFD
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CTRL_HUMIDITY 0xF2
#define BME280_REG_CONFIG 0xF5

// Calibration data registers
#define BME280_REG_CALIB_00 0x88

// Default I2C address of the BME280
#define BME280_I2C_ADDR 0x76

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Structure to hold calibration data
struct bme280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
    uint8_t dig_H1;
    int16_t dig_H2;
    uint8_t dig_H3;
    int16_t dig_H4;
    int16_t dig_H5;
    int8_t dig_H6;
};

struct bme280_calib_data calib;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from an I2C register
int i2c_read_reg(int fd, uint8_t reg_addr, uint8_t *data) {
    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return 0;
}

// Function to write a single byte to an I2C register
int i2c_write_reg(int fd, uint8_t reg_addr, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg_addr;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to register");
        return -1;
    }
    return 0;
}

// Function to read multiple bytes from an I2C register
int i2c_read_regs(int fd, uint8_t reg_addr, uint8_t *data, int len) {
    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read register values");
        return -1;
    }
    return 0;
}

// Function to initialize the BME280 sensor
int bme280_init(int fd) {
    // Set humidity oversampling to 1x
    if (i2c_write_reg(fd, BME280_REG_CTRL_HUMIDITY, 0x01) < 0) {
        fprintf(stderr, "Error writing to CTRL_HUMIDITY register\n");
        return -1;
    }

    // Set temperature and pressure oversampling to 1x and normal mode
    if (i2c_write_reg(fd, BME280_REG_CTRL_MEAS, 0x27) < 0) { //0b00100111
        fprintf(stderr, "Error writing to CTRL_MEAS register\n");
        return -1;
    }

    // Set inactive duration to 0.5ms
    if (i2c_write_reg(fd, BME280_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to CONFIG register\n");
        return -1;
    }

    return 0;
}

// Function to read calibration data from the BME280
int bme280_read_calibration_data(int fd, struct bme280_calib_data *cal) {
    uint8_t buffer[26];

    if (i2c_read_regs(fd, BME280_REG_CALIB_00, buffer, 26) < 0) {
        fprintf(stderr, "Error reading calibration data (first part)\n");
        return -1;
    }

    cal->dig_T1 = (uint16_t)(buffer[1] << 8 | buffer[0]);
    cal->dig_T2 = (int16_t)(buffer[3] << 8 | buffer[2]);
    cal->dig_T3 = (int16_t)(buffer[5] << 8 | buffer[4]);
    cal->dig_P1 = (uint16_t)(buffer[7] << 8 | buffer[6]);
    cal->dig_P2 = (int16_t)(buffer[9] << 8 | buffer[8]);
    cal->dig_P3 = (int16_t)(buffer[11] << 8 | buffer[10]);
    cal->dig_P4 = (int16_t)(buffer[13] << 8 | buffer[12]);
    cal->dig_P5 = (int16_t)(buffer[15] << 8 | buffer[14]);
    cal->dig_P6 = (int16_t)(buffer[17] << 8 | buffer[16]);
    cal->dig_P7 = (int16_t)(buffer[19] << 8 | buffer[18]);
    cal->dig_P8 = (int16_t)(buffer[21] << 8 | buffer[20]);
    cal->dig_P9 = (int16_t)(buffer[23] << 8 | buffer[22]);
    cal->dig_H1 = buffer[25];

    uint8_t buffer_h[7];
    if (i2c_read_regs(fd, 0xE1, buffer_h, 7) < 0) {
        fprintf(stderr, "Error reading calibration data (second part)\n");
        return -1;
    }

    cal->dig_H2 = (int16_t)(buffer_h[1] << 8 | buffer_h[0]);
    cal->dig_H3 = buffer_h[2];
    cal->dig_H4 = (int16_t)(buffer_h[3] << 4 | (buffer_h[4] & 0x0F));
    cal->dig_H5 = (int16_t)(buffer_h[5] << 4 | (buffer_h[4] >> 4));
    cal->dig_H6 = (int8_t)buffer_h[6];

    return 0;
}

// Function to read raw temperature, pressure, and humidity data
int bme280_read_raw_data(int fd, int32_t *temperature, int32_t *pressure, int32_t *humidity) {
    uint8_t buffer[8];

    if (i2c_read_regs(fd, BME280_REG_PRESSURE_MSB, buffer, 8) < 0) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *pressure = (int32_t)(((uint32_t)buffer[0] << 12) | ((uint32_t)buffer[1] << 4) | ((uint32_t)buffer[2] >> 4));
    *temperature = (int32_t)(((uint32_t)buffer[3] << 12) | ((uint32_t)buffer[4] << 4) | ((uint32_t)buffer[5] >> 4));
    *humidity = (int32_t)(((uint32_t)buffer[6] << 8) | (uint32_t)buffer[7]);

    return 0;
}

// Function to compensate temperature
float bme280_compensate_temperature(int32_t raw_temperature, struct bme280_calib_data cal, int32_t *t_fine) {
    float var1 = (raw_temperature / 16384.0 - cal.dig_T1 / 1024.0) * cal.dig_T2;
    float var2 = (raw_temperature / 131072.0 - cal.dig_T1 / 8192.0) * (raw_temperature / 131072.0 - cal.dig_T1 / 8192.0) * cal.dig_T3;
    *t_fine = (int32_t)(var1 + var2);
    float T = (*t_fine) / 5120.0;
    return T;
}

// Function to compensate pressure
float bme280_compensate_pressure(int32_t raw_pressure, struct bme280_calib_data cal, int32_t t_fine) {
    float var1 = (t_fine / 2.0) - 64000.0;
    float var2 = var1 * var1 * cal.dig_P6 / 32768.0;
    var2 = var2 + var1 * cal.dig_P5 * 2.0;
    var2 = (var2 / 4.0) + (cal.dig_P4 * 65536.0);
    var1 = (cal.dig_P3 * var1 * var1 / 524288.0 + cal.dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * cal.dig_P1;

    if (var1 == 0)
    {
        return 0;
    }

    float p = 1048576.0 - raw_pressure;
    p = (p - var2 / 4096.0) * 6250.0 / var1;
    var1 = cal.dig_P9 * p * p / 2147483648.0;
    var2 = p * cal.dig_P8 / 32768.0;
    p = p + (var1 + var2 + cal.dig_P7) / 16.0;
    return p/100.0; // in hPa
}

// Function to compensate humidity
float bme280_compensate_humidity(int32_t raw_humidity, struct bme280_calib_data cal, int32_t t_fine) {
    float var_H = (t_fine - 76800.0);
    var_H = (raw_humidity - (cal.dig_H4 * 64.0 + cal.dig_H5 / 16384.0 * var_H)) * (cal.dig_H2 / 65536.0 * (1.0 + cal.dig_H6 / 67108864.0 * var_H * (1.0 + cal.dig_H3 / 67108864.0 * var_H)));
    var_H = var_H * (1.0 - cal.dig_H1 * var_H / 524288.0);

    if (var_H > 100.0)
    {
        var_H = 100.0;
    } else if (var_H < 0.0)
    {
        var_H = 0.0;
    }
    return var_H;
}

int main() {
    const char *i2c_device = "/dev/i2c-1";
    int retries = 3;
    int delay_ms = 5000; // 5 seconds

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the BME280 sensor
    if (bme280_init(i2c_fd) < 0) {
        fprintf(stderr, "BME280 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Read calibration data
    if (bme280_read_calibration_data(i2c_fd, &calib) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop: read and print data every 5 seconds
    for (int i = 0; i < 3; ++i) {
        int32_t raw_temperature, raw_pressure, raw_humidity;
        int32_t t_fine;

        // Read raw data
        if (bme280_read_raw_data(i2c_fd, &raw_temperature, &raw_pressure, &raw_humidity) < 0) {
            fprintf(stderr, "Failed to read raw data\n");
            close(i2c_fd);
            return 1;
        }

        // Compensate data
        float temperature = bme280_compensate_temperature(raw_temperature, calib, &t_fine);
        float pressure = bme280_compensate_pressure(raw_pressure, calib, t_fine);
        float humidity = bme280_compensate_humidity(raw_humidity, calib, t_fine);

        // Print the results
        printf("Temperature: %.2f °C, Pressure: %.2f hPa, Humidity: %.2f %%\n", temperature, pressure, humidity);

        // Wait for 5 seconds
        usleep(delay_ms * 1000); // Convert milliseconds to microseconds
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig)
{
    terminate = 1;
}

int main()
{
    int ret;
    struct gpiod_line_request_config config;

    /* Register signal handler */
    signal(SIGINT, signal_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Configure line request */
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio-output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    /* Request GPIO line for output */
    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop */
    while (!terminate) {
        /* Set GPIO high */
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO high");
            break;
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN);
        sleep(1);

        /* Set GPIO low */
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO low");
            break;
        }
        printf("GPIO %d set to LOW\n", GPIO_PIN);
        sleep(1);
    }

    /* Release GPIO line */
    gpiod_line_release(line);

    /* Close GPIO chip */
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define VEML7700_ADDR 0x10

int i2c_fd;

void signal_handler(int sig);
int veml7700_read(unsigned int *als, unsigned int *uva, unsigned int *uvb);

void signal_handler(int sig) {
    printf("\nExiting...\n");
    close(i2c_fd);
    exit(0);
}

int veml7700_read(unsigned int *als, unsigned int *uva, unsigned int *uvb) {
    unsigned char data[6];
    if (read(i2c_fd, data, 6) != 6) {
        perror("Failed to read data");
        return -1;
    }

    *als = (data[1] << 8) | data[0];
    *uva = (data[3] << 8) | data[2];
    *uvb = (data[5] << 8) | data[4];

    return 0;
}

int main() {
    unsigned int als, uva, uvb;

    signal(SIGINT, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        if (veml7700_read(&als, &uva, &uvb) == 0) {
            printf("ALS: %u, UVA: %u, UVB: %u\n", als, uva, uvb);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }
        usleep(500000);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>

#define UART_PORT "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUD_RATE B9600
#define TIMEOUT_MS 100

volatile sig_atomic_t keep_running = 1;
int uart_fd = -1;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        keep_running = 0;
    }
}

int setup_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~PARENB; // No parity
    tty.c_cflag &= ~CSTOPB; // 1 stop bit
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8; // 8 data bits

    tty.c_lflag = 0; // Non-canonical mode
    tty.c_oflag = 0;
    tty.c_iflag = 0;

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = TIMEOUT_MS / 100; // Timeout in deciseconds

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    signal(SIGINT, signal_handler);

    uart_fd = setup_uart(UART_PORT);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    char buffer[256];
    ssize_t bytes_read;

    while (keep_running) {
        bytes_read = read(uart_fd, buffer, sizeof(buffer) - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            printf("Received: %s", buffer);
        } else if (bytes_read == -1) {
            if (errno != EAGAIN && errno != EWOULDBLOCK) {
                perror("Error reading from UART");
                break;
            }
        } else {
            // Timeout or no data
        }

        usleep(100000); // 0.1 seconds
    }

    close(uart_fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Speed of sound in cm/s
#define SPEED_OF_SOUND 34300.0

// Timeout duration in microseconds
#define TIMEOUT_US 500000 // 0.5 seconds

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to measure distance in centimeters
float get_distance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Measure echo pulse width
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        end_tick = gpioTick();
        diff_tick = end_tick - start_tick;
        if (diff_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for rising edge\n");
            return -1.0; // Indicate timeout error
        }
    }

    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        end_tick = gpioTick();
        diff_tick = end_tick - start_tick;
        if (diff_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for falling edge\n");
            return -1.0; // Indicate timeout error
        }
    }
    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    float time_taken_s = (float)diff_tick / 1000000.0; // Time in seconds
    float distance_cm = (time_taken_s * SPEED_OF_SOUND) / 2.0;

    return distance_cm;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float distance = get_distance();

        if (distance > 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: Invalid distance reading\n");
        }

        gpioDelay(500000); // Wait 0.5 seconds
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

