#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>

#define ADXL345_I2C_ADDR 0x53
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32

int main() {
    int file;
    char filename[20];
    int adxl345_address = ADXL345_I2C_ADDR;

    snprintf(filename, 19, "/dev/i2c-1"); // Standard I2C bus on Raspberry Pi

    file = open(filename, O_RDWR);
    if (file < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(file, I2C_SLAVE, adxl345_address) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return EXIT_FAILURE;
    }

    // Enable measurement mode
    uint8_t power_ctl_value = 0x08; // Set bit 3 to enable measurement
    if (write(file, &power_ctl_value, 1) != 1) {
        perror("Failed to write to ADXL345");
        close(file);
        return EXIT_FAILURE;
    }

    // Read accelerometer data
    uint8_t reg = ADXL345_REG_DATAX0;
    if (write(file, &reg, 1) != 1) {
        perror("Failed to write register address");
        close(file);
        return EXIT_FAILURE;
    }

    uint8_t buffer[6];
    if (read(file, buffer, 6) != 6) {
        perror("Failed to read from ADXL345");
        close(file);
        return EXIT_FAILURE;
    }

    // Combine high and low bytes for each axis
    int16_t x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z = (int16_t)((buffer[5] << 8) | buffer[4]);

    printf("X: %d, Y: %d, Z: %d\n", x, y, z);

    close(file);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"

static struct gpiod_chip *chip;
static struct gpiod_line *lines[8];
static int line_numbers[8] = {4, 17, 18, 22, 23, 24, 25, 27};
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig)
{
    terminate = 1;
}

int main()
{
    int i, ret;
    unsigned int value = 0;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get lines and set direction to output
    for (i = 0; i < 8; i++) {
        lines[i] = gpiod_chip_get_line(chip, line_numbers[i]);
        if (!lines[i]) {
            perror("Error getting GPIO line");
            goto cleanup;
        }

        ret = gpiod_line_request_output(lines[i], NULL, 0);
        if (ret < 0) {
            perror("Error setting GPIO line as output");
            goto cleanup;
        }
    }

    // Main loop
    while (!terminate) {
        // Set values on lines
        for (i = 0; i < 8; i++) {
            ret = gpiod_line_set_value(lines[i], (value >> i) & 1);
            if (ret < 0) {
                perror("Error setting GPIO line value");
                goto cleanup;
            }
        }

        // Print current state
        printf("GPIOs: ");
        for (i = 0; i < 8; i++) {
            printf("%d", (value >> i) & 1);
        }
        printf("\n");

        // Increment value
        value = (value + 1) % 256;

        // Wait 50ms
        usleep(50000);
    }

cleanup:
    // Release lines and close chip
    for (i = 0; i < 8; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_FAILURE;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_27 27

static volatile int keep_running = 1;
struct gpiod_chip *chip;
struct gpiod_line *line4, *line17, *line27;

void sigint_handler(int sig)
{
    keep_running = 0;
}

int main()
{
    struct gpiod_line_request_config config;
    int ret;

    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Open chip failed");
        return 1;
    }

    line4 = gpiod_chip_get_line(chip, GPIO_4);
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    line27 = gpiod_chip_get_line(chip, GPIO_27);

    if (!line4 || !line17 || !line27) {
        perror("Get line failed");
        goto cleanup_chip;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "digital_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(line4, &config, 0) < 0 ||
        gpiod_line_request(line17, &config, 0) < 0 ||
        gpiod_line_request(line27, &config, 0) < 0) {
        perror("Request line as output failed");
        goto cleanup_lines;
    }

    while (keep_running) {
        ret = gpiod_line_set_value(line4, 1);
        ret |= gpiod_line_set_value(line17, 0);
        ret |= gpiod_line_set_value(line27, 1);
        if (ret < 0) {
            perror("Set value failed");
            break;
        }
        printf("GPIO %d: HIGH, GPIO %d: LOW, GPIO %d: HIGH\n", GPIO_4, GPIO_17, GPIO_27);
        sleep(0.5);

        ret = gpiod_line_set_value(line4, 0);
        ret |= gpiod_line_set_value(line17, 1);
        ret |= gpiod_line_set_value(line27, 0);
        if (ret < 0) {
            perror("Set value failed");
            break;
        }
        printf("GPIO %d: LOW, GPIO %d: HIGH, GPIO %d: LOW\n", GPIO_4, GPIO_17, GPIO_27);
        sleep(0.5);
    }

cleanup_lines:
    gpiod_line_release(line4);
    gpiod_line_release(line17);
    gpiod_line_release(line27);

cleanup_chip:
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
