#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_bmp280(int fd, float *temperature);
int control_gpio(struct gpiod_line *line, int value);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", sig);
    terminate = 1;
}

// Function to read temperature from BMP280 sensor
int read_bmp280(int fd, float *temperature) {
    unsigned char data[6];
    int retries = RETRY_COUNT;
    int result;

    while (retries > 0) {
        // Read 6 bytes of data starting from register 0xF7 (pressure MSB)
        if (write(fd, "\xF7", 1) != 1) {
            perror("Failed to write to I2C device");
            return -1;
        }
        if (read(fd, data, 6) != 6) {
            perror("Failed to read from I2C device");
            usleep(RETRY_DELAY_MS * 1000); // Wait before retrying
            retries--;
            continue;
        }

        // Combine pressure and temperature data
        long pressure_raw = (long)data[0] << 12 | (long)data[1] << 4 | (long)data[2] >> 4;
        long temperature_raw = (long)data[3] << 12 | (long)data[4] << 4 | (long)data[5] >> 4;

        // Dummy conversion (replace with actual BMP280 conversion formula)
        *temperature = (float)temperature_raw / 100.0;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read BMP280 after multiple retries.\n");
    return -1; // Failure
}

// Function to control GPIO pin
int control_gpio(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Failed to set GPIO value");
        return -1;
    }
    return 0;
}

int main() {
    float temperature;
    int gpio_value = 0;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Get GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "bmp280_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Read temperature from BMP280
        if (read_bmp280(i2c_fd, &temperature) == 0) {
            printf("Temperature: %.2f °C\n", temperature);

            // Control GPIO based on temperature
            if (temperature > 25.0) {
                gpio_value = 1;
            } else {
                gpio_value = 0;
            }

            if (control_gpio(gpio_line, gpio_value) == 0) {
                printf("GPIO %d set to %d\n", GPIO_PIN, gpio_value);
            } else {
                fprintf(stderr, "Failed to control GPIO.\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        sleep(1); // Wait for 1 second
    }

    // Cleanup
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

