#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to measure distance in centimeters
float getDistance()
{
    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Measure echo pulse width
    uint32_t start_tick = 0;
    uint32_t end_tick = 0;

    // Wait for echo to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < 10000) // Timeout after ~10ms
    {
        if (count == 0) {
            start_tick = gpioTick();
        }
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= 10000) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1.0; // Indicate error
    }

    // Wait for echo to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < 50000) // Timeout after ~50ms
    {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= 50000) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1.0; // Indicate error
    }

    end_tick = gpioTick();

    // Calculate pulse width in microseconds
    uint32_t pulse_width = end_tick - start_tick;

    // Calculate distance in centimeters (speed of sound: 343 m/s)
    float distance = (pulse_width / 1000000.0) * 34300.0 / 2.0;

    return distance;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate)
    {
        float distance = getDistance();

        if (distance >= 0.0)
        {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(100); // Delay between measurements
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

