#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

// TCS34725 Registers
#define TCS34725_ADDRESS         (0x29)
#define TCS34725_COMMAND_BIT     (0x80)
#define TCS34725_ENABLE          (0x00)
#define TCS34725_ATIME           (0x01)
#define TCS34725_WTIME           (0x03)
#define TCS34725_AILTL           (0x04)
#define TCS34725_AILTH           (0x05)
#define TCS34725_AIHTL           (0x06)
#define TCS34725_AIHTH           (0x07)
#define TCS34725_ID              (0x12)
#define TCS34725_STATUS          (0x13)
#define TCS34725_CDATA           (0x14)
#define TCS34725_RDATA           (0x16)
#define TCS34725_GDATA           (0x18)
#define TCS34725_BDATA           (0x1A)

// Enable Register Values
#define TCS34725_ENABLE_PON      (0x01)
#define TCS34725_ENABLE_AEN      (0x02)
#define TCS34725_ENABLE_AIEN     (0x10)
#define TCS34725_ENABLE_WEN      (0x08)
#define TCS34725_ENABLE_AEN_ENAIEN (TCS34725_ENABLE_AEN | TCS34725_ENABLE_AIEN)

// Integration Time
#define TCS34725_INTEGRATIONTIME_2_4MS  (0xFF)   // 2.4ms - 1 cycle    - Max Count: 1024
#define TCS34725_INTEGRATIONTIME_24MS   (0xF6)   // 24ms  - 10 cycles   - Max Count: 10240
#define TCS34725_INTEGRATIONTIME_50MS   (0xEB)   // 50ms  - 20 cycles   - Max Count: 20480
#define TCS34725_INTEGRATIONTIME_101MS  (0xD5)   // 101ms - 42 cycles   - Max Count: 42240
#define TCS34725_INTEGRATIONTIME_154MS  (0xC0)   // 154ms - 64 cycles   - Max Count: 65535
#define TCS34725_INTEGRATIONTIME_238MS  (0xA0)   // 238ms - 98 cycles   - Max Count: 65535

// Gain
#define TCS34725_GAIN_1X           (0x00)   // No gain
#define TCS34725_GAIN_4X           (0x01)   // 4x gain
#define TCS34725_GAIN_16X          (0x02)   // 16x gain
#define TCS34725_GAIN_60X          (0x03)   // 60x gain

int i2c_fd;
volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    keep_running = 0;
}

int tcs34725_write_byte(uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg | TCS34725_COMMAND_BIT;
    buffer[1] = value;
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int tcs34725_read_byte(uint8_t reg, uint8_t *value) {
    uint8_t buffer[1];
    buffer[0] = reg | TCS34725_COMMAND_BIT;
    if (write(i2c_fd, buffer, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(i2c_fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

int tcs34725_read_word(uint8_t reg, uint16_t *value) {
    uint8_t buffer[1];
    uint8_t data[2];

    buffer[0] = reg | TCS34725_COMMAND_BIT;
    if (write(i2c_fd, buffer, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read word from I2C device");
        return -1;
    }

    *value = (data[1] << 8) | data[0];
    return 0;
}

int tcs34725_init() {
    uint8_t id;

    // Check device ID
    if (tcs34725_read_byte(TCS34725_ID, &id) < 0) {
        fprintf(stderr, "Error reading TCS34725 ID\n");
        return -1;
    }

    if (id != 0x44) {
        fprintf(stderr, "Incorrect TCS34725 ID: 0x%02X\n", id);
        return -1;
    }

    // Enable power and ALS
    if (tcs34725_write_byte(TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0) {
        fprintf(stderr, "Error enabling power\n");
        return -1;
    }
    usleep(3); // Wait for power-on (datasheet)

    if (tcs34725_write_byte(TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) {
        fprintf(stderr, "Error enabling ALS\n");
        return -1;
    }

    // Set integration time
    if (tcs34725_write_byte(TCS34725_ATIME, TCS34725_INTEGRATIONTIME_24MS) < 0) {
        fprintf(stderr, "Error setting integration time\n");
        return -1;
    }

    // Set gain
    if (tcs34725_write_byte(0x0F, TCS34725_GAIN_1X) < 0) {
        fprintf(stderr, "Error setting gain\n");
        return -1;
    }

    return 0;
}

int main() {
    const char *i2c_device = "/dev/i2c-1";
    uint16_t clear, red, green, blue;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize TCS34725
    if (tcs34725_init() < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("TCS34725 initialized successfully.\n");

    while (keep_running) {
        // Read color data
        if (tcs34725_read_word(TCS34725_CDATA, &clear) < 0 ||
            tcs34725_read_word(TCS34725_RDATA, &red) < 0 ||
            tcs34725_read_word(TCS34725_GDATA, &green) < 0 ||
            tcs34725_read_word(TCS34725_BDATA, &blue) < 0) {
            fprintf(stderr, "Error reading color data\n");
            break; // Exit loop on error
        }

        // Print color data
        printf("Clear: %5u, Red: %5u, Green: %5u, Blue: %5u\n", clear, red, green, blue);

        usleep(500000); // 0.5 seconds
    }

    // Close I2C device
    close(i2c_fd);
    printf("Program terminated.\n");

    return EXIT_SUCCESS;
}

