#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 18
#define ECHO_PIN 23

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *trigger_line = NULL;
struct gpiod_line *echo_line = NULL;
struct gpiod_chip *chip = NULL;

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to measure distance in centimeters
float measure_distance()
{
    struct timespec start_time, end_time;
    long long start_ns, end_ns, diff_ns;
    int timeout_us = 500000; // 0.5 seconds timeout
    int i;

    // Trigger the sensor
    gpiod_line_set_value(trigger_line, 0);
    usleep(2);
    gpiod_line_set_value(trigger_line, 1);
    usleep(10);
    gpiod_line_set_value(trigger_line, 0);

    // Wait for echo to go high with timeout
    clock_gettime(CLOCK_MONOTONIC, &start_time);
    for (i = 0; i < timeout_us; ++i) {
        if (gpiod_line_get_value(echo_line) == 1) {
            break;
        }
        usleep(1);
    }
    if (i >= timeout_us) {
        fprintf(stderr, "Error: Echo pin did not go high within timeout.\n");
        return -1.0;
    }
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    // Measure echo pulse width
    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end_time);
        end_ns = end_time.tv_sec * 1000000000LL + end_time.tv_nsec;
        start_ns = start_time.tv_sec * 1000000000LL + start_time.tv_nsec;
        diff_ns = end_ns - start_ns;
        if (diff_ns > timeout_us * 1000) {
            fprintf(stderr, "Error: Echo pin did not go low within timeout.\n");
            return -1.0;
        }
    }
    clock_gettime(CLOCK_MONOTONIC, &end_time);

    // Calculate pulse width in nanoseconds
    start_ns = start_time.tv_sec * 1000000000LL + start_time.tv_nsec;
    end_ns = end_time.tv_sec * 1000000000LL + end_time.tv_nsec;
    diff_ns = end_ns - start_ns;

    // Calculate distance in centimeters
    float distance = (float)diff_ns / 58.0;

    return distance;
}

int main()
{
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trigger_line || !echo_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output and input
    if (gpiod_line_request_output(trigger_line, "hc-sr04-trigger", 0) < 0) {
        perror("Error requesting trigger line as output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_input(echo_line, "hc-sr04-echo") < 0) {
        perror("Error requesting echo line as input");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Measure distance
    float distance = measure_distance();

    // Print distance
    if (distance >= 0) {
        printf("Distance: %.2f cm\n", distance);
    } else {
        fprintf(stderr, "Error: Could not measure distance.\n");
    }

    // Release GPIO lines
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

