#include <pigpio.h>

#define GPIO_PIN 18

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

int main() {
    int rc;
    int current_state = 0; // Initial state: LOW
    time_t start_time, current_time;
    double elapsed_time;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Seed the random number generator
    srand(time(NULL));

    time(&start_time);

    while (!terminate) {
        // Generate a random number (0 or 1)
        int new_state = rand() % 2;

        // Apply the new state to the GPIO pin
        gpioWrite(GPIO_PIN, new_state);

        // Print the current state to stdout
        printf("GPIO %d set to %d\n", GPIO_PIN, new_state);

        // Check validity of the reading (simulated)
        if (new_state != 0 && new_state != 1) {
            fprintf(stderr, "Error: Invalid state read from GPIO %d\n", GPIO_PIN);
            gpioTerminate();
            return 1;
        }

        // Check for timeout (5 seconds)
        time(&current_time);
        elapsed_time = difftime(current_time, start_time);

        if (elapsed_time >= 5.0) {
            fprintf(stderr, "Timeout: No valid readings received for 5 seconds.\n");
            break; // Exit the loop after timeout
        }

        // Wait for 1 second
        sleep(1);
    }

    // Release GPIO resources before exiting
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

