#include <pigpio.h>
#include <unistd.h>

#define PWM_GPIO 18

void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioPWM(PWM_GPIO, 0); // Stop PWM
    gpioTerminate();       // Terminate pigpio
    printf("Cleaned up. Exiting.\n");
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    while (1) {
        gpioPWM(PWM_GPIO, 128); // 50% duty cycle (128/255)
        printf("PWM set to 50%%\n");
        sleep(0.2);

        gpioPWM(PWM_GPIO, 64);  // 25% duty cycle (64/255)
        printf("PWM set to 25%%\n");
        sleep(0.2);
    }

    return 0; // This will never be reached due to the infinite loop.
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define GPIO_17 17
#define GPIO_18 18

static struct gpiod_chip *chip;
static struct gpiod_line *line17, *line18;

void cleanup(int signum) {
    printf("\nCleaning up and exiting...\n");
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_release(line18);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    line18 = gpiod_chip_get_line(chip, GPIO_18);

    if (!line17 || !line18) {
        perror("Error getting GPIO line");
        cleanup(0);
        return 1;
    }

    if (gpiod_line_request_output(line17, NULL, 0) < 0) {
        perror("Error requesting GPIO 17 as output");
        cleanup(0);
        return 1;
    }

    if (gpiod_line_request_output(line18, NULL, 1) < 0) {
        perror("Error requesting GPIO 18 as output");
        cleanup(0);
        return 1;
    }

    printf("GPIO %d set to LOW\n", GPIO_17);
    printf("GPIO %d set to HIGH\n", GPIO_18);

    cleanup(0);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_18 18
#define GPIO_23 23
#define GPIO_24 24

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int result;

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set GPIO modes */
    gpioSetMode(GPIO_18, PI_OUTPUT);
    gpioSetMode(GPIO_23, PI_OUTPUT);
    gpioSetMode(GPIO_24, PI_OUTPUT);

    /* Register signal handler */
    signal(SIGINT, signal_handler);

    while (!terminate) {
        /* Toggle GPIO 18 HIGH */
        result = gpioWrite(GPIO_18, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing to GPIO %d: %d\n", GPIO_18, result);
            break;
        }
        printf("GPIO %d: HIGH\n", GPIO_18);
        gpioDelay(100000); // 0.1 seconds

        /* Toggle GPIO 23 LOW */
        result = gpioWrite(GPIO_23, 0);
        if (result != 0) {
            fprintf(stderr, "Error writing to GPIO %d: %d\n", GPIO_23, result);
            break;
        }
        printf("GPIO %d: LOW\n", GPIO_23);
        gpioDelay(100000); // 0.1 seconds

        /* Toggle GPIO 24 HIGH */
        result = gpioWrite(GPIO_24, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing to GPIO %d: %d\n", GPIO_24, result);
            break;
        }
        printf("GPIO %d: HIGH\n", GPIO_24);
        gpioDelay(100000); // 0.1 seconds

        /* Toggle GPIO 18 LOW */
        result = gpioWrite(GPIO_18, 0);
        if (result != 0) {
            fprintf(stderr, "Error writing to GPIO %d: %d\n", GPIO_18, result);
            break;
        }
        printf("GPIO %d: LOW\n", GPIO_18);
        gpioDelay(100000); // 0.1 seconds

        /* Toggle GPIO 23 HIGH */
        result = gpioWrite(GPIO_23, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing to GPIO %d: %d\n", GPIO_23, result);
            break;
        }
        printf("GPIO %d: HIGH\n", GPIO_23);
        gpioDelay(100000); // 0.1 seconds

        /* Toggle GPIO 24 LOW */
        result = gpioWrite(GPIO_24, 0);
        if (result != 0) {
            fprintf(stderr, "Error writing to GPIO %d: %d\n", GPIO_24, result);
            break;
        }
        printf("GPIO %d: LOW\n", GPIO_24);
        gpioDelay(100000); // 0.1 seconds
    }

    /* Release GPIOs */
    gpioSetMode(GPIO_18, PI_INPUT);
    gpioSetMode(GPIO_23, PI_INPUT);
    gpioSetMode(GPIO_24, PI_INPUT);

    /* Terminate pigpio library */
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

// MPU6050 Registers
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

int i2c_fd = -1; // Global file descriptor for I2C

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from an I2C register
int i2c_read_byte(int fd, uint8_t reg_addr, uint8_t *data) {
    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, 1) != 1) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// Function to write a single byte to an I2C register
int i2c_write_byte(int fd, uint8_t reg_addr, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg_addr;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

int main() {
    const char *i2c_device = "/dev/i2c-1"; // I2C device file
    uint8_t buffer[14]; // Buffer to hold accelerometer and gyroscope data
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU6050 (set sleep bit to 0)
    if (i2c_write_byte(i2c_fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up MPU6050\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read accelerometer and gyroscope data
        if (write(i2c_fd, &(uint8_t){ACCEL_XOUT_H}, 1) != 1) {
            perror("Failed to write register address for read");
            close(i2c_fd);
            return 1;
        }
        if (read(i2c_fd, buffer, 14) != 14) {
            perror("Failed to read sensor data");
            close(i2c_fd);
            return 1;
        }

        // Combine high and low bytes for accelerometer data
        accel_x = (buffer[0] << 8) | buffer[1];
        accel_y = (buffer[2] << 8) | buffer[3];
        accel_z = (buffer[4] << 8) | buffer[5];

        // Combine high and low bytes for gyroscope data
        gyro_x = (buffer[8] << 8) | buffer[9];
        gyro_y = (buffer[10] << 8) | buffer[11];
        gyro_z = (buffer[12] << 8) | buffer[13];

        // Print the raw sensor values
        printf("AccelX: %d, AccelY: %d, AccelZ: %d, GyroX: %d, GyroY: %d, GyroZ: %d\n",
               accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        gpioWrite(GPIO_PIN, 1);
        printf("GPIO %d set to HIGH\n", GPIO_PIN);
        gpioDelay(600000); // 0.6 seconds

        gpioWrite(GPIO_PIN, 0);
        printf("GPIO %d set to LOW\n", GPIO_PIN);
        gpioDelay(600000); // 0.6 seconds
    }

    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}
